const PROTECTED_CORE_PUBLIC_HOSTS = new Set([
  "token-depot.co",
  "www.token-depot.co",
  "wallets.token-depot.co",
  "token-depot.com",
  "www.token-depot.com",
  "wallets.token-depot.com",
  "localhost",
  "127.0.0.1",
  "::1"
]);

function normalizePublicRequestHost(req: express.Request): string {
  const headerHost = Array.isArray(req.headers.host)
    ? String(req.headers.host[0] || "")
    : String(req.headers.host || "");

  let raw = typeof req.hostname === "string" && req.hostname.trim()
    ? req.hostname.trim().toLowerCase()
    : headerHost.trim().toLowerCase();

  if (!raw) return "";

  if (!raw.startsWith("[") && raw.includes(":") && raw.indexOf(":") === raw.lastIndexOf(":")) {
    raw = raw.slice(0, raw.indexOf(":"));
  }

  while (raw.endsWith(".")) {
    raw = raw.slice(0, -1);
  }

  return raw;
}

function isProtectedCorePublicHost(normalizedHost: string): boolean {
  return !!normalizedHost && PROTECTED_CORE_PUBLIC_HOSTS.has(normalizedHost);
}

type BrokerPublicPageName = "index" | "login" | "agency-reseller-kit";

function readBrokerPublicPageSkinId(): PublicPageSkinId {
  const cfg = readWrappedConfigV7(repoRoot);
  return normalizePublicPageSkinId(cfg.publicSite?.publicPageSkinId);
}

function sendRepoRootPublicPage(res: express.Response, pageName: BrokerPublicPageName) {
  const fileName = `${pageName}.html`;
  const filePath = path.join(repoRoot, fileName);
  const html = fs.readFileSync(filePath, "utf8");
  const skinId = readBrokerPublicPageSkinId();
  const anchor = '<body data-skin="classic_teal">';
  const replacement = `<body data-skin="${skinId}">`;

  if (!html.includes(anchor)) {
    throw new Error(`broker_public_skin_body_anchor_missing:${fileName}`);
  }

  return res.type("html").send(html.replace(anchor, replacement));
}

function sendTenantShellUnavailablePage(res: express.Response) {
  return res
    .status(503)
    .type("html")
    .send(`<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Site Unavailable</title>
</head>
<body>
  <main>
    <h1>Site Unavailable</h1>
    <p>Please see website administrator.</p>
  </main>
</body>
</html>`);
}

type TenantShellContextResponse =
  | {
      ok: true;
      host: string;
      matched: false;
    }
  | {
      ok: true;
      host: string;
      matched: true;
      tenant_id: string;
      tenant_slug: string;
      status: string;
      primary_domain: string;
      branding_id: string | null;
      signup_notify_email?: string | null;
      branding_status: string;
    }
  | {
      ok: false;
      reason: string;
      error?: string;
    };

async function fetchTenantShellContext(normalizedHost: string): Promise<TenantShellContextResponse> {
  const adminToken = String(process.env.TD_ADMIN_TOKEN || "").trim();
  if (!adminToken) {
    return { ok: false, reason: "admin_token_missing" };
  }

  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), getAppConfig(repoRoot).cn_timeout_ms);

  try {
    const url = `${cnBaseUrl(repoRoot)}/api/cn/tenant-shell-context?host=${encodeURIComponent(normalizedHost)}`;
    const r = await fetch(url, {
      headers: {
        Accept: "application/json",
        "x-td-admin-token": adminToken
      },
      signal: controller.signal
    });

    const data = await r.json().catch(() => null);
    if (!r.ok || !data || typeof data !== "object") {
      return {
        ok: false,
        reason: "tenant_shell_context_fetch_failed",
        error: r.statusText || `http_${r.status}`
      };
    }

    return data as TenantShellContextResponse;
  } catch (err) {
    const e = err instanceof Error ? err : new Error(String(err));
    const reason = e.name === "AbortError" ? "tenant_shell_context_timeout" : "tenant_shell_context_fetch_failed";
    return {
      ok: false,
      reason,
      error: e.message
    };
  } finally {
    clearTimeout(timeout);
  }
}

async function resolveSignupTenantFromRequest(req: express.Request): Promise<SignupTenantResolution> {
  const normalizedHost = normalizePublicRequestHost(req);
  if (!normalizedHost || isProtectedCorePublicHost(normalizedHost)) {
    return { ok: true, tenant_id: null };
  }

  const shellContext = await fetchTenantShellContext(normalizedHost);
  if (!shellContext.ok) {
    return { ok: false, status: 503, reason: shellContext.reason || "tenant_shell_context_failed" };
  }

  if (!shellContext.matched) {
    return { ok: true, tenant_id: null };
  }

  if (String(shellContext.status || "").trim().toLowerCase() !== "active") {
    return { ok: false, status: 403, reason: "tenant_not_active" };
  }

  if (shellContext.branding_status !== "ready" || !shellContext.branding_id) {
    return { ok: false, status: 503, reason: "tenant_shell_not_ready" };
  }

  return {
    ok: true,
    tenant_id: shellContext.tenant_id,
    tenant_signup_notify_email: shellContext.signup_notify_email || null
  };
}

async function servePublicEntryPage(req: express.Request, res: express.Response, next: express.NextFunction, pageName: "index" | "login") {
  try {
    const normalizedHost = normalizePublicRequestHost(req);
    if (!normalizedHost || isProtectedCorePublicHost(normalizedHost)) {
      return sendRepoRootPublicPage(res, pageName);
    }

    const shellContext = await fetchTenantShellContext(normalizedHost);
    if (!shellContext.ok) {
      return sendTenantShellUnavailablePage(res);
    }

    if (!shellContext.matched) {
      return sendRepoRootPublicPage(res, pageName);
    }

    if (shellContext.branding_status !== "ready" || !shellContext.branding_id) {
      return sendTenantShellUnavailablePage(res);
    }

    const resolved = resolveTenantPublicShellPageStrict(repoRoot, shellContext.branding_id, pageName);
    return res.sendFile(resolved.filePath);
  } catch (err) {
    const msg = String(err instanceof Error ? err.message : err);
    if (
      msg === "tenant_shell_pack_branding_invalid" ||
      msg.startsWith("tenant_shell_pack_missing:") ||
      msg.startsWith("tenant_shell_pack_public_page_missing:")
    ) {
      return sendTenantShellUnavailablePage(res);
    }
    return next(err);
  }
}

async function serveAuthenticatedAppPage(req: express.Request, res: express.Response, next: express.NextFunction, pageName: AppShellPageName) {
  try {
    const normalizedHost = normalizePublicRequestHost(req);
    if (!normalizedHost || isProtectedCorePublicHost(normalizedHost)) {
      return res.sendFile(path.join(repoRoot, `${pageName}.html`));
    }

    const shellContext = await fetchTenantShellContext(normalizedHost);
    if (!shellContext.ok) {
      return sendTenantShellUnavailablePage(res);
    }

    if (!shellContext.matched) {
      return res.sendFile(path.join(repoRoot, `${pageName}.html`));
    }

    if (shellContext.branding_status !== "ready" || !shellContext.branding_id) {
      return sendTenantShellUnavailablePage(res);
    }

    const resolved = resolveTenantAppShellPageStrict(repoRoot, shellContext.branding_id, pageName);
    return res.sendFile(resolved.filePath);
  } catch (err) {
    const msg = String(err instanceof Error ? err.message : err);
    if (
      msg === "tenant_shell_pack_branding_invalid" ||
      msg.startsWith("tenant_shell_pack_missing:") ||
      msg.startsWith("tenant_shell_pack_app_page_missing:")
    ) {
      return sendTenantShellUnavailablePage(res);
    }
    return next(err);
  }
}

const requireUserHtml: express.RequestHandler = (req, res, next) => {
  const userId = readSessionUserId(req, sessionCfg);
  if (!userId) return res.redirect("/login.html");

  const state = readUserState(repoRoot, userId);
  if (state.account_frozen) {
    clearSessionUserId(res, sessionCfg);
    return res.redirect("/login.html");
  }

  (res.locals as any).td_user_id = userId;
  return next();
};

const requireLicensedMainnetHtml: express.RequestHandler = (req, res, next) => {
  const userId = (res.locals as any).td_user_id;
  const uid = typeof userId === "string" ? userId : "";
  if (!uid) return res.redirect("/login.html");

  const store = readWalletStore(repoRoot, uid);
  const active = store.active_id ? store.items.find((w) => w.id === store.active_id) ?? null : null;
  if (!active) return next();

  const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
  const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
  if (networkId !== "mainnet") return next();

  requireMainnetLicenseOrReject({ networkId: "mainnet", userId: uid })
    .then((lic) => {
      if (lic.ok) return next();
      return res.redirect("/wallet.html?tdpro_license_required=1");
    })
    .catch(next);
};

