const requireActiveUserMw: express.RequestHandler = (req, res, next) => {
  const userId = readSessionUserId(req, sessionCfg);
  if (!userId) {
    return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
  }

  const state = readUserState(repoRoot, userId);
  if (state.account_frozen) {
    clearSessionUserId(res, sessionCfg);
    return res.status(401).json({ ok: false, reason: "account_frozen", login: "/login.html" });
  }

  (res.locals as any).td_user_id = userId;
  return next();
};

const requireUserApiMw: express.RequestHandler = (req, res, next) => {
  if (req.path === "/v1/wrapped-config") return next();
  if (req.path.startsWith("/v1/bridge/admin/")) return next();
  if (req.path.startsWith("/v1/sponsored-offers/admin/")) return next();
  if (req.path.startsWith("/v1/entitlement-token-settings/admin/")) return next();
  return requireActiveUserMw(req, res, next);
};
