type ProgrammableKasImmediateRecoveryStore = {
  schema_kind: "programmable_kas_immediate_recovery_locks_v1";
  schema_version: 1;
  records: ProgrammableKasImmediateRecoveryRecord[];
};

const PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_FILE_NAME = "programmable-kas-immediate-recovery-locks.v1.json";
const PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_SCHEMA_KIND = "programmable_kas_immediate_recovery_locks_v1";

function programmableKasImmediateRecoveryLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_FILE_NAME);
}

function emptyProgrammableKasImmediateRecoveryLockStore(): ProgrammableKasImmediateRecoveryStore {
  return { schema_kind: PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readProgrammableKasImmediateRecoveryLockStore(repoRootPath: string, userId: string): ProgrammableKasImmediateRecoveryStore {
  const p = programmableKasImmediateRecoveryLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyProgrammableKasImmediateRecoveryLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyProgrammableKasImmediateRecoveryLockStore();

  return {
    schema_kind: PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeProgrammableKasImmediateRecoveryLockStore(repoRootPath: string, userId: string, store: ProgrammableKasImmediateRecoveryStore): void {
  const p = programmableKasImmediateRecoveryLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertProgrammableKasImmediateRecoveryLockRecord(repoRootPath: string, userId: string, record: ProgrammableKasImmediateRecoveryRecord): void {
  const store = readProgrammableKasImmediateRecoveryLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const recoveryAddress = String(record.recovery_address || "").trim();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const sameRecovery = String(existing?.recovery_address || "").trim() === recoveryAddress;
    return !(sameSource && sameCovenant && sameRecovery);
  });

  writeProgrammableKasImmediateRecoveryLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function programmableKasImmediateRecoveryLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function markProgrammableKasImmediateRecoveryLockRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  expectedCovenantId: string,
  patch: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasImmediateRecoveryRecord | null {
  const store = readProgrammableKasImmediateRecoveryLockStore(repoRootPath, userId);
  const normalizedSource = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasImmediateRecoveryRecord | null = null;

  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === normalizedSource;
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === normalizedCovenantId;
    if (!sameSource || !sameCovenant) return record;

    updatedRecord = {
      ...record,
      record_status: patch.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: patch.release_status,
      release_txid: patch.release_txid,
      release_amount_sompi: patch.release_amount_sompi,
      release_amount_kas: patch.release_amount_kas,
      released_output_outpoint: patch.released_output_outpoint
    } as ProgrammableKasImmediateRecoveryRecord;
    return updatedRecord;
  });

  if (updatedRecord) {
    writeProgrammableKasImmediateRecoveryLockStore(repoRootPath, userId, {
      schema_kind: PROGRAMMABLE_KAS_IMMEDIATE_RECOVERY_LOCKS_SCHEMA_KIND,
      schema_version: 1,
      records
    });
  }

  return updatedRecord;
}

function programmableKasImmediateRecoveryViewerRole(record: any, viewerAddress: string): "owner" | "recovery" | null {
  const viewer = String(viewerAddress || "").trim();
  if (!viewer) return null;
  if (String(record?.owner_address || "").trim() === viewer) return "owner";
  if (String(record?.recovery_address || "").trim() === viewer) return "recovery";
  return null;
}

function programmableKasImmediateRecoveryRecordVisibleToWallet(record: any, viewerAddress: string): boolean {
  return programmableKasImmediateRecoveryViewerRole(record, viewerAddress) !== null;
}

function programmableKasImmediateRecoverySafeRecord(record: ProgrammableKasImmediateRecoveryRecord, viewerAddress?: string): any {
  const viewerRole = viewerAddress ? programmableKasImmediateRecoveryViewerRole(record, viewerAddress) : null;
  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    viewer_role: viewerRole,
    participant_filter: "owner_or_recovery_wallet_only",
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    owner_address: record.owner_address,
    owner_address_source: record.owner_address_source,
    owner_public_key_sha256: record.owner_public_key_sha256,
    recovery_address: record.recovery_address,
    recovery_address_version: record.recovery_address_version,
    recovery_public_key_sha256: record.recovery_public_key_sha256,
    recovery_address_matches_owner: record.recovery_address_matches_owner,
    p2sh_immediate_recovery_address: record.p2sh_immediate_recovery_address,
    p2sh_immediate_recovery_redeem_script_sha256: record.p2sh_immediate_recovery_redeem_script_sha256,
    p2sh_immediate_recovery_redeem_script_byte_len: record.p2sh_immediate_recovery_redeem_script_byte_len,
    p2sh_immediate_recovery_redeem_script_push_limit_bytes: record.p2sh_immediate_recovery_redeem_script_push_limit_bytes,
    p2sh_immediate_recovery_redeem_script_pushable: record.p2sh_immediate_recovery_redeem_script_pushable,
    p2sh_immediate_recovery_script_public_key_json_sha256: record.p2sh_immediate_recovery_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}




