function programmableKasOwnerReleaseDelayedRecoveryPolicyForOwnerRecoveryAndLock(
  ownerAddress: string,
  networkId: string,
  recoveryAddress: string,
  recoveryLockTargetDaa: bigint
): ProgrammableKasOwnerReleaseDelayedRecoveryPolicy | null {
  try {
    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const recoveryAddressObject = new Address(recoveryAddress);
    const recoveryAddressVersion = String(recoveryAddressObject.version || "");
    const recoveryXOnlyPublicKey = XOnlyPublicKey.fromAddress(recoveryAddressObject as any);
    const recoveryXOnlyPublicKeyHex = recoveryXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(recoveryXOnlyPublicKeyHex)) return null;

    const recoveryAddressFromPublicKey = recoveryXOnlyPublicKey.toAddress(networkId as any).toString();
    if (recoveryAddressFromPublicKey !== recoveryAddress) return null;

    const c6ScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addOp(Opcodes.OpDup)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpIf)
      .addOp(Opcodes.OpDrop)
      .addOp(Opcodes.OpTrue)
      .addOp(Opcodes.OpElse)
      .addLockTime(recoveryLockTargetDaa)
      .addOp(Opcodes.OpCheckLockTimeVerify)
      .addData(recoveryXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpEndIf);
    const c6ScriptPublicKey = c6ScriptBuilder.createPayToScriptHashScript();
    const c6RedeemScriptHex = c6ScriptBuilder.drain();
    const redeemScriptByteLen = c6RedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const c6P2shAddress = addressFromScriptPublicKey(c6ScriptPublicKey as any, networkId as any);
    if (!c6P2shAddress) return null;

    const c6ScriptPublicKeyJson = typeof c6ScriptPublicKey.toJSON === "function"
      ? c6ScriptPublicKey.toJSON()
      : null;
    const c6ScriptPublicKeyScript = covenantPrintable((c6ScriptPublicKeyJson as any)?.script ?? (c6ScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      recovery_address: recoveryAddress,
      recovery_address_version: recoveryAddressVersion,
      recovery_address_from_public_key: recoveryAddressFromPublicKey,
      recovery_public_key_sha256: covenantSha256Text(recoveryXOnlyPublicKeyHex),
      recovery_address_matches_owner: recoveryAddress === ownerAddress,
      recovery_lock_target_daa: recoveryLockTargetDaa.toString(),
      p2sh_owner_release_delayed_recovery_address: c6P2shAddress.toString(),
      p2sh_owner_release_delayed_recovery_redeem_script_hex: c6RedeemScriptHex,
      p2sh_owner_release_delayed_recovery_redeem_script_sha256: covenantSha256Text(c6RedeemScriptHex),
      p2sh_owner_release_delayed_recovery_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_owner_release_delayed_recovery_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_owner_release_delayed_recovery_redeem_script_pushable: redeemScriptPushable,
      p2sh_owner_release_delayed_recovery_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: c6ScriptPublicKey }),
      p2sh_owner_release_delayed_recovery_script_public_key_script_byte_len: c6ScriptPublicKeyScript ? c6ScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_owner_release_delayed_recovery_commitment",
      p2sh_owner_release_delayed_recovery_script_public_key: c6ScriptPublicKey
    };
  } catch {
    return null;
  }
}

function programmableKasOwnerReleaseDelayedRecoverySafeRecord(record: ProgrammableKasOwnerReleaseDelayedRecoveryRecord, currentVirtualDaaScore: string | null, viewerAddress?: string): any {
  const viewerRole = viewerAddress ? programmableKasOwnerReleaseDelayedRecoveryViewerRole(record, viewerAddress) : null;
  const targetText = String(record.recovery_lock_target_daa || "").trim();
  const currentText = String(currentVirtualDaaScore || "").trim();
  const recoveryTargetSatisfied = /^[0-9]+$/.test(targetText) && /^[0-9]+$/.test(currentText)
    ? BigInt(currentText) >= BigInt(targetText)
    : false;

  return {
    record_kind: record.record_kind,
    record_status: record.record_status,
    tracking_source: record.tracking_source,
    viewer_role: viewerRole,
    participant_filter: "owner_or_recovery_wallet_only",
    created_at: record.created_at,
    updated_at: record.updated_at,
    released_at: record.released_at || null,
    network: record.network,
    networkId: record.networkId,
    wallet_id: record.wallet_id,
    wallet_type: record.wallet_type,
    creator_address: record.creator_address,
    owner_address: record.owner_address,
    owner_address_source: record.owner_address_source,
    owner_public_key_sha256: record.owner_public_key_sha256,
    recovery_address: record.recovery_address,
    recovery_address_version: record.recovery_address_version,
    recovery_public_key_sha256: record.recovery_public_key_sha256,
    recovery_address_matches_owner: record.recovery_address_matches_owner,
    recovery_lock_daa_delta: record.recovery_lock_daa_delta,
    current_virtual_daa_score: currentVirtualDaaScore,
    current_virtual_daa_score_at_build: record.current_virtual_daa_score_at_build,
    recovery_lock_target_daa: record.recovery_lock_target_daa,
    recovery_target_satisfied: recoveryTargetSatisfied,
    p2sh_owner_release_delayed_recovery_address: record.p2sh_owner_release_delayed_recovery_address,
    p2sh_owner_release_delayed_recovery_redeem_script_sha256: record.p2sh_owner_release_delayed_recovery_redeem_script_sha256,
    p2sh_owner_release_delayed_recovery_redeem_script_byte_len: record.p2sh_owner_release_delayed_recovery_redeem_script_byte_len,
    p2sh_owner_release_delayed_recovery_redeem_script_push_limit_bytes: record.p2sh_owner_release_delayed_recovery_redeem_script_push_limit_bytes,
    p2sh_owner_release_delayed_recovery_redeem_script_pushable: record.p2sh_owner_release_delayed_recovery_redeem_script_pushable,
    p2sh_owner_release_delayed_recovery_script_public_key_json_sha256: record.p2sh_owner_release_delayed_recovery_script_public_key_json_sha256,
    protected_output_script_form: record.protected_output_script_form,
    amount_sompi: record.amount_sompi,
    amount_kas: record.amount_kas,
    covenant_id: record.covenant_id,
    source_outpoint_key: record.source_outpoint_key,
    submitted_txid: record.submitted_txid,
    post_submit_scan_status: record.post_submit_scan_status,
    protected_output_visible: record.protected_output_visible,
    release_status: record.release_status || null,
    release_txid: record.release_txid || null,
    release_path: record.release_path || null,
    release_amount_sompi: record.release_amount_sompi || null,
    release_amount_kas: record.release_amount_kas || null,
    released_output_outpoint: record.released_output_outpoint || null
  };
}

