type ProgrammableKasAllowedDestinationStore = {
  schema_kind: "programmable_kas_allowed_destination_locks_v1";
  schema_version: 1;
  records: ProgrammableKasAllowedDestinationRecord[];
};

const PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_FILE_NAME = "programmable-kas-allowed-destination-locks.v1.json";
const PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND = "programmable_kas_allowed_destination_locks_v1";

function programmableKasAllowedDestinationLocksPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_FILE_NAME);
}

function emptyProgrammableKasAllowedDestinationLockStore(): ProgrammableKasAllowedDestinationStore {
  return { schema_kind: PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readProgrammableKasAllowedDestinationLockStore(repoRootPath: string, userId: string): ProgrammableKasAllowedDestinationStore {
  const p = programmableKasAllowedDestinationLocksPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return emptyProgrammableKasAllowedDestinationLockStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return emptyProgrammableKasAllowedDestinationLockStore();

  return {
    schema_kind: PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeProgrammableKasAllowedDestinationLockStore(repoRootPath: string, userId: string, store: ProgrammableKasAllowedDestinationStore): void {
  const p = programmableKasAllowedDestinationLocksPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function upsertProgrammableKasAllowedDestinationLockRecord(repoRootPath: string, userId: string, record: ProgrammableKasAllowedDestinationRecord): void {
  const store = readProgrammableKasAllowedDestinationLockStore(repoRootPath, userId);
  const sourceOutpoint = String(record.source_outpoint_key || "").trim();
  const covenantId = String(record.covenant_id || "").trim().toLowerCase();
  const allowedDestinationAddress = String(record.allowed_destination_address || "").trim();
  const filtered = store.records.filter((existing: any) => {
    const sameSource = String(existing?.source_outpoint_key || "").trim() === sourceOutpoint;
    const sameCovenant = String(existing?.covenant_id || "").trim().toLowerCase() === covenantId;
    const sameAllowedDestination = String(existing?.allowed_destination_address || "").trim() === allowedDestinationAddress;
    return !(sameSource && sameCovenant && sameAllowedDestination);
  });

  writeProgrammableKasAllowedDestinationLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function programmableKasAllowedDestinationLockRecordIsReleased(record: any): boolean {
  const status = String(record?.record_status || "").trim();
  return status === "released_live_verified" || status === "release_submitted_pending_visibility";
}

function markProgrammableKasAllowedDestinationLockRecordReleased(
  repoRootPath: string,
  userId: string,
  sourceOutpointKey: string,
  expectedCovenantId: string,
  patch: {
    record_status: string;
    release_status: string;
    release_txid: string;
    release_amount_sompi: string;
    release_amount_kas: string | null;
    released_output_outpoint: string | null;
  }
): ProgrammableKasAllowedDestinationRecord | null {
  const store = readProgrammableKasAllowedDestinationLockStore(repoRootPath, userId);
  const normalizedSource = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();
  const nowIso = new Date().toISOString();
  let updatedRecord: ProgrammableKasAllowedDestinationRecord | null = null;

  const records = store.records.map((record: any) => {
    const sameSource = String(record?.source_outpoint_key || "").trim() === normalizedSource;
    const sameCovenant = String(record?.covenant_id || "").trim().toLowerCase() === normalizedCovenantId;
    if (!sameSource || !sameCovenant) return record;

    updatedRecord = {
      ...(record as ProgrammableKasAllowedDestinationRecord),
      record_status: patch.record_status,
      updated_at: nowIso,
      released_at: nowIso,
      release_status: patch.release_status,
      release_txid: patch.release_txid,
      release_amount_sompi: patch.release_amount_sompi,
      release_amount_kas: patch.release_amount_kas,
      released_output_outpoint: patch.released_output_outpoint
    };
    return updatedRecord;
  });

  if (!updatedRecord) return null;

  writeProgrammableKasAllowedDestinationLockStore(repoRootPath, userId, {
    schema_kind: PROGRAMMABLE_KAS_ALLOWED_DESTINATION_LOCKS_SCHEMA_KIND,
    schema_version: 1,
    records
  });

  return updatedRecord;
}

function programmableKasScriptPublicKeyOutputBytesForSpk(scriptPublicKey: any): { version: number; script: string; bytes_hex: string; script_byte_len: number | null } | null {
  try {
    const json = scriptPublicKey && typeof scriptPublicKey.toJSON === "function" ? scriptPublicKey.toJSON() : scriptPublicKey;
    const version = Number((json as any)?.version ?? (scriptPublicKey as any)?.version ?? 0);
    const script = covenantPrintable((json as any)?.script ?? (scriptPublicKey as any)?.script) || "";
    if (!Number.isInteger(version) || version < 0 || version > 0xffff) return null;
    if (!/^[0-9a-f]*$/i.test(script) || script.length % 2 !== 0) return null;
    return {
      version,
      script,
      bytes_hex: version.toString(16).padStart(4, "0") + script,
      script_byte_len: script ? script.length / 2 : null
    };
  } catch {
    return null;
  }
}

function programmableKasAllowedDestinationPolicyForOwnerAndDestination(
  ownerAddress: string,
  networkId: string,
  allowedDestinationAddress: string
): ProgrammableKasAllowedDestinationPolicy | null {
  try {
    const ownerAddressObject = new Address(ownerAddress);
    const ownerAddressVersion = String(ownerAddressObject.version || "");
    const ownerXOnlyPublicKey = XOnlyPublicKey.fromAddress(ownerAddressObject as any);
    const ownerXOnlyPublicKeyHex = ownerXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(ownerXOnlyPublicKeyHex)) return null;

    const ownerAddressFromPublicKey = ownerXOnlyPublicKey.toAddress(networkId as any).toString();
    if (ownerAddressFromPublicKey !== ownerAddress) return null;

    const allowedDestinationAddressObject = new Address(allowedDestinationAddress);
    const allowedDestinationAddressVersion = String(allowedDestinationAddressObject.version || "");
    const allowedDestinationScriptPublicKey = payToAddressScript(allowedDestinationAddressObject as any);
    const allowedDestinationScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(allowedDestinationScriptPublicKey as any);
    if (!allowedDestinationScriptPublicKeyBytes) return null;

    const allowedDestinationScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addOp(Opcodes.OpTxOutputCount)
      .addI64(1n)
      .addOp(Opcodes.OpEqualVerify)
      .addI64(0n)
      .addOp(Opcodes.OpTxOutputSpk)
      .addData(allowedDestinationScriptPublicKeyBytes.bytes_hex)
      .addOp(Opcodes.OpEqualVerify)
      .addData(ownerXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig);
    const allowedDestinationP2shScriptPublicKey = allowedDestinationScriptBuilder.createPayToScriptHashScript();
    const allowedDestinationRedeemScriptHex = allowedDestinationScriptBuilder.drain();
    const redeemScriptByteLen = allowedDestinationRedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const allowedDestinationP2shAddress = addressFromScriptPublicKey(allowedDestinationP2shScriptPublicKey as any, networkId as any);
    if (!allowedDestinationP2shAddress) return null;

    const allowedDestinationP2shScriptPublicKeyJson = typeof allowedDestinationP2shScriptPublicKey.toJSON === "function"
      ? allowedDestinationP2shScriptPublicKey.toJSON()
      : null;
    const allowedDestinationP2shScriptPublicKeyScript = covenantPrintable((allowedDestinationP2shScriptPublicKeyJson as any)?.script ?? (allowedDestinationP2shScriptPublicKey as any).script);

    return {
      owner_address: ownerAddress,
      owner_address_version: ownerAddressVersion,
      owner_address_from_public_key: ownerAddressFromPublicKey,
      owner_public_key_sha256: covenantSha256Text(ownerXOnlyPublicKeyHex),
      allowed_destination_address: allowedDestinationAddressObject.toString(),
      allowed_destination_address_version: allowedDestinationAddressVersion,
      allowed_destination_script_public_key_version: allowedDestinationScriptPublicKeyBytes.version,
      allowed_destination_script_public_key_script_byte_len: allowedDestinationScriptPublicKeyBytes.script_byte_len,
      allowed_destination_script_public_key_bytes_sha256: covenantSha256Text(allowedDestinationScriptPublicKeyBytes.bytes_hex),
      p2sh_allowed_destination_address: allowedDestinationP2shAddress.toString(),
      p2sh_allowed_destination_redeem_script_hex: allowedDestinationRedeemScriptHex,
      p2sh_allowed_destination_redeem_script_sha256: covenantSha256Text(allowedDestinationRedeemScriptHex),
      p2sh_allowed_destination_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_allowed_destination_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_allowed_destination_redeem_script_pushable: redeemScriptPushable,
      p2sh_allowed_destination_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: allowedDestinationP2shScriptPublicKey }),
      p2sh_allowed_destination_script_public_key_script_byte_len: allowedDestinationP2shScriptPublicKeyScript ? allowedDestinationP2shScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_allowed_destination_commitment",
      p2sh_allowed_destination_script_public_key: allowedDestinationP2shScriptPublicKey
    };
  } catch {
    return null;
  }
}


type ProgrammableKasEscrowRefundPolicy = {
  buyer_refund_address: string;
  buyer_refund_address_version: string;
  buyer_refund_address_from_public_key: string;
  buyer_refund_public_key_sha256: string;
  buyer_refund_script_public_key_version: number;
  buyer_refund_script_public_key_script_byte_len: number | null;
  buyer_refund_script_public_key_bytes_sha256: string;
  seller_release_address: string;
  seller_release_address_version: string;
  seller_release_address_from_public_key: string;
  seller_release_public_key_sha256: string;
  seller_release_script_public_key_version: number;
  seller_release_script_public_key_script_byte_len: number | null;
  seller_release_script_public_key_bytes_sha256: string;
  refund_lock_daa: string;
  p2sh_escrow_refund_address: string;
  p2sh_escrow_refund_redeem_script_hex: string;
  p2sh_escrow_refund_redeem_script_sha256: string;
  p2sh_escrow_refund_redeem_script_byte_len: number;
  p2sh_escrow_refund_redeem_script_push_limit_bytes: number;
  p2sh_escrow_refund_redeem_script_pushable: boolean;
  p2sh_escrow_refund_script_public_key_json_sha256: string | null;
  p2sh_escrow_refund_script_public_key_script_byte_len: number | null;
  protected_output_script_form: "p2sh_escrow_refund_commitment";
  p2sh_escrow_refund_script_public_key: any;
};

function programmableKasEscrowRefundPolicyForBuyerSeller(
  buyerRefundAddress: string,
  networkId: string,
  sellerReleaseAddress: string,
  refundLockDaa: bigint
): ProgrammableKasEscrowRefundPolicy | null {
  try {
    const buyerRefundAddressObject = new Address(buyerRefundAddress);
    const buyerRefundAddressVersion = String(buyerRefundAddressObject.version || "");
    const buyerRefundXOnlyPublicKey = XOnlyPublicKey.fromAddress(buyerRefundAddressObject as any);
    const buyerRefundXOnlyPublicKeyHex = buyerRefundXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(buyerRefundXOnlyPublicKeyHex)) return null;

    const buyerRefundAddressFromPublicKey = buyerRefundXOnlyPublicKey.toAddress(networkId as any).toString();
    if (buyerRefundAddressFromPublicKey !== buyerRefundAddressObject.toString()) return null;

    const sellerReleaseAddressObject = new Address(sellerReleaseAddress);
    const sellerReleaseAddressVersion = String(sellerReleaseAddressObject.version || "");
    const sellerReleaseXOnlyPublicKey = XOnlyPublicKey.fromAddress(sellerReleaseAddressObject as any);
    const sellerReleaseXOnlyPublicKeyHex = sellerReleaseXOnlyPublicKey.toString();
    if (!/^[0-9a-f]{64}$/i.test(sellerReleaseXOnlyPublicKeyHex)) return null;

    const sellerReleaseAddressFromPublicKey = sellerReleaseXOnlyPublicKey.toAddress(networkId as any).toString();
    if (sellerReleaseAddressFromPublicKey !== sellerReleaseAddressObject.toString()) return null;

    const buyerRefundScriptPublicKey = payToAddressScript(buyerRefundAddressObject as any);
    const buyerRefundScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(buyerRefundScriptPublicKey as any);
    if (!buyerRefundScriptPublicKeyBytes) return null;

    const sellerReleaseScriptPublicKey = payToAddressScript(sellerReleaseAddressObject as any);
    const sellerReleaseScriptPublicKeyBytes = programmableKasScriptPublicKeyOutputBytesForSpk(sellerReleaseScriptPublicKey as any);
    if (!sellerReleaseScriptPublicKeyBytes) return null;

    const escrowRefundScriptBuilder = new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
      .addOp(Opcodes.OpDup)
      .addData(sellerReleaseXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpIf)
      .addOp(Opcodes.OpTxOutputCount)
      .addI64(1n)
      .addOp(Opcodes.OpEqualVerify)
      .addI64(0n)
      .addOp(Opcodes.OpTxOutputSpk)
      .addData(sellerReleaseScriptPublicKeyBytes.bytes_hex)
      .addOp(Opcodes.OpEqualVerify)
      .addData(sellerReleaseXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpElse)
      .addLockTime(refundLockDaa)
      .addOp(Opcodes.OpCheckLockTimeVerify)
      .addOp(Opcodes.OpTxOutputCount)
      .addI64(1n)
      .addOp(Opcodes.OpEqualVerify)
      .addI64(0n)
      .addOp(Opcodes.OpTxOutputSpk)
      .addData(buyerRefundScriptPublicKeyBytes.bytes_hex)
      .addOp(Opcodes.OpEqualVerify)
      .addData(buyerRefundXOnlyPublicKeyHex)
      .addOp(Opcodes.OpCheckSig)
      .addOp(Opcodes.OpEndIf);
    const escrowRefundScriptPublicKey = escrowRefundScriptBuilder.createPayToScriptHashScript();
    const escrowRefundRedeemScriptHex = escrowRefundScriptBuilder.drain();
    const redeemScriptByteLen = escrowRefundRedeemScriptHex.length / 2;
    const redeemScriptPushable = redeemScriptByteLen <= COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES;
    if (!redeemScriptPushable) return null;

    const escrowRefundP2shAddress = addressFromScriptPublicKey(escrowRefundScriptPublicKey as any, networkId as any);
    if (!escrowRefundP2shAddress) return null;

    const escrowRefundScriptPublicKeyJson = typeof escrowRefundScriptPublicKey.toJSON === "function"
      ? escrowRefundScriptPublicKey.toJSON()
      : null;
    const escrowRefundScriptPublicKeyScript = covenantPrintable((escrowRefundScriptPublicKeyJson as any)?.script ?? (escrowRefundScriptPublicKey as any).script);

    return {
      buyer_refund_address: buyerRefundAddressObject.toString(),
      buyer_refund_address_version: buyerRefundAddressVersion,
      buyer_refund_address_from_public_key: buyerRefundAddressFromPublicKey,
      buyer_refund_public_key_sha256: covenantSha256Text(buyerRefundXOnlyPublicKeyHex),
      buyer_refund_script_public_key_version: buyerRefundScriptPublicKeyBytes.version,
      buyer_refund_script_public_key_script_byte_len: buyerRefundScriptPublicKeyBytes.script_byte_len,
      buyer_refund_script_public_key_bytes_sha256: covenantSha256Text(buyerRefundScriptPublicKeyBytes.bytes_hex),
      seller_release_address: sellerReleaseAddressObject.toString(),
      seller_release_address_version: sellerReleaseAddressVersion,
      seller_release_address_from_public_key: sellerReleaseAddressFromPublicKey,
      seller_release_public_key_sha256: covenantSha256Text(sellerReleaseXOnlyPublicKeyHex),
      seller_release_script_public_key_version: sellerReleaseScriptPublicKeyBytes.version,
      seller_release_script_public_key_script_byte_len: sellerReleaseScriptPublicKeyBytes.script_byte_len,
      seller_release_script_public_key_bytes_sha256: covenantSha256Text(sellerReleaseScriptPublicKeyBytes.bytes_hex),
      refund_lock_daa: refundLockDaa.toString(),
      p2sh_escrow_refund_address: escrowRefundP2shAddress.toString(),
      p2sh_escrow_refund_redeem_script_hex: escrowRefundRedeemScriptHex,
      p2sh_escrow_refund_redeem_script_sha256: covenantSha256Text(escrowRefundRedeemScriptHex),
      p2sh_escrow_refund_redeem_script_byte_len: redeemScriptByteLen,
      p2sh_escrow_refund_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_escrow_refund_redeem_script_pushable: redeemScriptPushable,
      p2sh_escrow_refund_script_public_key_json_sha256: covenantOutputScriptPublicKeyJsonSha256({ scriptPublicKey: escrowRefundScriptPublicKey }),
      p2sh_escrow_refund_script_public_key_script_byte_len: escrowRefundScriptPublicKeyScript ? escrowRefundScriptPublicKeyScript.length / 2 : null,
      protected_output_script_form: "p2sh_escrow_refund_commitment",
      p2sh_escrow_refund_script_public_key: escrowRefundScriptPublicKey
    };
  } catch {
    return null;
  }

}

