    const programmableKasOwnerReleaseDelayedRecoveryHiddenByParticipantFilterCount = programmableKasOwnerReleaseDelayedRecoveryAllNetworkRecords.length - programmableKasOwnerReleaseDelayedRecoveryRecords.length;
    const programmableKasActiveOwnerReleaseDelayedRecoveryRecords = programmableKasOwnerReleaseDelayedRecoveryRecords
      .filter((record: any) => !programmableKasOwnerReleaseDelayedRecoveryLockRecordIsReleased(record));
    const programmableKasRequestedOwnerReleaseDelayedRecoveryRecord = requestedAddress
