    const programmableKasAbsoluteTimeLockStore = readProgrammableKasAbsoluteTimeLockStore(repoRoot, userId);
    const programmableKasAbsoluteTimeLockRecords = programmableKasAbsoluteTimeLockStore.records
      .filter((record: any) => String(record?.networkId || "") === networkId)
