    const programmableKasActiveAbsoluteTimeLockRecords = programmableKasAbsoluteTimeLockRecords
      .filter((record: any) => !programmableKasAbsoluteTimeLockRecordIsReleased(record));
    const programmableKasRequestedAbsoluteTimeLockRecord = requestedAddress
      ? programmableKasAbsoluteTimeLockRecords.find((record: any) => String(record?.p2sh_absolute_time_lock_address || "").trim() === requestedAddress) || null
      : null;
    const programmableKasAbsoluteTimeLockRequestedAddressSource = programmableKasRequestedAbsoluteTimeLockRecord
      ? "programmable_kas_p2sh_absolute_time_lock_tracked_address"
      : null;
    const programmableKasRelativeSequenceLockStore = readProgrammableKasRelativeSequenceLockStore(repoRoot, userId);
    const programmableKasRelativeSequenceLockRecords = programmableKasRelativeSequenceLockStore.records
