    const programmableKasRequestedRelativeSequenceLockRecord = requestedAddress
      ? programmableKasRelativeSequenceLockRecords.find((record: any) => String(record?.p2sh_relative_sequence_lock_address || "").trim() === requestedAddress) || null
      : null;
    const programmableKasRelativeSequenceLockRequestedAddressSource = programmableKasRequestedRelativeSequenceLockRecord
      ? "programmable_kas_p2sh_relative_sequence_lock_tracked_address"
      : null;
    const programmableKasAllowedDestinationStore = readProgrammableKasAllowedDestinationLockStore(repoRoot, userId);
    const programmableKasAllowedDestinationRecords = programmableKasAllowedDestinationStore.records
      .filter((record: any) => String(record?.networkId || "") === networkId)
      .filter((record: any) => String(record?.p2sh_allowed_destination_address || "").trim());
    const programmableKasActiveAllowedDestinationRecords = programmableKasAllowedDestinationRecords
      .filter((record: any) => !programmableKasAllowedDestinationLockRecordIsReleased(record));
    const programmableKasRequestedAllowedDestinationRecord = requestedAddress
      ? programmableKasAllowedDestinationRecords.find((record: any) => String(record?.p2sh_allowed_destination_address || "").trim() === requestedAddress) || null
      : null;
    const programmableKasAllowedDestinationRequestedAddressSource = programmableKasRequestedAllowedDestinationRecord
      ? "programmable_kas_p2sh_allowed_destination_tracked_address"
      : null;
    const programmableKasAbsoluteTimeLockAllowedDestinationStore = readProgrammableKasAbsoluteTimeLockAllowedDestinationLockStore(repoRoot, userId);
    const programmableKasAbsoluteTimeLockAllowedDestinationRecords = programmableKasAbsoluteTimeLockAllowedDestinationStore.records
      .filter((record: any) => String(record?.networkId || "") === networkId)
      .filter((record: any) => String(record?.p2sh_absolute_time_lock_allowed_destination_address || "").trim());
    const programmableKasActiveAbsoluteTimeLockAllowedDestinationRecords = programmableKasAbsoluteTimeLockAllowedDestinationRecords
      .filter((record: any) => !programmableKasAbsoluteTimeLockAllowedDestinationRecordIsReleased(record));
    const programmableKasRequestedAbsoluteTimeLockAllowedDestinationRecord = requestedAddress
      ? programmableKasAbsoluteTimeLockAllowedDestinationRecords.find((record: any) => String(record?.p2sh_absolute_time_lock_allowed_destination_address || "").trim() === requestedAddress) || null
      : null;
    const programmableKasAbsoluteTimeLockAllowedDestinationRequestedAddressSource = programmableKasRequestedAbsoluteTimeLockAllowedDestinationRecord
      ? "programmable_kas_p2sh_absolute_time_lock_allowed_destination_tracked_address"
      : null;
    const programmableKasEscrowRefundStore = readProgrammableKasEscrowRefundLockStore(repoRoot, userId);
    const programmableKasEscrowRefundRecords = programmableKasEscrowRefundStore.records
      .filter((record: any) => String(record?.networkId || "") === networkId)
