    const programmableKasRequestedEscrowRefundRecord = requestedAddress
      ? programmableKasEscrowRefundRecords.find((record: any) => String(record?.p2sh_escrow_refund_address || "").trim() === requestedAddress) || null
      : null;
    const programmableKasEscrowRefundRequestedAddressSource = programmableKasRequestedEscrowRefundRecord
      ? "programmable_kas_p2sh_escrow_refund_tracked_address"
      : null;
    const kcc20AtomicSwapStore = readKcc20AtomicSwapLockStore(repoRoot, userId);
