    const kcc20AtomicSwapHiddenByParticipantFilterCount = kcc20AtomicSwapAllNetworkRecords.length - kcc20AtomicSwapRecords.length;
    const kcc20AtomicSwapActiveRecords = kcc20AtomicSwapRecords
      .filter((record: any) => !kcc20AtomicSwapLockRecordIsReleased(record));
