function covenantInputOutpointKey(row: CovenantControlsBuildSourceRow): string | null {
  return row.outpoint.transaction_id && row.outpoint.index !== null
    ? `${row.outpoint.transaction_id}:${row.outpoint.index}`
    : row.outpoint.text;
}

function covenantIsCoinbaseReference(reference: any): boolean {
  const entry = covenantReferenceEntry(reference);
  return reference?.isCoinbase === true || entry?.isCoinbase === true || reference?.utxo?.isCoinbase === true || reference?.utxoEntry?.isCoinbase === true;
}

function covenantBuildSourceRow(reference: any, index: number): CovenantControlsBuildSourceRow {
  const covenant = covenantIdFromReference(reference);
  const amount_sompi = covenantAmountSompiFromReference(reference);
  const outpoint = covenantOutpointFromReference(reference);
  return {
    index,
    amount_sompi,
    amount_kas: sompiTextToKasText(amount_sompi),
    block_daa_score: covenantBlockDaaScoreFromReference(reference),
    outpoint,
    covenant_present: covenant.present,
    covenant_id: covenant.value,
    covenant_path: covenant.path,
    is_coinbase: covenantIsCoinbaseReference(reference)
  };
}

function selectCovenantControlsBuildSource(entries: any[], amountSompi: bigint, feeReserveSompi: bigint): { reference: any; row: CovenantControlsBuildSourceRow } | null {
  const requiredSompi = amountSompi + feeReserveSompi;
  const candidates = entries
    .map((entry, index) => ({ reference: entry, row: covenantBuildSourceRow(entry, index) }))
    .filter(({ row }) => {
      if (row.covenant_present) return false;
      if (row.is_coinbase) return false;
      if (!row.amount_sompi || !/^[0-9]+$/.test(row.amount_sompi)) return false;
      return BigInt(row.amount_sompi) > requiredSompi;
    })
    .sort((a, b) => {
      const aAmount = BigInt(a.row.amount_sompi || "0");
      const bAmount = BigInt(b.row.amount_sompi || "0");
      if (aAmount < bAmount) return -1;
      if (aAmount > bAmount) return 1;
      return a.row.index - b.row.index;
    });

  return candidates[0] || null;
}


type CovenantControlsMassAwareGenesisBuildResult = {
  tx: any;
  expectedCovenantId: string;
  populatedCovenantId: string;
  changeAmountSompi: bigint;
  calculatedFeeSompi: bigint;
  massBeforeUpdate: any;
  nativeFundingInputs: CovenantControlsNativeFundingInputCacheEntry[];
  nativeFundingTotalSompi: bigint;
  selectedCandidateIndex: number;
  feeResolutionTrace: any[];
  selected: { reference: any; row: CovenantControlsBuildSourceRow };
  signInputIndexes: number[];
};

function covenantControlsNativeFundingDummySignatureScript(): string {
  return new ScriptBuilder({ flags: { covenantsEnabled: true } } as any)
    .addData(new Uint8Array(65))
    .drain();
}

function covenantControlsBuildMassAwareGenesisCandidate(args: {
  entries: any[];
  networkId: string;
  fundingAddress: string;
  amountSompi: bigint;
  feeReserveSompi: bigint;
  createProtectedOutput: () => any;
  createChangeOutput: (changeAmountSompi: bigint) => any;
  selectionKind: string;
  changeNotPositiveReason: string;
  massFailureReason: string;
  feeNotConvergedReason: string;
  computeBudget?: number;
}): CovenantControlsMassAwareGenesisBuildResult | null {
  const fundingCandidateSets = omaKcc20NativeFundingCandidateSets(args.entries, args.amountSompi + args.feeReserveSompi, 8);
  const nativeFundingDummySignatureScript = covenantControlsNativeFundingDummySignatureScript();
  const candidateAttempts = fundingCandidateSets.slice(0, 40);

  for (let candidateIndex = 0; candidateIndex < candidateAttempts.length; candidateIndex += 1) {
    const candidateSet = candidateAttempts[candidateIndex];
    const nativeFundingTotalSompi = candidateSet.reduce((sum, item) => sum + item.amount_sompi, 0n);
    const nativeFundingInputs: CovenantControlsNativeFundingInputCacheEntry[] = candidateSet.map((item, itemIndex) => ({
      input_index: itemIndex,
      outpoint: item.outpoint,
      address: args.fundingAddress,
      amount_sompi: item.amount_sompi.toString()
    }));
    const candidateFeeResolutionTrace: any[] = [];
    let nextFeeReserveSompi = args.feeReserveSompi;

    for (let attemptIndex = 0; attemptIndex < 8; attemptIndex += 1) {
      const changeAmountSompi = nativeFundingTotalSompi - args.amountSompi - nextFeeReserveSompi;
      if (changeAmountSompi <= 0n) {
        candidateFeeResolutionTrace.push({ selection_kind: args.selectionKind, attempt: attemptIndex + 1, attempted_fee_reserve_sompi: nextFeeReserveSompi.toString(), native_funding_total_sompi: nativeFundingTotalSompi.toString(), amount_sompi: args.amountSompi.toString(), change_sompi: changeAmountSompi.toString(), result: "rejected", reason: args.changeNotPositiveReason });
        break;
      }

      const tx: any = new Transaction({
        version: 1,
        inputs: candidateSet.map((item) => ({
          previousOutpoint: item.previous_outpoint,
          signatureScript: "",
          sequence: 0n,
          sigOpCount: 0,
          computeBudget: args.computeBudget ?? COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET,
          utxo: item.reference
        })),
        outputs: [args.createProtectedOutput(), args.createChangeOutput(changeAmountSompi)],
        lockTime: 0n,
        subnetworkId: COVENANT_CONTROLS_DEFAULT_SUBNETWORK_ID,
        gas: 0n,
        payload: ""
      } as any);

      const expectedCovenantId = covenantId(candidateSet[0].previous_outpoint as any, [{ index: 0, output: tx.outputs[0] }] as any).toString();
      tx.populateGenesisCovenants([{ authorizingInput: 0, outputs: [0] }]);
      const populatedCovenant = tx.outputs[0]?.covenant;
      if (!populatedCovenant) throw new Error("covenant_controls_mass_aware_genesis_missing_populated_covenant");
      const populatedCovenantId = String(populatedCovenant.toJSON().covenantId);
      if (populatedCovenantId !== expectedCovenantId) throw new Error("covenant_controls_mass_aware_genesis_covenant_id_mismatch");
      if (tx.outputs[1]?.covenant) throw new Error("covenant_controls_mass_aware_genesis_change_output_unexpected_covenant");

      for (const fundingInput of nativeFundingInputs) tx.inputs[fundingInput.input_index].signatureScript = nativeFundingDummySignatureScript;
      const massBeforeUpdate = calculateTransactionMass(args.networkId, tx, 1);
      const updateOk = updateTransactionMass(args.networkId, tx, 1);
      const calculatedFee = updateOk ? calculateTransactionFee(args.networkId, tx, 1) : undefined;
      for (const fundingInput of nativeFundingInputs) tx.inputs[fundingInput.input_index].signatureScript = "";

      if (!updateOk || calculatedFee === undefined) {
        candidateFeeResolutionTrace.push({ selection_kind: args.selectionKind, attempt: attemptIndex + 1, attempted_fee_reserve_sompi: nextFeeReserveSompi.toString(), native_funding_total_sompi: nativeFundingTotalSompi.toString(), amount_sompi: args.amountSompi.toString(), change_sompi: changeAmountSompi.toString(), calculated_mass_before_update: covenantPrintable(massBeforeUpdate), update_transaction_mass_ok: false, result: "rejected", reason: args.massFailureReason });
        break;
      }

      const calculatedFeeSompi = BigInt(covenantPrintable(calculatedFee) || "0");
      if (calculatedFeeSompi <= 0n) throw new Error("covenant_controls_mass_aware_genesis_calculated_fee_not_positive");
      candidateFeeResolutionTrace.push({ selection_kind: args.selectionKind, attempt: attemptIndex + 1, attempted_fee_reserve_sompi: nextFeeReserveSompi.toString(), native_funding_total_sompi: nativeFundingTotalSompi.toString(), amount_sompi: args.amountSompi.toString(), change_sompi: changeAmountSompi.toString(), calculated_mass_before_update: covenantPrintable(massBeforeUpdate), storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null, calculated_fee_sompi: calculatedFeeSompi.toString(), fee_matches_reserve: calculatedFeeSompi === nextFeeReserveSompi });

      if (calculatedFeeSompi === nextFeeReserveSompi) {
        const signInputIndexes = nativeFundingInputs.map((input) => input.input_index);
        return {
          tx,
          expectedCovenantId,
          populatedCovenantId,
          changeAmountSompi,
          calculatedFeeSompi,
          massBeforeUpdate,
          nativeFundingInputs,
          nativeFundingTotalSompi,
          selectedCandidateIndex: candidateIndex,
          feeResolutionTrace: candidateFeeResolutionTrace,
          selected: { reference: candidateSet[0].reference, row: candidateSet[0].row },
          signInputIndexes
        };
      }
      nextFeeReserveSompi = calculatedFeeSompi;
    }
  }

  return null;
}

function covenantControlsValidateNativeFundingSignedInputs(args: {
  signedTx: any;
  unsignedTx: any;
  cachedFundingInputs: CovenantControlsNativeFundingInputCacheEntry[];
  expectedComputeBudget?: number;
  reasonPrefix: string;
}): { ok: true } | { ok: false; status: number; body: any } {
  const expectedInputCount = args.cachedFundingInputs.length;
  if (!Array.isArray(args.signedTx?.inputs) || !Array.isArray(args.signedTx?.outputs) || args.signedTx.inputs.length !== expectedInputCount || args.signedTx.outputs.length !== 2) {
    return { ok: false, status: 400, body: { ok: false, reason: `${args.reasonPrefix}_tx_shape_invalid`, expected_input_count: expectedInputCount, signed_input_count: Array.isArray(args.signedTx?.inputs) ? args.signedTx.inputs.length : null, broadcasting_enabled: false, minting_enabled: false } };
  }
  if (!Array.isArray(args.unsignedTx?.inputs) || !Array.isArray(args.unsignedTx?.outputs) || args.unsignedTx.inputs.length !== expectedInputCount || args.unsignedTx.outputs.length !== 2) {
    return { ok: false, status: 500, body: { ok: false, reason: `cached_unsigned_${args.reasonPrefix}_tx_shape_invalid`, expected_input_count: expectedInputCount, unsigned_input_count: Array.isArray(args.unsignedTx?.inputs) ? args.unsignedTx.inputs.length : null, broadcasting_enabled: false, minting_enabled: false } };
  }
  for (let fundingPosition = 0; fundingPosition < args.cachedFundingInputs.length; fundingPosition += 1) {
    const fundingInput = args.cachedFundingInputs[fundingPosition];
    const inputIndex = Number(fundingInput.input_index);
    const signedInput = args.signedTx.inputs[inputIndex];
    const unsignedInput = args.unsignedTx.inputs[inputIndex];
    const signedInputOutpoint = covenantTxInputOutpointKey(signedInput);
    const unsignedInputOutpoint = covenantTxInputOutpointKey(unsignedInput);
    if (!Number.isInteger(inputIndex) || inputIndex < 0 || inputIndex >= expectedInputCount || !signedInput || !unsignedInput || signedInputOutpoint !== fundingInput.outpoint || unsignedInputOutpoint !== fundingInput.outpoint) {
      return { ok: false, status: 409, body: { ok: false, reason: `${args.reasonPrefix}_input_outpoint_mismatch`, native_funding_position: fundingPosition, native_funding_input_index: inputIndex, expected_outpoint: fundingInput.outpoint, signed_outpoint: signedInputOutpoint, unsigned_outpoint: unsignedInputOutpoint, broadcasting_enabled: false, minting_enabled: false } };
    }
    if (!covenantSignatureScriptIsPresentHex(signedInput)) {
      return { ok: false, status: 400, body: { ok: false, reason: `${args.reasonPrefix}_input_signature_script_missing_or_invalid`, native_funding_position: fundingPosition, native_funding_input_index: inputIndex, broadcasting_enabled: false, minting_enabled: false } };
    }
    const expectedComputeBudget = args.expectedComputeBudget ?? COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET;
    if (Number(signedInput.computeBudget ?? 0) !== expectedComputeBudget || Number(signedInput.sigOpCount ?? 0) !== 0 || signedInput.computeBudget !== unsignedInput.computeBudget || signedInput.sigOpCount !== unsignedInput.sigOpCount) {
      return { ok: false, status: 409, body: { ok: false, reason: `${args.reasonPrefix}_input_budget_mismatch`, native_funding_position: fundingPosition, native_funding_input_index: inputIndex, expected_computeBudget: expectedComputeBudget, signed_computeBudget: Number(signedInput.computeBudget ?? 0), expected_sigOpCount: 0, signed_sigOpCount: Number(signedInput.sigOpCount ?? 0), broadcasting_enabled: false, minting_enabled: false } };
    }
  }
  return { ok: true };
}

function covenantControlsValidateCachedNativeFundingUnspent(args: {
  preSubmitRows: CovenantControlsBuildSourceRow[];
  cachedFundingInputs: CovenantControlsNativeFundingInputCacheEntry[];
  reasonPrefix: string;
}): { ok: true; rows: CovenantControlsBuildSourceRow[] } | { ok: false; status: number; body: any } {
  const rows: CovenantControlsBuildSourceRow[] = [];
  for (const fundingInput of args.cachedFundingInputs) {
    const row = args.preSubmitRows.find((candidate) => covenantInputOutpointKey(candidate) === fundingInput.outpoint) || null;
    if (!row) {
      return { ok: false, status: 409, body: { ok: false, reason: `${args.reasonPrefix}_selected_source_not_unspent`, selected_outpoint_key: fundingInput.outpoint, broadcasting_enabled: false, minting_enabled: false } };
    }
    if (row.covenant_present || row.amount_sompi !== fundingInput.amount_sompi) {
      return { ok: false, status: 409, body: { ok: false, reason: `${args.reasonPrefix}_selected_source_state_mismatch`, selected_outpoint_key: fundingInput.outpoint, selected_source: row, expected_amount_sompi: fundingInput.amount_sompi, broadcasting_enabled: false, minting_enabled: false } };
    }
    rows.push(row);
  }
  return { ok: true, rows };
}

function selectCovenantControlsReleaseSource(
  entries: any[],
  sourceOutpointKey: string,
  expectedCovenantId: string
): { reference: any; row: CovenantControlsBuildSourceRow } | null {
  const normalizedOutpoint = String(sourceOutpointKey || "").trim();
  const normalizedCovenantId = String(expectedCovenantId || "").trim().toLowerCase();

  if (!normalizedOutpoint || !normalizedCovenantId) return null;

  const candidates = entries.map((entry, index) => ({ reference: entry, row: covenantBuildSourceRow(entry, index) }));
  return candidates.find(({ row }) => {
    const outpointKey = covenantInputOutpointKey(row);
    const rowCovenantId = String(row.covenant_id || "").trim().toLowerCase();
    return outpointKey === normalizedOutpoint && row.covenant_present === true && rowCovenantId === normalizedCovenantId;
  }) || null;
}

function covenantControlsSummarizeTxOutput(output: any, index: number): any {
  const covenant = output?.covenant;
  return {
    index,
    value: output?.value !== undefined ? covenantPrintable(output.value) : null,
    scriptPublicKey: output?.scriptPublicKey && typeof output.scriptPublicKey.toJSON === "function" ? output.scriptPublicKey.toJSON() : null,
    covenant_present: !!covenant,
    covenant: covenant && typeof covenant.toJSON === "function" ? covenant.toJSON() : null
  };
}

function covenantControlsSummarizeTxInput(input: any, index: number): any {
  return {
    index,
    previousOutpoint: input?.previousOutpoint && typeof input.previousOutpoint.toJSON === "function" ? input.previousOutpoint.toJSON() : input?.previousOutpoint,
    signatureScript_present: typeof input?.signatureScript === "string" && input.signatureScript.length > 0,
    signatureScript_length: typeof input?.signatureScript === "string" ? input.signatureScript.length : null,
    sequence: input?.sequence !== undefined ? covenantPrintable(input.sequence) : null,
    sigOpCount: input?.sigOpCount ?? null,
    computeBudget: input?.computeBudget ?? null,
    utxo_present: !!input?.utxo
  };
}

function requirePositiveSompiInput(value: any, fieldName: string): bigint {
  const sompi = readSompi(value);
  if (sompi === null || sompi <= 0n) {
    throw new Error(`${fieldName}_must_be_positive_integer_sompi`);
  }
  return sompi;
}

function requireTransactionSafeJson(tx: any): string {
  if (!tx || typeof tx.serializeToSafeJSON !== "function") {
    throw new Error("transaction_serialize_to_safe_json_missing");
  }
  const safeJson = tx.serializeToSafeJSON();
  if (typeof safeJson !== "string" || !safeJson.trim()) {
    throw new Error("transaction_safe_json_empty");
  }
  return safeJson;
}

function covenantSha256Text(value: string): string {
  return createHash("sha256").update(String(value || ""), "utf8").digest("hex");
}

