type OmaL1IssuanceAuthorizationStore = {
  schema_kind: "oma_l1_issuance_authorizations_v1";
  schema_version: 1;
  records: OmaL1IssuanceAuthorizationConsumptionRecord[];
};

function omaL1IssuanceAuthorizationsPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, OMA_L1_ISSUANCE_AUTHORIZATIONS_FILE_NAME);
}

function readOmaL1IssuanceAuthorizationStore(
  repoRootPath: string,
  userId: string
): OmaL1IssuanceAuthorizationStore {
  const p = omaL1IssuanceAuthorizationsPath(repoRootPath, userId);
  if (!fs.existsSync(p)) {
    return {
      schema_kind: OMA_L1_ISSUANCE_AUTHORIZATIONS_SCHEMA_KIND,
      schema_version: 1,
      records: []
    };
  }

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (
    !parsed
    || typeof parsed !== "object"
    || parsed.schema_kind !== OMA_L1_ISSUANCE_AUTHORIZATIONS_SCHEMA_KIND
    || parsed.schema_version !== 1
    || !Array.isArray(parsed.records)
  ) {
    throw new Error("oma_l1_issuance_authorization_store_invalid");
  }

  const records = parsed.records.map((record: any) => {
    if (
      !record
      || typeof record !== "object"
      || record.record_kind !== "oma_l1_issuance_authorization_consumption_v1"
      || record.record_status !== "consumed"
      || typeof record.event_identity !== "string"
      || !record.event_identity.trim()
    ) {
      throw new Error("oma_l1_issuance_authorization_record_invalid");
    }
    return record as OmaL1IssuanceAuthorizationConsumptionRecord;
  });

  return {
    schema_kind: OMA_L1_ISSUANCE_AUTHORIZATIONS_SCHEMA_KIND,
    schema_version: 1,
    records
  };
}

function writeOmaL1IssuanceAuthorizationStore(
  repoRootPath: string,
  userId: string,
  store: OmaL1IssuanceAuthorizationStore
): void {
  const p = omaL1IssuanceAuthorizationsPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function appendOmaL1IssuanceAuthorizationConsumptionRecord(
  repoRootPath: string,
  userId: string,
  record: OmaL1IssuanceAuthorizationConsumptionRecord
): void {
  const eventIdentity = String(record.event_identity || "").trim().toLowerCase();
  if (!eventIdentity) throw new Error("oma_l1_issuance_authorization_event_identity_required");
  if (omaL1IssuanceAuthorizationEventConsumed(repoRootPath, eventIdentity)) {
    throw new Error("oma_l1_issuance_authorization_event_already_consumed");
  }

  const store = readOmaL1IssuanceAuthorizationStore(repoRootPath, userId);
  writeOmaL1IssuanceAuthorizationStore(repoRootPath, userId, {
    schema_kind: OMA_L1_ISSUANCE_AUTHORIZATIONS_SCHEMA_KIND,
    schema_version: 1,
    records: [...store.records, { ...record, event_identity: eventIdentity, authorization_id: eventIdentity }]
  });
}

function omaL1IssuanceAuthorizationEventConsumed(
  repoRootPath: string,
  eventIdentity: string
): boolean {
  const target = String(eventIdentity || "").trim().toLowerCase();
  if (!target) throw new Error("oma_l1_issuance_authorization_event_identity_required");

  for (const userId of omaL1DataUserIds(repoRootPath)) {
    const store = readOmaL1IssuanceAuthorizationStore(repoRootPath, userId);
    if (store.records.some((record) => String(record.event_identity || "").trim().toLowerCase() === target)) {
      return true;
    }
  }
  return false;
}

function omaL1NormalizeNetworkId(value: any): string {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "testnet" || raw === "tn10" || raw === "testnet10") return "testnet-10";
  return raw;
}

function omaL1TrackedAssetsPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, OMA_L1_TRACKED_ASSETS_FILE_NAME);
}

function omaL1EmptyTrackedAssetStore(): OmaL1TrackedAssetStore {
  return { schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readOmaL1TrackedAssetStore(repoRootPath: string, userId: string): OmaL1TrackedAssetStore {
  const p = omaL1TrackedAssetsPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return omaL1EmptyTrackedAssetStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return omaL1EmptyTrackedAssetStore();

  return {
    schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeOmaL1TrackedAssetStore(repoRootPath: string, userId: string, store: OmaL1TrackedAssetStore): void {
  const p = omaL1TrackedAssetsPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function omaL1BurnReceiptsPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, OMA_L1_BURN_RECEIPTS_FILE_NAME);
}

function omaL1EmptyBurnReceiptStore(): OmaL1BurnReceiptStore {
  return { schema_kind: OMA_L1_BURN_RECEIPTS_SCHEMA_KIND, schema_version: 1, records: [] };
}

function readOmaL1BurnReceiptStore(repoRootPath: string, userId: string): OmaL1BurnReceiptStore {
  const p = omaL1BurnReceiptsPath(repoRootPath, userId);
  if (!fs.existsSync(p)) return omaL1EmptyBurnReceiptStore();

  const parsed = JSON.parse(fs.readFileSync(p, "utf8"));
  if (!parsed || typeof parsed !== "object" || !Array.isArray(parsed.records)) return omaL1EmptyBurnReceiptStore();

  return {
    schema_kind: OMA_L1_BURN_RECEIPTS_SCHEMA_KIND,
    schema_version: 1,
    records: parsed.records.filter((record: any) => record && typeof record === "object")
  };
}

function writeOmaL1BurnReceiptStore(repoRootPath: string, userId: string, store: OmaL1BurnReceiptStore): void {
  const p = omaL1BurnReceiptsPath(repoRootPath, userId);
  const dir = path.dirname(p);
  if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
  const tmp = `${p}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tmp, JSON.stringify(store, null, 2) + "\n", "utf8");
  fs.renameSync(tmp, p);
}

function appendOmaL1BurnReceiptRecord(repoRootPath: string, userId: string, record: OmaL1BurnReceiptRecord): void {
  const store = readOmaL1BurnReceiptStore(repoRootPath, userId);
  const submittedTxid = String(record.submitted_txid || "").trim();
  const burnAmountRaw = String(record.burn_amount_raw || "").trim();
  const sourceKey = record.source_holder_outpoints.join("|");
  const filtered = store.records.filter((existing: any) => {
    const sameTx = String(existing?.submitted_txid || "").trim() === submittedTxid;
    const sameAmount = String(existing?.burn_amount_raw || "").trim() === burnAmountRaw;
    const sameSources = Array.isArray(existing?.source_holder_outpoints) && existing.source_holder_outpoints.join("|") === sourceKey;
    return !(sameTx && sameAmount && sameSources);
  });

  writeOmaL1BurnReceiptStore(repoRootPath, userId, {
    schema_kind: OMA_L1_BURN_RECEIPTS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, record]
  });
}

function upsertOmaL1TrackedAssetRecord(repoRootPath: string, userId: string, record: OmaL1TrackedAssetRecord): void {
  const store = readOmaL1TrackedAssetStore(repoRootPath, userId);
  const assetId = String(record.asset_covenant_id || "").trim().toLowerCase();
  const holderOutpoint = String(record.holder?.outpoint || "").trim();
  const nextRecords = store.records.filter((existing: any) => {
    const existingAsset = String(existing?.asset_covenant_id || "").trim().toLowerCase();
    const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
    return !(assetId && existingAsset === assetId) && !(holderOutpoint && existingHolderOutpoint === holderOutpoint);
  });

  writeOmaL1TrackedAssetStore(repoRootPath, userId, {
    schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
    schema_version: 1,
    records: [...nextRecords, record]
  });
}

