function omaL1DeploySubmitTrackedAssetCandidate(params: {
  cached: OmaL1TokenDeployBuildCacheEntry;
  activeWallet: any;
  submittedTxid: string;
  controllerExpected: OmaL1TokenDeployOutputSnapshot | null;
  holderExpected: OmaL1TokenDeployOutputSnapshot | null;
  controllerOutputRow: CovenantControlsBuildSourceRow | null;
  holderOutputRow: CovenantControlsBuildSourceRow | null;
}): OmaL1TrackedAssetRecord | null {
  const { cached, activeWallet, submittedTxid, controllerExpected, holderExpected, controllerOutputRow, holderOutputRow } = params;
  if (!controllerExpected || !controllerOutputRow) return null;

  const holderAmountRawText = String(cached.initial_issue_raw || "0").trim();
  if (!/^\d+$/.test(holderAmountRawText)) return null;
  const controllerOnlyZeroSupply = BigInt(holderAmountRawText) === 0n;
  const regulatedProfile = omaReadKcc20StoredRegulatedCompactState(cached.regulated_profile);
  if (controllerOnlyZeroSupply && !regulatedProfile) return null;
  if (!controllerOnlyZeroSupply && (!holderExpected || !holderOutputRow)) return null;

  const assetCovenantId = String(cached.asset_covenant_id || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetCovenantId)) return null;
  if (String(controllerOutputRow.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
  if (String(controllerExpected.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
  if (!controllerOnlyZeroSupply) {
    if (String(holderOutputRow?.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
    if (String(holderExpected?.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
  }

  const controllerOutpoint = covenantInputOutpointKey(controllerOutputRow) || `${submittedTxid}:${controllerExpected.index}`;
  const holderOutpoint = controllerOnlyZeroSupply
    ? null
    : (covenantInputOutpointKey(holderOutputRow!) || `${submittedTxid}:${holderExpected!.index}`);
  const now = new Date().toISOString();

  return {
    record_kind: "oma_l1_tracked_asset_record_v1",
    record_status: "candidate_requires_live_reverification",
    created_at: now,
    updated_at: now,
    source: "oma_l1_deploy_submit_auto_track_v1",
    networkId: cached.networkId,
    wallet_id: String(cached.wallet_id || activeWallet?.id || ""),
    owner_public_key: String(cached.owner_public_key || ""),
    owner_identifier: String(cached.owner_address_from_public_key || activeWallet?.address0 || ""),
    issuer_identifier: String(cached.fromAddress || activeWallet?.address0 || ""),
    token_name: cached.token_name,
    token_symbol: cached.token_symbol,
    decimals: cached.decimals,
    max_supply_raw: cached.max_supply_raw,
    issued_supply_raw: cached.initial_issue_raw,
    holder_amount_raw: holderAmountRawText,
    transfer_rule: cached.transfer_rule,
    policy_hash: cached.policy_hash,
    ...(regulatedProfile ? {
      regulated_profile: regulatedProfile,
      holder_script_profile: OMA_L1_TOKEN_HOLDER_SCRIPT_PROFILE_REGULATED_REGISTRY_CONTROL_V1
    } : {}),
    ...(controllerOnlyZeroSupply ? { controller_only_zero_supply: true } : {}),
    asset_covenant_id: assetCovenantId,
    controller: {
      address: String(controllerExpected.address || ""),
      outpoint: controllerOutpoint,
      carrier_sompi: String(controllerExpected.value_sompi || cached.controller_carrier_sompi || "0"),
      script_public_key_script: null,
      script_public_key_json_sha256: controllerExpected.script_public_key_json_sha256,
      redeem_script_hex_sha256: null,
      state_schema: String(controllerExpected.state_schema || OMA_L1_TOKEN_CONTROLLER_STATE_SCHEMA)
    },
    holder: controllerOnlyZeroSupply ? {
      address: "",
      outpoint: null,
      carrier_sompi: "0",
      script_public_key_script: null,
      script_public_key_json_sha256: null,
      redeem_script_hex_sha256: null,
      state_schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA
    } : {
      address: String(holderExpected!.address || ""),
      outpoint: holderOutpoint,
      carrier_sompi: String(holderExpected!.value_sompi || cached.holder_carrier_sompi || "0"),
      script_public_key_script: null,
      script_public_key_json_sha256: holderExpected!.script_public_key_json_sha256,
      redeem_script_hex_sha256: null,
      state_schema: String(holderExpected!.state_schema || OMA_L1_TOKEN_HOLDER_STATE_SCHEMA)
    }
  };
}

function omaL1HolderTransferTrackedAssetCandidate(params: {
  cached: OmaL1HolderTransferBuildCacheEntry;
  activeWallet: any;
  submittedTxid: string;
  expected: OmaL1HolderTransferOutputSnapshot;
  outputRow: CovenantControlsBuildSourceRow | null;
  ownerPublicKey: string;
  ownerIdentifier: string;
  walletId: string;
}): OmaL1TrackedAssetRecord | null {
  const { cached, activeWallet, submittedTxid, expected, outputRow, ownerPublicKey, ownerIdentifier, walletId } = params;
  if (!expected) return null;
  if (expected.role !== "recipient_holder" && expected.role !== "sender_change_holder") return null;

  const assetCovenantId = String(cached.asset_covenant_id || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetCovenantId)) return null;
  if (String(expected.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
  if (outputRow && String(outputRow.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;

  const holderAmountRaw = String(expected.amount_raw || "0").trim();
  if (!/^\d+$/.test(holderAmountRaw) || BigInt(holderAmountRaw) <= 0n) return null;

  const holderOutpoint = outputRow ? (covenantInputOutpointKey(outputRow) || `${submittedTxid}:${expected.index}`) : `${submittedTxid}:${expected.index}`;
  const regulatedProfile = omaReadKcc20StoredRegulatedCompactState(cached.regulated_profile);
  const now = new Date().toISOString();

  return {
    record_kind: "oma_l1_tracked_asset_record_v1",
    record_status: "candidate_requires_live_reverification",
    created_at: now,
    updated_at: now,
    source: "oma_l1_holder_transfer_submit_auto_track_v1",
    networkId: cached.networkId,
    wallet_id: String(walletId || cached.wallet_id || activeWallet?.id || ""),
    owner_public_key: String(ownerPublicKey || ""),
    owner_identifier: String(ownerIdentifier || ""),
    issuer_identifier: cached.issuer_identifier,
    token_name: cached.token_name,
    token_symbol: cached.token_symbol,
    decimals: cached.decimals,
    max_supply_raw: cached.max_supply_raw,
    issued_supply_raw: cached.issued_supply_raw,
    holder_amount_raw: holderAmountRaw,
    transfer_rule: cached.transfer_rule,
    policy_hash: cached.policy_hash,
    ...(regulatedProfile ? { regulated_profile: regulatedProfile } : {}),
    ...(cached.controller_regulated_profile ? { controller_regulated_profile: cached.controller_regulated_profile } : {}),
    holder_script_profile: omaReadL1TokenHolderScriptProfile(cached.holder_script_profile),
    asset_covenant_id: assetCovenantId,
    controller: {
      address: cached.controller.address,
      outpoint: cached.controller.outpoint,
      carrier_sompi: cached.controller.carrier_sompi,
      script_public_key_script: null,
      script_public_key_json_sha256: cached.controller.script_public_key_json_sha256,
      redeem_script_hex_sha256: cached.controller.redeem_script_hex_sha256,
      state_schema: cached.controller.state_schema
    },
    holder: {
      address: String(expected.address || ""),
      outpoint: holderOutpoint,
      carrier_sompi: String(expected.value_sompi || "0"),
      script_public_key_script: null,
      script_public_key_json_sha256: expected.script_public_key_json_sha256,
      redeem_script_hex_sha256: null,
      state_schema: String(expected.state_schema || OMA_L1_TOKEN_HOLDER_STATE_SCHEMA)
    }
  };
}

function replaceOmaL1TrackedAssetRecordsAfterHolderTransfer(repoRootPath: string, userId: string, sourceHolderOutpoints: string | string[], records: OmaL1TrackedAssetRecord[]): void {
  const store = readOmaL1TrackedAssetStore(repoRootPath, userId);
  const sourceOutpointSet = new Set((Array.isArray(sourceHolderOutpoints) ? sourceHolderOutpoints : [sourceHolderOutpoints])
    .map((outpoint) => String(outpoint || "").trim())
    .filter(Boolean));
  const newHolderOutpoints = new Set(records.map((record) => String(record.holder?.outpoint || "").trim()).filter(Boolean));
  const filtered = store.records.filter((existing: any) => {
    const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
    if (existingHolderOutpoint && sourceOutpointSet.has(existingHolderOutpoint)) return false;
    if (existingHolderOutpoint && newHolderOutpoints.has(existingHolderOutpoint)) return false;
    return true;
  });

  writeOmaL1TrackedAssetStore(repoRootPath, userId, {
    schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, ...records]
  });
}

function replaceOmaL1TrackedAssetRecordsAfterHolderBurn(repoRootPath: string, userId: string, sourceHolderOutpoints: string | string[], records: OmaL1TrackedAssetRecord[]): void {
  const store = readOmaL1TrackedAssetStore(repoRootPath, userId);
  const sourceOutpointSet = new Set((Array.isArray(sourceHolderOutpoints) ? sourceHolderOutpoints : [sourceHolderOutpoints])
    .map((outpoint) => String(outpoint || "").trim())
    .filter(Boolean));
  const newHolderOutpoints = new Set(records.map((record) => String(record.holder?.outpoint || "").trim()).filter(Boolean));
  const filtered = store.records.filter((existing: any) => {
    const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
    if (existingHolderOutpoint && sourceOutpointSet.has(existingHolderOutpoint)) return false;
    if (existingHolderOutpoint && newHolderOutpoints.has(existingHolderOutpoint)) return false;
    return true;
  });

  writeOmaL1TrackedAssetStore(repoRootPath, userId, {
    schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, ...records]
  });
}

function omaL1HolderBurnTrackedAssetCandidate(params: {
  cached: OmaL1HolderBurnBuildCacheEntry;
  activeWallet: any;
  submittedTxid: string;
  expected: OmaL1HolderBurnOutputSnapshot | null;
  outputRow: CovenantControlsBuildSourceRow | null;
}): OmaL1TrackedAssetRecord | null {
  const { cached, activeWallet, submittedTxid, expected, outputRow } = params;
  if (!expected || expected.role !== "sender_change_holder") return null;

  const assetCovenantId = String(cached.asset_covenant_id || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetCovenantId)) return null;
  if (String(expected.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;
  if (outputRow && String(outputRow.covenant_id || "").trim().toLowerCase() !== assetCovenantId) return null;

  const holderAmountRaw = String(expected.amount_raw || "0").trim();
  if (!/^\d+$/.test(holderAmountRaw) || BigInt(holderAmountRaw) <= 0n) return null;

  const holderOutpoint = outputRow ? (covenantInputOutpointKey(outputRow) || `${submittedTxid}:${expected.index}`) : `${submittedTxid}:${expected.index}`;
  const regulatedProfile = omaReadKcc20StoredRegulatedCompactState(cached.regulated_profile);
  const now = new Date().toISOString();

  return {
    record_kind: "oma_l1_tracked_asset_record_v1",
    record_status: "candidate_requires_live_reverification",
    created_at: now,
    updated_at: now,
    source: "oma_l1_holder_burn_submit_auto_track_v1",
    networkId: cached.networkId,
    wallet_id: String(cached.wallet_id || activeWallet?.id || ""),
    owner_public_key: cached.sender_owner_public_key,
    owner_identifier: cached.sender_owner_identifier,
    issuer_identifier: cached.issuer_identifier,
    token_name: cached.token_name,
    token_symbol: cached.token_symbol,
    decimals: cached.decimals,
    max_supply_raw: cached.max_supply_raw,
    issued_supply_raw: cached.issued_supply_raw,
    holder_amount_raw: holderAmountRaw,
    transfer_rule: cached.transfer_rule,
    policy_hash: cached.policy_hash,
    ...(regulatedProfile ? { regulated_profile: regulatedProfile } : {}),
    holder_script_profile: omaReadL1TokenHolderScriptProfile(cached.holder_script_profile),
    asset_covenant_id: assetCovenantId,
    controller: {
      address: cached.controller.address,
      outpoint: cached.controller.outpoint,
      carrier_sompi: cached.controller.carrier_sompi,
      script_public_key_script: null,
      script_public_key_json_sha256: cached.controller.script_public_key_json_sha256,
      redeem_script_hex_sha256: cached.controller.redeem_script_hex_sha256,
      state_schema: cached.controller.state_schema
    },
    holder: {
      address: String(expected.address || ""),
      outpoint: holderOutpoint,
      carrier_sompi: String(expected.value_sompi || "0"),
      script_public_key_script: null,
      script_public_key_json_sha256: expected.script_public_key_json_sha256,
      redeem_script_hex_sha256: null,
      state_schema: String(expected.state_schema || OMA_L1_TOKEN_HOLDER_STATE_SCHEMA)
    }
  };
}

function replaceOmaL1TrackedAssetRecordsAfterIssueSubmit(repoRootPath: string, userId: string, assetCovenantId: string, sourceControllerOutpoint: string, nextController: { address: string | null; outpoint: string; carrier_sompi: string | null; script_public_key_json_sha256: string | null; redeem_script_hex_sha256: string | null; state_schema: string | null }, issuedSupplyAfterRaw: string, newHolderRecord: OmaL1TrackedAssetRecord): void {
  const store = readOmaL1TrackedAssetStore(repoRootPath, userId);
  const assetId = String(assetCovenantId || "").trim().toLowerCase();
  const nextHolderOutpoint = String(newHolderRecord.holder?.outpoint || "").trim();
  const now = new Date().toISOString();
  const updatedRecords = store.records
    .filter((existing: any) => {
      const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
      if (existingHolderOutpoint === nextHolderOutpoint) return false;
      const existingAsset = String(existing?.asset_covenant_id || "").trim().toLowerCase();
      const existingControllerOutpoint = String(existing?.controller?.outpoint || "").trim();
      if (
        assetId &&
        existingAsset === assetId &&
        existing?.controller_only_zero_supply === true &&
        existingControllerOutpoint === String(sourceControllerOutpoint || "").trim()
      ) {
        return false;
      }
      return true;
    })
    .map((existing: any) => {
      const existingAsset = String(existing?.asset_covenant_id || "").trim().toLowerCase();
      if (!assetId || existingAsset !== assetId) return existing;
      return {
        ...existing,
        record_status: "candidate_requires_live_reverification",
        updated_at: now,
        source: String(existing?.source || "oma_l1_issue_submit_controller_update_v1"),
        issued_supply_raw: String(issuedSupplyAfterRaw),
        controller: {
          ...(existing.controller || {}),
          address: String(nextController.address || existing?.controller?.address || ""),
          outpoint: nextController.outpoint,
          carrier_sompi: String(nextController.carrier_sompi || existing?.controller?.carrier_sompi || "0"),
          script_public_key_script: null,
          script_public_key_json_sha256: nextController.script_public_key_json_sha256,
          redeem_script_hex_sha256: nextController.redeem_script_hex_sha256,
          state_schema: String(nextController.state_schema || existing?.controller?.state_schema || OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA)
        }
      };
    });

  const filtered = updatedRecords.filter((existing: any) => {
    const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
    return !nextHolderOutpoint || existingHolderOutpoint !== nextHolderOutpoint;
  });

  writeOmaL1TrackedAssetStore(repoRootPath, userId, {
    schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
    schema_version: 1,
    records: [...filtered, newHolderRecord]
  });
}


type OmaL1ResolvedLocalWalletAddress = {
  user_id: string;
  wallet_id: string;
  wallet_type: string | null;
  network: string | null;
  address: string;
  user_pubkey: string | null;
};

function omaL1DataUserIds(repoRootPath: string): string[] {
  const usersDir = path.join(repoRootPath, "data", "users");
  if (!fs.existsSync(usersDir)) return [];
  return fs.readdirSync(usersDir, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .map((entry) => entry.name)
    .filter((name) => !!name);
}

function resolveOmaL1LocalWalletByAddress(repoRootPath: string, address: string, networkId: string): OmaL1ResolvedLocalWalletAddress | null {
  const targetAddress = String(address || "").trim();
  if (!targetAddress) return null;

  for (const userId of omaL1DataUserIds(repoRootPath)) {
    let store: any = null;
    try {
      const walletsPath = path.join(repoRootPath, "data", "users", userId, "wallets.json");
      if (!fs.existsSync(walletsPath)) continue;
      store = readWalletStore(repoRootPath, userId);
    } catch {
      continue;
    }

    const items = Array.isArray(store?.items) ? store.items : [];
    for (const wallet of items) {
      const walletAddress = String(wallet?.address0 || "").trim();
      if (walletAddress !== targetAddress) continue;
      if (String(wallet?.state || "") !== "READY") continue;
      let walletNetworkId = "";
      try {
        walletNetworkId = rpcNetworkIdFromAppNetworkKey(appNetworkKeyFromWalletNetwork(wallet.network));
      } catch {
        walletNetworkId = "";
      }
      if (walletNetworkId !== networkId) continue;
      return {
        user_id: userId,
        wallet_id: String(wallet?.id || ""),
        wallet_type: wallet?.wallet_type ? String(wallet.wallet_type) : null,
        network: wallet?.network ? String(wallet.network) : null,
        address: walletAddress,
        user_pubkey: wallet?.user_pubkey ? String(wallet.user_pubkey) : null
      };
    }
  }

  return null;
}

function replaceOmaL1TrackedAssetRecordsAfterChangeOwnership(repoRootPath: string, params: {
  assetCovenantId: string;
  sourceControllerOutpoint: string;
  nextController: { address: string | null; outpoint: string; carrier_sompi: string | null; script_public_key_json_sha256: string | null; redeem_script_hex_sha256: string | null; state_schema: string | null };
  newIssuerIdentifier: string;
  issuedSupplyRaw: string;
  regulatedProfile: OmaL1TokenRegulatedCompactState | null;
  recipientUserId: string;
  recipientRecord: OmaL1TrackedAssetRecord;
}): { updated_user_count: number; updated_record_count: number; recipient_record_written: boolean } {
  const assetId = String(params.assetCovenantId || "").trim().toLowerCase();
  const now = new Date().toISOString();
  let updatedUserCount = 0;
  let updatedRecordCount = 0;
  let recipientRecordWritten = false;

  for (const userId of omaL1DataUserIds(repoRootPath)) {
    const store = readOmaL1TrackedAssetStore(repoRootPath, userId);
    let changed = false;
    const recipientHolderOutpoint = String(params.recipientRecord.holder?.outpoint || "").trim();

    const records = store.records
      .filter((existing: any) => {
        const existingHolderOutpoint = String(existing?.holder?.outpoint || "").trim();
        return !(userId === params.recipientUserId && recipientHolderOutpoint && existingHolderOutpoint === recipientHolderOutpoint);
      })
      .map((existing: any) => {
        const existingAsset = String(existing?.asset_covenant_id || "").trim().toLowerCase();
        if (!assetId || existingAsset !== assetId) return existing;
        changed = true;
        updatedRecordCount += 1;
        return {
          ...existing,
          record_status: "candidate_requires_live_reverification",
          updated_at: now,
          source: "oma_l1_change_ownership_submit_controller_update_v1",
          issuer_identifier: params.newIssuerIdentifier,
          issued_supply_raw: String(params.issuedSupplyRaw),
          ...(params.regulatedProfile ? { regulated_profile: params.regulatedProfile } : {}),
          controller: {
            ...(existing.controller || {}),
            address: String(params.nextController.address || existing?.controller?.address || ""),
            outpoint: params.nextController.outpoint,
            carrier_sompi: String(params.nextController.carrier_sompi || existing?.controller?.carrier_sompi || "0"),
            script_public_key_script: null,
            script_public_key_json_sha256: params.nextController.script_public_key_json_sha256,
            redeem_script_hex_sha256: params.nextController.redeem_script_hex_sha256,
            state_schema: String(params.nextController.state_schema || existing?.controller?.state_schema || OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA)
          }
        };
      });

    if (userId === params.recipientUserId) {
      records.push(params.recipientRecord);
      recipientRecordWritten = true;
      changed = true;
    }

    if (changed) {
      writeOmaL1TrackedAssetStore(repoRootPath, userId, {
        schema_kind: OMA_L1_TRACKED_ASSETS_SCHEMA_KIND,
        schema_version: 1,
        records
      });
      updatedUserCount += 1;
    }
  }

  return { updated_user_count: updatedUserCount, updated_record_count: updatedRecordCount, recipient_record_written: recipientRecordWritten };
}


function pendingOmaL1BurnReceiptsForControllerSupply(params: { repoRootPath: string; userId: string; networkId: string; walletId: string; ownerIdentifier: string; assetCovenantId: string; receiptSubmittedTxid?: string | null }): OmaL1BurnReceiptRecord[] {
  const assetId = String(params.assetCovenantId || "").trim().toLowerCase();
  const requestedTxid = String(params.receiptSubmittedTxid || "").trim().toLowerCase();
  return readOmaL1BurnReceiptStore(params.repoRootPath, params.userId).records
    .filter((record: any) => record && record.record_kind === "oma_l1_holder_burn_receipt_v1")
    .filter((record: any) => omaL1NormalizeNetworkId(record.networkId) === params.networkId)
    .filter((record: any) => String(record.wallet_id || "").trim() === params.walletId)
    .filter((record: any) => String(record.owner_identifier || "").trim() === params.ownerIdentifier)
    .filter((record: any) => String(record.asset_covenant_id || "").trim().toLowerCase() === assetId)
    .filter((record: any) => String(record.controller_supply_update_status || "").trim() === "not_updated_in_holder_burn_v1_next_controller_supply_module_required")
    .filter((record: any) => !requestedTxid || String(record.submitted_txid || "").trim().toLowerCase() === requestedTxid);
}

