function markOmaL1BurnReceiptsControllerSupplyUpdated(repoRootPath: string, userId: string, receiptSubmittedTxids: string[], update: { submittedTxid: string; nextControllerOutpoint: string; issuedSupplyAfterRaw: string }): void {
  const receiptSet = new Set(receiptSubmittedTxids.map((txid) => String(txid || "").trim().toLowerCase()).filter(Boolean));
  const store = readOmaL1BurnReceiptStore(repoRootPath, userId);
  const now = new Date().toISOString();
  const records = store.records.map((record: any) => {
    const receiptTxid = String(record?.submitted_txid || "").trim().toLowerCase();
    if (!receiptSet.has(receiptTxid)) return record;
    return {
      ...record,
      record_status: "accepted_submit_burn_receipt_controller_supply_updated_v1",
      updated_at: now,
      controller_supply_update_status: "updated_after_controller_supply_submit_v1",
      controller_supply_update_txid: update.submittedTxid,
      controller_supply_update_controller_outpoint: update.nextControllerOutpoint,
      controller_supply_update_issued_supply_after_raw: update.issuedSupplyAfterRaw,
      controller_supply_update_applied_at: now
    };
  });

  writeOmaL1BurnReceiptStore(repoRootPath, userId, {
    schema_kind: OMA_L1_BURN_RECEIPTS_SCHEMA_KIND,
    schema_version: 1,
    records
  });
}

function omaL1HolderTransferCacheSourceHolders(cached: OmaL1HolderTransferBuildCacheEntry): OmaL1HolderTransferSourceCacheEntry[] {
  const sources = Array.isArray((cached as any).source_holders) ? (cached as any).source_holders : [];
  const normalized = sources.map((source: any, index: number) => ({
    input_index: Number.isInteger(Number(source?.input_index)) ? Number(source.input_index) : index,
    holder_outpoint: String(source?.holder_outpoint || "").trim(),
    holder_address: String(source?.holder_address || "").trim(),
    holder_carrier_sompi: String(source?.holder_carrier_sompi || "").trim(),
    holder_amount_raw: String(source?.holder_amount_raw || "").trim(),
    holder_script_public_key_json_sha256: source?.holder_script_public_key_json_sha256 || null,
    holder_redeem_script_hex_sha256: source?.holder_redeem_script_hex_sha256 || null,
    owner_public_key: String(source?.owner_public_key || cached.sender_owner_public_key || "").trim(),
    owner_identifier: String(source?.owner_identifier || cached.sender_owner_identifier || "").trim()
  })).filter((source: OmaL1HolderTransferSourceCacheEntry) => source.holder_outpoint && source.holder_address && /^\d+$/.test(source.holder_carrier_sompi) && /^\d+$/.test(source.holder_amount_raw));
  if (normalized.length > 0) return normalized;
  return [{
    input_index: 0,
    holder_outpoint: cached.source_holder_outpoint,
    holder_address: cached.source_holder_address,
    holder_carrier_sompi: cached.source_holder_carrier_sompi,
    holder_amount_raw: cached.source_holder_amount_raw,
    holder_script_public_key_json_sha256: cached.source_holder_script_public_key_json_sha256,
    holder_redeem_script_hex_sha256: cached.source_holder_redeem_script_hex_sha256,
    owner_public_key: cached.sender_owner_public_key,
    owner_identifier: cached.sender_owner_identifier
  }].filter((source) => source.holder_outpoint && source.holder_address && /^\d+$/.test(source.holder_carrier_sompi) && /^\d+$/.test(source.holder_amount_raw));
}

