function omaL1ControllerOwnerXOnlyFromTrackedRecord(record: OmaL1TrackedAssetRecord, holderOwnerXOnlyPublicKey: string, activeAddress: string): { ok: boolean; reason?: string; ownerXOnlyPublicKey?: string; issuerIdentifier?: string; source?: string } {
  const issuerIdentifier = String(record.issuer_identifier || activeAddress || "").trim();
  if (!issuerIdentifier) return { ok: false, reason: "tracked_controller_issuer_identifier_required" };

  if (issuerIdentifier === activeAddress) {
    return {
      ok: true,
      ownerXOnlyPublicKey: holderOwnerXOnlyPublicKey,
      issuerIdentifier,
      source: "controller_owner_matches_active_holder_owner"
    };
  }

  try {
    const issuerAddress = new Address(issuerIdentifier);
    const issuerAddressVersion = String((issuerAddress as any).version || "");
    if (issuerAddressVersion !== "PubKey") {
      return {
        ok: false,
        reason: "tracked_controller_issuer_address_public_key_not_derivable",
        issuerIdentifier,
        source: issuerAddressVersion || "unknown_address_version"
      };
    }

    const issuerXOnlyPublicKey = XOnlyPublicKey.fromAddress(issuerAddress as any).toString();
    if (!/^[0-9a-f]{64}$/i.test(issuerXOnlyPublicKey)) {
      return {
        ok: false,
        reason: "tracked_controller_issuer_xonly_invalid_shape",
        issuerIdentifier,
        source: "derived_controller_xonly_from_pubkey_issuer_identifier"
      };
    }

    return {
      ok: true,
      ownerXOnlyPublicKey: issuerXOnlyPublicKey,
      issuerIdentifier,
      source: "derived_controller_xonly_from_pubkey_issuer_identifier"
    };
  } catch {
    return {
      ok: false,
      reason: "tracked_controller_issuer_identifier_not_address",
      issuerIdentifier,
      source: "controller_owner_may_differ_from_holder_owner"
    };
  }
}

function omaL1ExpectedEnvelopesFromTrackedRecord(record: OmaL1TrackedAssetRecord, activeAddress: string, networkId: string, siblingRecords: OmaL1TrackedAssetRecord[] = []): { ok: boolean; reason?: string; ownerAddress?: string; controller?: OmaL1TokenStateEnvelopeProof; holder?: OmaL1TokenStateEnvelopeProof; controller_only_zero_supply?: boolean; controller_regulated_profile?: OmaL1TokenRegulatedCompactState | null } {
  try {
    const normalizedNetwork = omaL1NormalizeNetworkId(record.networkId);
    if (normalizedNetwork !== networkId) return { ok: false, reason: "tracked_record_network_mismatch" };

    const holderOwnerPublicKeyHex = String(record.owner_public_key || "").trim();
    if (!/^[0-9a-f]{64}$|^[0-9a-f]{66}$/i.test(holderOwnerPublicKeyHex)) return { ok: false, reason: "tracked_owner_public_key_invalid_shape" };

    const holderOwnerPublicKey = new PublicKey(holderOwnerPublicKeyHex);
    const ownerAddress = holderOwnerPublicKey.toAddress(networkId).toString();
    if (ownerAddress !== activeAddress) return { ok: false, reason: "tracked_owner_public_key_not_active_wallet", ownerAddress };

    const tokenName = omaSafeText(record.token_name, "token_name", 64);
    const tokenSymbol = omaSafeSymbol(record.token_symbol);
    const decimals = omaReadUintNumber(record.decimals, "decimals", 0, 18);
    const maxSupplyRaw = omaReadNonnegativeRawInteger(record.max_supply_raw, "max_supply_raw");
    const issuedSupplyRaw = omaReadNonnegativeRawInteger(record.issued_supply_raw, "issued_supply_raw");
    const holderAmountRaw = omaReadNonnegativeRawInteger(record.holder_amount_raw, "holder_amount_raw");
    if (maxSupplyRaw <= 0n) return { ok: false, reason: "tracked_max_supply_raw_not_positive" };
    if (issuedSupplyRaw > maxSupplyRaw) return { ok: false, reason: "tracked_issued_supply_exceeds_max_supply" };
    if (holderAmountRaw > issuedSupplyRaw) return { ok: false, reason: "tracked_holder_amount_exceeds_issued_supply" };

    const transferRule = omaSafeOptionalText(record.transfer_rule, 80) || "owner_signature_required";
    const policyHash = omaSafeOptionalText(record.policy_hash, 128);
    const regulatedProfile = omaReadKcc20StoredRegulatedCompactState(record.regulated_profile);
    const controllerRegulatedProfileCandidates: OmaL1TokenRegulatedCompactState[] = [];
    const controllerProfileKeys = new Set<string>();
    const addControllerRegulatedProfileCandidate = (value: unknown): void => {
      let candidate: OmaL1TokenRegulatedCompactState | null = null;
      try { candidate = omaReadKcc20StoredRegulatedCompactState(value); } catch { candidate = null; }
      if (!candidate) return;
      if (regulatedProfile && (candidate.rg !== regulatedProfile.rg || candidate.rv !== regulatedProfile.rv || candidate.pr !== regulatedProfile.pr || candidate.fc !== regulatedProfile.fc)) return;
      const key = omaStableJson(candidate);
      if (controllerProfileKeys.has(key)) return;
      controllerProfileKeys.add(key);
      controllerRegulatedProfileCandidates.push(candidate);
    };
    addControllerRegulatedProfileCandidate(record.controller_regulated_profile);
    addControllerRegulatedProfileCandidate(regulatedProfile);
    const recordAssetId = String(record.asset_covenant_id || "").trim().toLowerCase();
    const recordControllerOutpoint = String(record.controller?.outpoint || "").trim();
    const recordControllerScriptHash = String(record.controller?.script_public_key_json_sha256 || "").trim().toLowerCase();
    for (const sibling of siblingRecords) {
      if (String(sibling?.asset_covenant_id || "").trim().toLowerCase() !== recordAssetId) continue;
      if (recordControllerOutpoint && String(sibling?.controller?.outpoint || "").trim() !== recordControllerOutpoint) continue;
      const siblingControllerHash = String(sibling?.controller?.script_public_key_json_sha256 || "").trim().toLowerCase();
      if (recordControllerScriptHash && siblingControllerHash && siblingControllerHash !== recordControllerScriptHash) continue;
      addControllerRegulatedProfileCandidate(sibling?.controller_regulated_profile);
      addControllerRegulatedProfileCandidate(sibling?.regulated_profile);
    }
    const controllerOnlyZeroSupply = record.controller_only_zero_supply === true;
    if (controllerOnlyZeroSupply && (!regulatedProfile || issuedSupplyRaw !== 0n || holderAmountRaw !== 0n)) {
      return { ok: false, reason: "tracked_controller_only_zero_supply_record_invalid" };
    }

    const holderOwnerXOnlyPublicKey = holderOwnerPublicKey.toXOnlyPublicKey().toString();
    const controllerOwner = omaL1ControllerOwnerXOnlyFromTrackedRecord(record, holderOwnerXOnlyPublicKey, activeAddress);
    if (!controllerOwner.ok || !controllerOwner.ownerXOnlyPublicKey || !controllerOwner.issuerIdentifier) {
      return { ok: false, reason: controllerOwner.reason || "tracked_controller_owner_xonly_not_derivable" };
    }

    const controllerStateSchema = String(record.controller?.state_schema || OMA_L1_TOKEN_CONTROLLER_STATE_SCHEMA);
    if (regulatedProfile && controllerStateSchema !== OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA) {
      return { ok: false, reason: "tracked_regulated_controller_compact_schema_required" };
    }
    const controllerBaseFields = omaBuildL1TokenControllerEnvelopeFields({
      role: "controller",
      tokenName,
      tokenSymbol,
      decimals,
      maxSupplyRaw,
      issuedSupplyRaw,
      holderAmountRaw: 0n,
      ownerIdentifier: activeAddress,
      issuerIdentifier: controllerOwner.issuerIdentifier,
      transferRule,
      policyHash
    }, controllerStateSchema);
    let controllerRegulatedProfile: OmaL1TokenRegulatedCompactState | null = null;
    let controller: OmaL1TokenStateEnvelopeProof | null = null;
    if (regulatedProfile) {
      for (const candidateProfile of controllerRegulatedProfileCandidates) {
        const candidateFields = omaBuildKcc20RegulatedCompactStateFields(controllerBaseFields, candidateProfile);
        const candidateController = omaBuildStateEnvelopeScriptPublicKey({ role: "controller", ownerXOnlyPublicKey: controllerOwner.ownerXOnlyPublicKey, fields: candidateFields });
        if (recordControllerScriptHash && String(candidateController.p2sh_script_public_key_json_sha256 || "").toLowerCase() !== recordControllerScriptHash) continue;
        controllerRegulatedProfile = candidateProfile;
        controller = candidateController;
        break;
      }
      if (!controller || !controllerRegulatedProfile) return { ok: false, reason: "tracked_controller_regulated_profile_not_resolved" };
    } else {
      controller = omaBuildStateEnvelopeScriptPublicKey({ role: "controller", ownerXOnlyPublicKey: controllerOwner.ownerXOnlyPublicKey, fields: controllerBaseFields });
    }
    if (!controller.decode_round_trip_ok || !controller.script_contains_state_envelope) return { ok: false, reason: "tracked_controller_envelope_not_rebuildable" };

    if (controllerOnlyZeroSupply) {
      return { ok: true, ownerAddress, controller, controller_only_zero_supply: true, controller_regulated_profile: controllerRegulatedProfile };
    }

    const holderStateSchema = String(record.holder?.state_schema || OMA_L1_TOKEN_HOLDER_STATE_SCHEMA);
    const holderScriptProfile = omaReadL1TokenHolderScriptProfile(record.holder_script_profile);
    if (holderScriptProfile === OMA_L1_TOKEN_HOLDER_SCRIPT_PROFILE_REGULATED_REGISTRY_CONTROL_V1 && !regulatedProfile) {
      return { ok: false, reason: "tracked_control_holder_regulated_profile_required" };
    }
    if (regulatedProfile && holderStateSchema !== OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA) {
      return { ok: false, reason: "tracked_regulated_holder_legacy_or_unsupported_schema" };
    }
    const holderFields = omaBuildKcc20RegulatedCompactStateFields(
      holderStateSchema === OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA
        ? omaBuildL1TokenCompactHolderEnvelopeFields({
            tokenSymbol,
            decimals,
            holderAmountRaw,
            ownerIdentifierType: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS as OmaL1TokenCompactHolderOwnerType,
            ownerIdentifier: activeAddress
          })
        : omaBuildL1TokenEnvelopeFields({
            role: "holder",
            tokenName,
            tokenSymbol,
            decimals,
            maxSupplyRaw,
            issuedSupplyRaw,
            holderAmountRaw,
            ownerIdentifier: activeAddress,
            issuerIdentifier: controllerOwner.issuerIdentifier,
            transferRule,
            policyHash
          }),
      regulatedProfile
    );
    const holder = omaBuildHolderStateEnvelopeScriptPublicKey({
      ownerXOnlyPublicKey: holderOwnerXOnlyPublicKey,
      fields: holderFields,
      holderScriptProfile,
      registryCovenantId: regulatedProfile?.pr || null
    });
    if (!holder.decode_round_trip_ok || !holder.script_contains_state_envelope) return { ok: false, reason: "tracked_holder_envelope_not_rebuildable" };

    return { ok: true, ownerAddress, controller, holder, controller_only_zero_supply: false, controller_regulated_profile: controllerRegulatedProfile };
  } catch (err) {
    return { ok: false, reason: `tracked_record_rebuild_failed:${String(err)}` };
  }
}

async function omaL1TrackedRowsForAddress(rpc: InstanceType<typeof ToccataRpcClient>, address: string): Promise<OmaL1TrackedLiveRow[]> {
  const response = await rpc.getUtxosByAddresses({ addresses: [address] });
  const entries = covenantEntriesFromResponse(response);
  return entries.map((entry: any) => {
    const covenant = covenantIdFromReference(entry);
    const scriptPublicKey = covenantScriptPublicKeyPublicFields(entry);
    const amount_sompi = covenantAmountSompiFromReference(entry);
    return {
      outpoint: covenantOutpointFromReference(entry),
      amount_sompi,
      amount_kas: sompiTextToKasText(amount_sompi),
      covenant_present: covenant.present,
      covenant_id: covenant.value ? String(covenant.value).toLowerCase() : null,
      covenant_path: covenant.path,
      script_public_key_script: scriptPublicKey.script_public_key_script,
      script_public_key_json_sha256: scriptPublicKey.script_public_key_json_sha256
    };
  });
}

function omaL1FindTrackedLiveRow(rows: OmaL1TrackedLiveRow[], expectedScript: string | null, expectedOutpoint: string | null): OmaL1TrackedLiveRow | null {
  const script = String(expectedScript || "").trim().toLowerCase();
  const outpoint = String(expectedOutpoint || "").trim();
  if (!script) return null;
  return rows.find((row) => {
    if (String(row.script_public_key_script || "").trim().toLowerCase() !== script) return false;
    if (outpoint && String(row.outpoint?.text || "").trim() !== outpoint) return false;
    return row.covenant_present === true && !!row.covenant_id;
  }) || null;
}

function omaL1FormatRawAmountHumanServer(amountRaw: string, decimals: number): string {
  try {
    const raw = String(amountRaw || "").trim();
    if (!/^\d+$/.test(raw) || !Number.isInteger(decimals) || decimals < 0 || decimals > 18) return raw || "0";
    if (decimals === 0) return raw;
    const base = 10n ** BigInt(decimals);
    const value = BigInt(raw);
    const whole = value / base;
    const frac = value % base;
    const fracText = frac.toString().padStart(decimals, "0").replace(/0+$/, "");
    return fracText ? `${whole.toString()}.${fracText}` : whole.toString();
  } catch {
    return String(amountRaw || "0");
  }
}

async function verifyOmaL1TrackedAssetRecordLive(params: {
  rpc: InstanceType<typeof ToccataRpcClient>;
  record: OmaL1TrackedAssetRecord;
  activeWallet: any;
  networkId: string;
  siblingRecords?: OmaL1TrackedAssetRecord[];
}): Promise<OmaL1TrackedVerification> {
  const { rpc, record, activeWallet, networkId } = params;
  const expected = omaL1ExpectedEnvelopesFromTrackedRecord(record, String(activeWallet.address0 || ""), networkId, params.siblingRecords || []);
  if (!expected.ok || !expected.controller) return { ok: false, reason: expected.reason || "tracked_record_expected_envelope_failed" };

  const controllerOnlyZeroSupply = expected.controller_only_zero_supply === true;
  if (!controllerOnlyZeroSupply && !expected.holder) return { ok: false, reason: expected.reason || "tracked_holder_expected_envelope_failed" };

  const controllerScript = expected.controller.script_public_key_json?.script ? String(expected.controller.script_public_key_json.script).toLowerCase() : null;
  const holderScript = expected.holder?.script_public_key_json?.script ? String(expected.holder.script_public_key_json.script).toLowerCase() : null;

  const controllerRows = await omaL1TrackedRowsForAddress(rpc, String(record.controller?.address || ""));
  const controllerRow = omaL1FindTrackedLiveRow(controllerRows, controllerScript, record.controller?.outpoint || null);
  if (!controllerRow) return { ok: false, reason: "tracked_controller_live_row_not_found" };

  let holderRow: OmaL1TrackedLiveRow | null = null;
  if (!controllerOnlyZeroSupply) {
    const holderRows = await omaL1TrackedRowsForAddress(rpc, String(record.holder?.address || ""));
    holderRow = omaL1FindTrackedLiveRow(holderRows, holderScript, record.holder?.outpoint || null);
    if (!holderRow) return { ok: false, reason: "tracked_holder_live_row_not_found" };
  }

  const controllerCovenantId = String(controllerRow.covenant_id || "").toLowerCase();
  const holderCovenantId = holderRow ? String(holderRow.covenant_id || "").toLowerCase() : controllerCovenantId;
  if (!/^[0-9a-f]{64}$/.test(controllerCovenantId) || controllerCovenantId !== holderCovenantId) {
    return { ok: false, reason: "tracked_live_covenant_id_mismatch" };
  }

  const storedAssetId = String(record.asset_covenant_id || "").trim().toLowerCase();
  if (storedAssetId && storedAssetId !== controllerCovenantId) return { ok: false, reason: "tracked_stored_asset_covenant_id_mismatch" };

  const holderFields = expected.holder?.decoded_fields || {};
  const holderStateSchema = controllerOnlyZeroSupply
    ? String(record.holder?.state_schema || OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA)
    : String(expected.holder?.state_schema || record.holder?.state_schema || "");
  const compactHolder = holderStateSchema === OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA;
  const decimals = Number(controllerOnlyZeroSupply
    ? record.decimals
    : (compactHolder ? holderFields.d : holderFields.decimals));
  const safeDecimals = Number.isFinite(decimals) ? decimals : 0;
  const amountRaw = controllerOnlyZeroSupply
    ? "0"
    : String((compactHolder ? holderFields.q : holderFields.amount_raw) || "0");
  const tokenSymbol = controllerOnlyZeroSupply
    ? String(record.token_symbol || "KCC20-Regulated")
    : String((compactHolder ? holderFields.t : holderFields.token_symbol) || record.token_symbol || "OMA L1");
  const tokenName = String(record.token_name || tokenSymbol);
  const maxSupplyRaw = String(record.max_supply_raw || "0");
  const issuedSupplyRaw = String(record.issued_supply_raw || "0");
  const transferRule = String(record.transfer_rule || (compactHolder ? "owner_signature_required" : holderFields.transfer_rule) || "");
  const policyHash = typeof record.policy_hash === "string" && record.policy_hash.trim() ? record.policy_hash.trim() : null;
  const issuerIdentifier = String(record.issuer_identifier || "");
  const controllerStateSchema = String(expected.controller.state_schema || record.controller?.state_schema || "");
  const regulatedProfile = omaReadKcc20StoredRegulatedCompactState(record.regulated_profile);

  const verifiedRecord: OmaL1TrackedAssetRecord = {
    ...record,
    record_status: "live_verified",
    updated_at: new Date().toISOString(),
    asset_covenant_id: controllerCovenantId,
    ...(controllerOnlyZeroSupply ? { controller_only_zero_supply: true } : {}),
    ...(expected.controller_regulated_profile ? { controller_regulated_profile: expected.controller_regulated_profile } : {}),
    controller: {
      ...record.controller,
      outpoint: controllerRow.outpoint.text || record.controller.outpoint || null,
      script_public_key_script: controllerScript,
      script_public_key_json_sha256: controllerRow.script_public_key_json_sha256 || expected.controller.p2sh_script_public_key_json_sha256 || null,
      redeem_script_hex_sha256: expected.controller.redeem_script_hex_sha256,
      state_schema: expected.controller.state_schema
    },
    holder: controllerOnlyZeroSupply ? {
      ...record.holder,
      address: "",
      outpoint: null,
      carrier_sompi: "0",
      script_public_key_script: null,
      script_public_key_json_sha256: null,
      redeem_script_hex_sha256: null,
      state_schema: OMA_L1_TOKEN_HOLDER_COMPACT_STATE_SCHEMA
    } : {
      ...record.holder,
      outpoint: holderRow?.outpoint.text || record.holder.outpoint || null,
      script_public_key_script: holderScript,
      script_public_key_json_sha256: holderRow?.script_public_key_json_sha256 || expected.holder?.p2sh_script_public_key_json_sha256 || null,
      redeem_script_hex_sha256: expected.holder?.redeem_script_hex_sha256 || null,
      state_schema: expected.holder?.state_schema || record.holder.state_schema
    }
  };

  return {
    ok: true,
    record: verifiedRecord,
    controller_row: controllerRow,
    ...(holderRow ? { holder_row: holderRow } : {}),
    token: {
      asset_kind: "oma_l1_covenant_token",
      proof_kind: controllerOnlyZeroSupply
        ? "oma_l1_tracked_controller_only_zero_supply_live_verified_v1"
        : "oma_l1_tracked_record_live_verified_v1",
      verification_status: controllerOnlyZeroSupply
        ? "live_chain_recomputed_controller_only_zero_supply_match"
        : "live_chain_recomputed_p2sh_match",
      stored_record_used_as_candidate_only: true,
      stored_record_drift_allowed: false,
      token: true,
      send_enabled: false,
      normal_send_eligible: false,
      token_transfer_enabled: false,
      controller_only_zero_supply: controllerOnlyZeroSupply,
      token_symbol: tokenSymbol,
      token_name: tokenName,
      amount_raw: amountRaw,
      amount_human: omaL1FormatRawAmountHumanServer(amountRaw, safeDecimals),
      decimals: safeDecimals,
      max_supply_raw: maxSupplyRaw,
      max_supply_human: omaL1FormatRawAmountHumanServer(maxSupplyRaw, safeDecimals),
      issued_supply_raw: issuedSupplyRaw,
      issued_supply_human: omaL1FormatRawAmountHumanServer(issuedSupplyRaw, safeDecimals),
      transfer_rule: transferRule,
      policy_hash: policyHash,
      issuer_identifier: issuerIdentifier,
      ...(regulatedProfile ? {
        regulated_profile_kind: OMA_L1_TOKEN_REGULATED_PROFILE_KIND,
        regulated_profile: regulatedProfile
      } : {}),
      holder_script_profile: omaReadL1TokenHolderScriptProfile(record.holder_script_profile),
      controller_state_schema: controllerStateSchema,
      holder_state_schema: holderStateSchema,
      owner_identifier: controllerOnlyZeroSupply
        ? String(record.owner_identifier || "")
        : String(holderFields.owner_identifier || record.owner_identifier || ""),
      asset_covenant_id: controllerCovenantId,
      holder_address: controllerOnlyZeroSupply ? null : String(record.holder?.address || ""),
      holder_outpoint: controllerOnlyZeroSupply ? null : holderRow?.outpoint.text || null,
      holder_carrier_kas: controllerOnlyZeroSupply ? "0" : holderRow?.amount_kas || null,
      holder_carrier_sompi: controllerOnlyZeroSupply ? "0" : holderRow?.amount_sompi || null,
      holder_script_public_key_json_sha256: controllerOnlyZeroSupply ? null : holderRow?.script_public_key_json_sha256 || null,
      holder_redeem_script_hex_sha256: controllerOnlyZeroSupply ? null : expected.holder?.redeem_script_hex_sha256 || null,
      controller_address: String(record.controller?.address || ""),
      controller_outpoint: controllerRow.outpoint.text,
      controller_carrier_kas: controllerRow.amount_kas,
      controller_carrier_sompi: controllerRow.amount_sompi,
      controller_script_public_key_json_sha256: controllerRow.script_public_key_json_sha256 || null,
      controller_redeem_script_hex_sha256: expected.controller.redeem_script_hex_sha256,
      verification_rule: controllerOnlyZeroSupply
        ? "rebuild_controller_state_envelope_then_match_live_p2sh_script_and_covenant_id"
        : "rebuild_state_envelope_from_public_record_then_match_live_p2sh_script_and_covenant_id",
      warning: controllerOnlyZeroSupply
        ? "Verified KCC20-Regulated issuer controller with zero issued supply. Use the regulated Issue workflow to create the first holder output."
        : "Verified OMA L1 holder token. Token transfer is disabled until a covenant-aware holder transfer path is proven.",
      human_amount_display_rule: "amount_human = amount_raw / 10^decimals; display only; amount_raw remains canonical"
    }
  };
}

async function verifiedOmaL1TokensFromTrackedRecords(params: {
  repoRootPath: string;
  userId: string;
  activeWallet: any;
  networkId: string;
}): Promise<{ ok: boolean; tokens: any[]; verified_records: OmaL1TrackedAssetRecord[]; reasons: string[]; record_count: number }> {
  const store = readOmaL1TrackedAssetStore(params.repoRootPath, params.userId);
  const networkRecords = store.records.filter((record: any) => omaL1NormalizeNetworkId(record?.networkId) === params.networkId);
  const assetsWithPositiveSupplyHolder = new Set(
    networkRecords
      .filter((record: any) => {
        const issuedSupplyRaw = String(record?.issued_supply_raw || "0").trim();
        const holderOutpoint = String(record?.holder?.outpoint || "").trim();
        return record?.controller_only_zero_supply !== true && /^\d+$/.test(issuedSupplyRaw) && BigInt(issuedSupplyRaw) > 0n && !!holderOutpoint;
      })
      .map((record: any) => String(record?.asset_covenant_id || "").trim().toLowerCase())
      .filter(Boolean)
  );
  const records = networkRecords.filter((record: any) => {
    const assetId = String(record?.asset_covenant_id || "").trim().toLowerCase();
    return !(record?.controller_only_zero_supply === true && assetsWithPositiveSupplyHolder.has(assetId));
  });
  if (records.length === 0) {
    return { ok: true, tokens: [], verified_records: [], reasons: [], record_count: networkRecords.length };
  }

  await ensureKaspaToccataReady(params.repoRootPath);
  const rpc = createToccataCovenantRpcClient(params.networkId);
  try {
    await rpc.connect();
    const tokens: any[] = [];
    const verifiedRecords: OmaL1TrackedAssetRecord[] = [];
    const reasons: string[] = [];

    for (const record of records) {
      const verified = await verifyOmaL1TrackedAssetRecordLive({ rpc, record, activeWallet: params.activeWallet, networkId: params.networkId, siblingRecords: records });
      if (verified.ok && verified.token && verified.record) {
        tokens.push(verified.token);
        verifiedRecords.push(verified.record);
      } else {
        reasons.push(verified.reason || "tracked_record_not_verified");
      }
    }

    return { ok: true, tokens, verified_records: verifiedRecords, reasons, record_count: networkRecords.length };
  } finally {
    try { await rpc.disconnect(); } catch { /* tracked holdings scan cleanup only */ }
  }
}

async function attachTrackedOmaL1HoldingsToResponse(params: {
  repoRootPath: string;
  userId: string;
  activeWallet: any;
  networkId: string;
  holdings: any;
}): Promise<void> {
  try {
    const result = await verifiedOmaL1TokensFromTrackedRecords({
      repoRootPath: params.repoRootPath,
      userId: params.userId,
      activeWallet: params.activeWallet,
      networkId: params.networkId
    });

    params.holdings.oma_l1 = {
      ok: result.ok,
      recognition_kind: "oma_l1_tracked_holdings_v1",
      recognition_status: "server_live_verified",
      source: "server_tracked_record_live_verified",
      networkId: params.networkId,
      tokens: result.tokens,
      token_count: result.tokens.length,
      tracked_record_count: result.record_count,
      rejected_record_reasons: result.reasons,
      stored_record_used_as_candidate_only: true,
      stored_record_drift_allowed: false,
      verification_rule: "rebuild_state_envelope_from_public_record_then_match_live_p2sh_script_and_covenant_id",
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    };
  } catch (err) {
    params.holdings.oma_l1 = {
      ok: false,
      recognition_kind: "oma_l1_tracked_holdings_v1",
      recognition_status: "server_live_verification_failed_closed",
      source: "server_tracked_record_live_verified",
      reason: String(err),
      tokens: [],
      token_count: 0,
      stored_record_used_as_candidate_only: true,
      stored_record_drift_allowed: false,
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    };
  }
}

app.post("/api/covenants/issuer-token/tracked-assets/import-known", async (req, res) => {
  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active || String(active.state || "") !== "READY" || !active.address0 || !active.network) {
      return res.status(409).json({
        ok: false,
        reason: "active_wallet_required",
        import_kind: "oma_l1_known_holder_tracking_import_v1",
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKeyFromWalletNetwork(active.network));
    if (networkId !== "testnet-10") {
      return res.status(409).json({
        ok: false,
        reason: "known_oma_l1_import_requires_testnet_10",
        network: active.network,
        networkId,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const ownerPublicKey = String((req.body as any)?.owner_public_key || (req.body as any)?.ownerPublicKey || "").trim();
    const candidate = omaL1KnownHolderImportCandidate({
      networkId,
      walletId: String(active.id || ""),
      ownerPublicKey,
      ownerIdentifier: String(active.address0 || "")
    });

    const rpc = createToccataCovenantRpcClient(networkId);
    try {
      await rpc.connect();
      const verified = await verifyOmaL1TrackedAssetRecordLive({ rpc, record: candidate, activeWallet: active, networkId });
      if (!verified.ok || !verified.record || !verified.token) {
        return res.status(409).json({
          ok: false,
          reason: verified.reason || "known_oma_l1_import_not_live_verified",
          import_kind: "oma_l1_known_holder_tracking_import_v1",
          stored_record_written: false,
          stored_record_used_as_candidate_only: true,
          stored_record_drift_allowed: false,
          signing_enabled: false,
          broadcasting_enabled: false,
          minting_enabled: false
        });
      }

      upsertOmaL1TrackedAssetRecord(repoRoot, userId, verified.record);

      return res.json({
        ok: true,
        import_kind: "oma_l1_known_holder_tracking_import_v1",
        import_status: "stored_after_live_chain_verification",
        stored_record_written: true,
        stored_record_path_kind: OMA_L1_TRACKED_ASSETS_FILE_NAME,
        stored_record_used_as_candidate_only: true,
        stored_record_drift_allowed: false,
        verification_rule: "rebuild_state_envelope_from_public_record_then_match_live_p2sh_script_and_covenant_id",
        asset_covenant_id: verified.record.asset_covenant_id,
        token: verified.token,
        controller_outpoint: verified.record.controller.outpoint,
        holder_outpoint: verified.record.holder.outpoint,
        private_key_printed: false,
        owner_public_key_echoed: false,
        signed_transaction_printed: false,
        signature_script_printed: false,
        submit_token_printed: false,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    } finally {
      try { await rpc.disconnect(); } catch { /* import scan cleanup only */ }
    }
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "oma_l1_known_holder_tracking_import_failed",
      error: String(err),
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    });
  }
});

type OmaKcc20RegulatedAuthoritativeRulebookVerifiedData = {
  rulebook: Record<string, unknown>;
  canonical_rulebook_json: string;
  rulebook_root: string;
  policy_epoch: number;
  source_policy_snapshot_id: string;
  network: string;
};

type OmaKcc20RegulatedAuthoritativeRulebookVerificationResult = {
  status: number;
  body: Record<string, unknown>;
  verified?: OmaKcc20RegulatedAuthoritativeRulebookVerifiedData;
};

async function omaVerifyKcc20RegulatedAuthoritativeRulebook(
  repoRoot: string
): Promise<OmaKcc20RegulatedAuthoritativeRulebookVerificationResult> {
  try {
    const adminToken = String(process.env.TD_ADMIN_TOKEN || "").trim();
    if (!adminToken) {
      return {
        status: 503,
        body: {
          ok: false,
          reason: "kcc20_regulated_rulebook_preview_admin_token_missing",
          proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
          read_only: true,
          writes_to_disk: false,
          policy_mutation: false,
          transfer_enforcement_enabled: false,
          registry_deployment_enabled: false,
          signing: false,
          broadcasting: false,
          minting: false
        }
      };
    }

    const baseUrl = cnBaseUrl(repoRoot);
    if (!baseUrl) {
      return {
        status: 503,
        body: {
          ok: false,
          reason: "kcc20_regulated_rulebook_preview_cn_url_missing",
          proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
          read_only: true,
          writes_to_disk: false,
          policy_mutation: false,
          transfer_enforcement_enabled: false,
          registry_deployment_enabled: false,
          signing: false,
          broadcasting: false,
          minting: false
        }
      };
    }

    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), getAppConfig(repoRoot).cn_timeout_ms);

    let cnResponse: Response;
    let cnData: any;
    try {
      cnResponse = await fetch(`${baseUrl}/api/cn/kcc20-regulated/rulebook/current`, {
        method: "GET",
        headers: {
          Accept: "application/json",
          "x-td-admin-token": adminToken
        },
        signal: controller.signal
      });
      cnData = await cnResponse.json().catch(() => null);
    } catch (err) {
      const e = err instanceof Error ? err : new Error(String(err));
      return {
        status: e.name === "AbortError" ? 504 : 502,
        body: {
          ok: false,
          reason: e.name === "AbortError"
            ? "kcc20_regulated_rulebook_preview_cn_timeout"
            : "kcc20_regulated_rulebook_preview_cn_fetch_failed",
          error: e.message,
          proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
          read_only: true,
          writes_to_disk: false,
          policy_mutation: false,
          transfer_enforcement_enabled: false,
          registry_deployment_enabled: false,
          signing: false,
          broadcasting: false,
          minting: false
        }
      };
    } finally {
      clearTimeout(timeout);
    }

    if (!cnResponse.ok || !cnData || typeof cnData !== "object" || cnData.ok !== true) {
      return {
        status: 502,
        body: {
          ok: false,
          reason: "kcc20_regulated_rulebook_preview_cn_response_invalid",
          cn_http_status: cnResponse.status,
          cn_reason: typeof cnData?.reason === "string" ? cnData.reason : null,
          proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
          read_only: true,
          writes_to_disk: false,
          policy_mutation: false,
          transfer_enforcement_enabled: false,
          registry_deployment_enabled: false,
          signing: false,
          broadcasting: false,
          minting: false
        }
      };
    }

    const rulebook = cnData.rulebook;
    if (!rulebook || typeof rulebook !== "object" || Array.isArray(rulebook)) {
      return {
        status: 502,
        body: {
          ok: false,
          reason: "kcc20_regulated_rulebook_preview_rulebook_missing",
          proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
          read_only: true,
          writes_to_disk: false,
          policy_mutation: false,
          transfer_enforcement_enabled: false,
          registry_deployment_enabled: false,
          signing: false,
          broadcasting: false,
          minting: false
        }
      };
    }

    const requiredListFields = [
      "regulated_asset_covenant_ids",
      "recipient_allowlist",
      "recipient_blacklist",
      "frozen_holders",
      "frozen_outpoints",
      "lawful_order_actions"
    ];
    const requiredListsPresent = requiredListFields.every((field) => Array.isArray((rulebook as any)[field]));
    const schemaKind = String((rulebook as any).schema_kind || "").trim();
    const schemaVersion = Number((rulebook as any).schema_version);
    const network = String((rulebook as any).network || "").trim();
    const policyEpoch = (rulebook as any).policy_epoch;
    const policyEpochValid = typeof policyEpoch === "number"
      && Number.isInteger(policyEpoch)
      && policyEpoch >= 1
      && policyEpoch <= 0xffffffff;
    const sourcePolicySnapshotId = String((rulebook as any).source_policy_snapshot_id || "").trim().toLowerCase();
    const schemaValid = schemaKind === "kcc20_regulated_rulebook_v1"
      && schemaVersion === 1
      && network.length > 0
      && policyEpochValid
      && /^[0-9a-f]{64}$/.test(sourcePolicySnapshotId)
      && requiredListsPresent;

    const cwCanonicalRulebookJson = omaStableJson(rulebook);
    const cwRecomputedRulebookRoot = omaSha256Text(cwCanonicalRulebookJson);
    const cnCanonicalRulebookJson = String(cnData.canonical_rulebook_json || "");
    const cnCanonicalRulebookJsonSha256 = String(cnData.canonical_rulebook_json_sha256 || "").trim().toLowerCase();
    const cnRulebookRoot = String(cnData.rulebook_root || "").trim().toLowerCase();

    const canonicalJsonMatches = cnCanonicalRulebookJson === cwCanonicalRulebookJson;
    const canonicalJsonSha256Matches = cnCanonicalRulebookJsonSha256 === cwRecomputedRulebookRoot;
    const rulebookRootMatches = cnRulebookRoot === cwRecomputedRulebookRoot;
    const verificationPassed = schemaValid
      && canonicalJsonMatches
      && canonicalJsonSha256Matches
      && rulebookRootMatches;

    const counts = Object.fromEntries(requiredListFields.map((field) => [field, (rulebook as any)[field].length]));

    return {
      status: verificationPassed ? 200 : 409,
      body: {
        ok: verificationPassed,
        reason: verificationPassed ? null : "kcc20_regulated_rulebook_preview_verification_failed",
        proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
        schema_kind: schemaKind,
        schema_version: schemaVersion,
        policy_epoch: policyEpochValid ? policyEpoch : null,
        policy_epoch_valid: policyEpochValid,
        source_policy_snapshot_id: sourcePolicySnapshotId,
        network,
        counts,
        cn_rulebook_root: cnRulebookRoot,
        cw_recomputed_rulebook_root: cwRecomputedRulebookRoot,
        canonical_json_matches: canonicalJsonMatches,
        canonical_json_sha256_matches: canonicalJsonSha256Matches,
        rulebook_root_matches: rulebookRootMatches,
        schema_valid: schemaValid,
        verification_passed: verificationPassed,
        admin_token_exposed: false,
        source_policy_path_exposed: false,
        fee_policy_included: false,
        bcw_custody_fields_included: false,
        read_only: true,
        writes_to_disk: false,
        policy_mutation: false,
        transfer_enforcement_enabled: false,
        registry_deployment_enabled: false,
        signing: false,
        broadcasting: false,
        minting: false
      },
      ...(verificationPassed ? {
        verified: {
          rulebook: rulebook as Record<string, unknown>,
          canonical_rulebook_json: cwCanonicalRulebookJson,
          rulebook_root: cwRecomputedRulebookRoot,
          policy_epoch: policyEpoch as number,
          source_policy_snapshot_id: sourcePolicySnapshotId,
          network
        }
      } : {})
    };
  } catch (err) {
    return {
      status: 500,
      body: {
        ok: false,
        reason: "kcc20_regulated_rulebook_preview_failed",
        error: String(err),
        proof_kind: "kcc20_regulated_4a_rulebook_fetch_recompute_preview_v1",
        read_only: true,
        writes_to_disk: false,
        policy_mutation: false,
        transfer_enforcement_enabled: false,
        registry_deployment_enabled: false,
        signing: false,
        broadcasting: false,
        minting: false
      }
    };
  }
}

app.get("/api/covenants/issuer-token/kcc20-regulated/rulebook/preview", async (req, res) => {
  const userId = String((res.locals as any).td_user_id || "").trim();
  if (!userId) {
    return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
  }

  const verification = await omaVerifyKcc20RegulatedAuthoritativeRulebook(repoRoot);
  return res.status(verification.status).json(verification.body);
});

const OMA_KCC20_REGULATED_DEMO_POLICY_TEMPLATE_FILE = "kcc20-regulated-demo-policy.template.v1.json";
const OMA_KCC20_REGULATED_DEMO_POLICY_TEMPLATE_SHA256 = "85ae4a947611e893726247292aad9a143a7199600c9d36d95f16c945f29d3bc9";
const OMA_KCC20_REGULATED_DEMO_POLICY_FILE = "kcc20-regulated-demo-policy.v1.json";
const OMA_KCC20_REGULATED_DEMO_POLICY_SCHEMA_KIND = "kcc20_regulated_demo_policy_v1";
const OMA_KCC20_REGULATED_RULEBOOK_SCHEMA_KIND = "kcc20_regulated_rulebook_v1";
const OMA_KCC20_REGULATED_DEMO_POLICY_MAX_EPOCH = 4294967295;

interface OmaKcc20RegulatedDemoPolicyContentV1 {
  regulated_asset_covenant_ids: string[];
  recipient_allowlist: string[];
  recipient_blacklist: string[];
  frozen_holders: string[];
  frozen_outpoints: string[];
  lawful_order_actions: any[];
}

interface Kcc20RegulatedDemoPolicyV1 extends OmaKcc20RegulatedDemoPolicyContentV1 {
  schema_kind: "kcc20_regulated_demo_policy_v1";
  schema_version: 1;
  network: "testnet-10";
  policy_epoch: number;
  created_at: string;
  updated_at: string;
}

interface OmaKcc20RegulatedDemoRulebookV1 extends OmaKcc20RegulatedDemoPolicyContentV1 {
  schema_kind: "kcc20_regulated_rulebook_v1";
  schema_version: 1;
  network: "testnet-10";
  policy_epoch: number;
  source_policy_snapshot_id: string;
}

type OmaKcc20RegulatedDemoPolicyContextResult =
  | {
      ok: true;
      userId: string;
      active: any;
      networkId: "testnet-10";
    }
  | {
      ok: false;
      status: number;
      body: any;
    };

function omaKcc20RegulatedDemoPolicyPath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, OMA_KCC20_REGULATED_DEMO_POLICY_FILE);
}

function omaKcc20RegulatedDemoPolicyTemplatePath(repoRootPath: string): string {
  return path.join(repoRootPath, "static", "covenants", OMA_KCC20_REGULATED_DEMO_POLICY_TEMPLATE_FILE);
}

function omaKcc20RegulatedDemoPolicyRequireTn10Context(
  res: express.Response
): OmaKcc20RegulatedDemoPolicyContextResult {
  const userId = String((res.locals as any).td_user_id || "").trim();
  if (!userId) {
    return {
      ok: false,
      status: 401,
      body: { ok: false, reason: "auth_required", login: "/login.html" }
    };
  }

  const walletStore = readWalletStore(repoRoot, userId);
  const active = walletStore.active_id
    ? walletStore.items.find((wallet) => wallet.id === walletStore.active_id) ?? null
    : null;
  if (!active || String(active.state || "") !== "READY" || !active.address0 || !active.network) {
    return {
      ok: false,
      status: 409,
      body: {
        ok: false,
        reason: "kcc20_regulated_demo_policy_active_wallet_required",
        policy_source_mode: "Testnet-10 Local Demo Policy"
      }
    };
  }

  const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKeyFromWalletNetwork(active.network));
  if (networkId !== "testnet-10") {
    return {
      ok: false,
      status: 409,
      body: {
        ok: false,
        reason: "kcc20_regulated_demo_policy_testnet_10_only",
        networkId,
        policy_source_mode: "Testnet-10 Local Demo Policy"
      }
    };
  }

  return { ok: true, userId, active, networkId: "testnet-10" };
}

function omaKcc20RegulatedDemoPolicyAssertExactKeys(
  value: any,
  expectedKeys: string[],
  errorName: string
): void {
  if (!value || typeof value !== "object" || Array.isArray(value)) throw new Error(`${errorName}_object_required`);
  const actual = Object.keys(value).sort();
  const expected = [...expectedKeys].sort();
  if (actual.length !== expected.length || actual.some((key, index) => key !== expected[index])) {
    throw new Error(`${errorName}_keys_invalid`);
  }
}

function omaKcc20RegulatedDemoPolicyNormalizeStringList(
  value: any,
  fieldName: string,
  normalizeItem: (item: string) => string
): string[] {
  if (!Array.isArray(value)) throw new Error(`${fieldName}_array_required`);
  const normalized = value.map((item) => normalizeItem(String(item ?? "").trim())).filter(Boolean);
  return [...new Set(normalized)].sort((a, b) => a.localeCompare(b));
}

function omaKcc20RegulatedDemoPolicyNormalizeAssetId(value: string): string {
  const normalized = value.toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(normalized)) throw new Error("kcc20_regulated_demo_policy_asset_covenant_id_64_hex_required");
  return normalized;
}

function omaKcc20RegulatedDemoPolicyNormalizeTn10Address(value: string): string {
  const normalized = value.toLowerCase();
  if (!normalized.startsWith("kaspatest:")) throw new Error("kcc20_regulated_demo_policy_testnet_address_required");
  let parsed: InstanceType<typeof Address> | null = null;
  try {
    parsed = new Address(normalized);
  } catch {
    parsed = null;
  }
  if (!parsed || parsed.toString().toLowerCase() !== normalized) {
    throw new Error("kcc20_regulated_demo_policy_address_invalid_for_sdk");
  }
  return normalized;
}

function omaKcc20RegulatedDemoPolicyNormalizeOutpoint(value: string): string {
  const normalized = value.toLowerCase();
  const match = /^([0-9a-f]{64}):(\d+)$/.exec(normalized);
  if (!match) throw new Error("kcc20_regulated_demo_policy_outpoint_required");
  const index = Number(match[2]);
  if (!Number.isSafeInteger(index) || index < 0 || index > 4294967295) {
    throw new Error("kcc20_regulated_demo_policy_outpoint_index_invalid");
  }
  return `${match[1]}:${index}`;
}

function omaKcc20RegulatedDemoPolicyNormalizeContent(value: any): OmaKcc20RegulatedDemoPolicyContentV1 {
  const keys = [
    "regulated_asset_covenant_ids",
    "recipient_allowlist",
    "recipient_blacklist",
    "frozen_holders",
    "frozen_outpoints",
    "lawful_order_actions"
  ];
  omaKcc20RegulatedDemoPolicyAssertExactKeys(value, keys, "kcc20_regulated_demo_policy_content");

  if (!Array.isArray(value.lawful_order_actions)) {
    throw new Error("kcc20_regulated_demo_policy_lawful_order_actions_array_required");
  }
  if (value.lawful_order_actions.length !== 0) {
    throw new Error("kcc20_regulated_demo_policy_lawful_order_actions_not_supported_yet");
  }

  return {
    regulated_asset_covenant_ids: omaKcc20RegulatedDemoPolicyNormalizeStringList(
      value.regulated_asset_covenant_ids,
      "kcc20_regulated_demo_policy_regulated_asset_covenant_ids",
      omaKcc20RegulatedDemoPolicyNormalizeAssetId
    ),
    recipient_allowlist: omaKcc20RegulatedDemoPolicyNormalizeStringList(
      value.recipient_allowlist,
      "kcc20_regulated_demo_policy_recipient_allowlist",
      omaKcc20RegulatedDemoPolicyNormalizeTn10Address
    ),
    recipient_blacklist: omaKcc20RegulatedDemoPolicyNormalizeStringList(
      value.recipient_blacklist,
      "kcc20_regulated_demo_policy_recipient_blacklist",
      omaKcc20RegulatedDemoPolicyNormalizeTn10Address
    ),
    frozen_holders: omaKcc20RegulatedDemoPolicyNormalizeStringList(
      value.frozen_holders,
      "kcc20_regulated_demo_policy_frozen_holders",
      omaKcc20RegulatedDemoPolicyNormalizeTn10Address
    ),
    frozen_outpoints: omaKcc20RegulatedDemoPolicyNormalizeStringList(
      value.frozen_outpoints,
      "kcc20_regulated_demo_policy_frozen_outpoints",
      omaKcc20RegulatedDemoPolicyNormalizeOutpoint
    ),
    lawful_order_actions: []
  };
}

function omaKcc20RegulatedDemoPolicyReadTemplate(repoRootPath: string): OmaKcc20RegulatedDemoPolicyContentV1 {
  const templatePath = omaKcc20RegulatedDemoPolicyTemplatePath(repoRootPath);
  if (!fs.existsSync(templatePath)) throw new Error("kcc20_regulated_demo_policy_template_missing");
  const templateBytes = fs.readFileSync(templatePath);
  const templateHash = createHash("sha256").update(templateBytes).digest("hex");
  if (templateHash !== OMA_KCC20_REGULATED_DEMO_POLICY_TEMPLATE_SHA256) {
    throw new Error("kcc20_regulated_demo_policy_template_hash_mismatch");
  }

  const parsed = JSON.parse(templateBytes.toString("utf8"));
  omaKcc20RegulatedDemoPolicyAssertExactKeys(parsed, [
    "schema_kind",
    "schema_version",
    "network",
    "policy_epoch",
    "regulated_asset_covenant_ids",
    "recipient_allowlist",
    "recipient_blacklist",
    "frozen_holders",
    "frozen_outpoints",
    "lawful_order_actions"
  ], "kcc20_regulated_demo_policy_template");
  if (
    parsed.schema_kind !== OMA_KCC20_REGULATED_DEMO_POLICY_SCHEMA_KIND
    || Number(parsed.schema_version) !== 1
    || parsed.network !== "testnet-10"
    || Number(parsed.policy_epoch) !== 1
  ) {
    throw new Error("kcc20_regulated_demo_policy_template_header_invalid");
  }
  return omaKcc20RegulatedDemoPolicyNormalizeContent({
    regulated_asset_covenant_ids: parsed.regulated_asset_covenant_ids,
    recipient_allowlist: parsed.recipient_allowlist,
    recipient_blacklist: parsed.recipient_blacklist,
    frozen_holders: parsed.frozen_holders,
    frozen_outpoints: parsed.frozen_outpoints,
    lawful_order_actions: parsed.lawful_order_actions
  });
}

function omaKcc20RegulatedDemoPolicyRead(
  repoRootPath: string,
  userId: string
): Kcc20RegulatedDemoPolicyV1 | null {
  const policyPath = omaKcc20RegulatedDemoPolicyPath(repoRootPath, userId);
  if (!fs.existsSync(policyPath)) return null;
  const parsed = JSON.parse(fs.readFileSync(policyPath, "utf8"));
  omaKcc20RegulatedDemoPolicyAssertExactKeys(parsed, [
    "schema_kind",
    "schema_version",
    "network",
    "policy_epoch",
    "regulated_asset_covenant_ids",
    "recipient_allowlist",
    "recipient_blacklist",
    "frozen_holders",
    "frozen_outpoints",
    "lawful_order_actions",
    "created_at",
    "updated_at"
  ], "kcc20_regulated_demo_policy_store");

  if (
    parsed.schema_kind !== OMA_KCC20_REGULATED_DEMO_POLICY_SCHEMA_KIND
    || Number(parsed.schema_version) !== 1
    || parsed.network !== "testnet-10"
  ) {
    throw new Error("kcc20_regulated_demo_policy_store_header_invalid");
  }

  const policyEpoch = omaReadUintNumber(
    parsed.policy_epoch,
    "kcc20_regulated_demo_policy_epoch",
    1,
    OMA_KCC20_REGULATED_DEMO_POLICY_MAX_EPOCH
  );
  const createdAt = String(parsed.created_at || "").trim();
  const updatedAt = String(parsed.updated_at || "").trim();
  if (!createdAt || !Number.isFinite(Date.parse(createdAt))) throw new Error("kcc20_regulated_demo_policy_created_at_invalid");
  if (!updatedAt || !Number.isFinite(Date.parse(updatedAt))) throw new Error("kcc20_regulated_demo_policy_updated_at_invalid");

  const storedContent = {
    regulated_asset_covenant_ids: parsed.regulated_asset_covenant_ids,
    recipient_allowlist: parsed.recipient_allowlist,
    recipient_blacklist: parsed.recipient_blacklist,
    frozen_holders: parsed.frozen_holders,
    frozen_outpoints: parsed.frozen_outpoints,
    lawful_order_actions: parsed.lawful_order_actions
  };
  const content = omaKcc20RegulatedDemoPolicyNormalizeContent(storedContent);
  if (omaStableJson(storedContent) !== omaStableJson(content)) {
    throw new Error("kcc20_regulated_demo_policy_store_not_normalized");
  }

  return {
    schema_kind: OMA_KCC20_REGULATED_DEMO_POLICY_SCHEMA_KIND,
    schema_version: 1,
    network: "testnet-10",
    policy_epoch: policyEpoch,
    ...content,
    created_at: createdAt,
    updated_at: updatedAt
  };
}

function omaKcc20RegulatedDemoPolicyWrite(
  repoRootPath: string,
  userId: string,
  policy: Kcc20RegulatedDemoPolicyV1
): void {
  const policyPath = omaKcc20RegulatedDemoPolicyPath(repoRootPath, userId);
  fs.mkdirSync(path.dirname(policyPath), { recursive: true });
  const tempPath = `${policyPath}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tempPath, JSON.stringify(policy, null, 2) + "\n", { mode: 0o600 });
  fs.renameSync(tempPath, policyPath);
}

function omaKcc20RegulatedDemoPolicyDerive(policy: Kcc20RegulatedDemoPolicyV1): {
  source_policy_snapshot_id: string;
  rulebook: OmaKcc20RegulatedDemoRulebookV1;
  canonical_rulebook_json: string;
  rulebook_root: string;
} {
  const sourceContent: OmaKcc20RegulatedDemoPolicyContentV1 = {
    regulated_asset_covenant_ids: policy.regulated_asset_covenant_ids,
    recipient_allowlist: policy.recipient_allowlist,
    recipient_blacklist: policy.recipient_blacklist,
    frozen_holders: policy.frozen_holders,
    frozen_outpoints: policy.frozen_outpoints,
    lawful_order_actions: policy.lawful_order_actions
  };
  const sourcePolicySnapshotId = omaSha256Text(omaStableJson(sourceContent));
  const rulebook: OmaKcc20RegulatedDemoRulebookV1 = {
    schema_kind: OMA_KCC20_REGULATED_RULEBOOK_SCHEMA_KIND,
    schema_version: 1,
    network: "testnet-10",
    policy_epoch: policy.policy_epoch,
    source_policy_snapshot_id: sourcePolicySnapshotId,
    ...sourceContent
  };
  const canonicalRulebookJson = omaStableJson(rulebook);
  return {
    source_policy_snapshot_id: sourcePolicySnapshotId,
    rulebook,
    canonical_rulebook_json: canonicalRulebookJson,
    rulebook_root: omaSha256Text(canonicalRulebookJson)
  };
}

function omaKcc20RegulatedDemoHolderTransferPolicyDecision(params: {
  repoRootPath: string;
  userId: string;
  assetCovenantId: string;
  senderAddress: string;
  recipientAddress: string;
  sourceHolderOutpoints: string[];
  regulatedProfile: OmaL1TokenRegulatedCompactState;
}): OmaL1HolderTransferDemoPolicyDecision {
  const assetCovenantId = String(params.assetCovenantId || "").trim().toLowerCase();
  const senderAddress = String(params.senderAddress || "").trim().toLowerCase();
  const recipientAddress = String(params.recipientAddress || "").trim().toLowerCase();
  const sourceHolderOutpoints = [...new Set(params.sourceHolderOutpoints
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean))].sort();
  const controlFlags = omaDecodeKcc20RegulatedControlFlags(params.regulatedProfile.fc);
  const policy = omaKcc20RegulatedDemoPolicyRead(params.repoRootPath, params.userId);
  if (!policy) {
    return {
      decision_kind: "kcc20_regulated_demo_holder_transfer_policy_decision_v1",
      policy_source_mode: "Testnet-10 Local Demo Policy",
      demo_enforcement_only: true,
      production_eligible: false,
      allowed: false,
      rejection_reasons: ["kcc20_regulated_demo_policy_not_initialized"],
      policy_epoch: null,
      source_policy_snapshot_id: null,
      rulebook_root: null,
      asset_covenant_id: assetCovenantId,
      asset_governed: false,
      recipient_address: recipientAddress,
      recipient_allowlisted: false,
      recipient_blacklisted: false,
      sender_frozen: false,
      recipient_frozen: false,
      source_holder_outpoints: sourceHolderOutpoints,
      frozen_source_holder_outpoints: [],
      control_flags: controlFlags,
      stored_policy_epoch: params.regulatedProfile.pe,
      policy_epoch_compatible: false,
      successor_policy_epoch: null,
      registry_record_matches_policy: false
    };
  }

  const derived = omaKcc20RegulatedDemoPolicyDerive(policy);
  const assetGoverned = policy.regulated_asset_covenant_ids.includes(assetCovenantId);
  const recipientAllowlisted = policy.recipient_allowlist.includes(recipientAddress);
  const recipientBlacklisted = policy.recipient_blacklist.includes(recipientAddress);
  const senderFrozen = policy.frozen_holders.includes(senderAddress);
  const recipientFrozen = policy.frozen_holders.includes(recipientAddress);
  const frozenSourceHolderOutpoints = sourceHolderOutpoints.filter((outpoint) => policy.frozen_outpoints.includes(outpoint));
  const policyEpochCompatible = params.regulatedProfile.pe <= policy.policy_epoch;
  const registryRecord = omaKcc20PolicyRegistryRecord(params.repoRootPath, params.userId, params.regulatedProfile.pr);
  const registryRecordMatchesPolicy = !!registryRecord
    && registryRecord.record_status === "live_verified"
    && registryRecord.networkId === "testnet-10"
    && registryRecord.state.e === policy.policy_epoch
    && registryRecord.state.r === derived.rulebook_root;
  const rejectionReasons: string[] = [];

  if (controlFlags.rulebook_transfer_required && !assetGoverned) rejectionReasons.push("kcc20_regulated_demo_transfer_asset_not_governed");
  if (!policyEpochCompatible) rejectionReasons.push("kcc20_regulated_demo_transfer_policy_epoch_ahead_of_saved_policy");
  if (!registryRecordMatchesPolicy) rejectionReasons.push("kcc20_regulated_demo_transfer_registry_not_current");
  if (controlFlags.recipient_blacklist_enabled && recipientBlacklisted) rejectionReasons.push("kcc20_regulated_demo_transfer_recipient_blacklisted");
  if (controlFlags.recipient_allowlist_enabled && !recipientAllowlisted) rejectionReasons.push("kcc20_regulated_demo_transfer_recipient_not_allowlisted");
  if (controlFlags.freeze_supported && senderFrozen) rejectionReasons.push("kcc20_regulated_demo_transfer_sender_frozen");
  if (controlFlags.freeze_supported && recipientFrozen) rejectionReasons.push("kcc20_regulated_demo_transfer_recipient_frozen");
  if (controlFlags.freeze_supported && frozenSourceHolderOutpoints.length > 0) rejectionReasons.push("kcc20_regulated_demo_transfer_source_outpoint_frozen");

  return {
    decision_kind: "kcc20_regulated_demo_holder_transfer_policy_decision_v1",
    policy_source_mode: "Testnet-10 Local Demo Policy",
    demo_enforcement_only: true,
    production_eligible: false,
    allowed: rejectionReasons.length === 0,
    rejection_reasons: rejectionReasons,
    policy_epoch: policy.policy_epoch,
    source_policy_snapshot_id: derived.source_policy_snapshot_id,
    rulebook_root: derived.rulebook_root,
    asset_covenant_id: assetCovenantId,
    asset_governed: assetGoverned,
    recipient_address: recipientAddress,
    recipient_allowlisted: recipientAllowlisted,
    recipient_blacklisted: recipientBlacklisted,
    sender_frozen: senderFrozen,
    recipient_frozen: recipientFrozen,
    source_holder_outpoints: sourceHolderOutpoints,
    frozen_source_holder_outpoints: frozenSourceHolderOutpoints,
    control_flags: controlFlags,
    stored_policy_epoch: params.regulatedProfile.pe,
    policy_epoch_compatible: policyEpochCompatible,
    successor_policy_epoch: policyEpochCompatible ? policy.policy_epoch : null,
    registry_record_matches_policy: registryRecordMatchesPolicy
  };
}

function omaKcc20RegulatedDemoPolicyPublic(
  policy: Kcc20RegulatedDemoPolicyV1,
  extra: Record<string, any> = {}
): any {
  const derived = omaKcc20RegulatedDemoPolicyDerive(policy);
  return {
    ok: true,
    policy_source_mode: "Testnet-10 Local Demo Policy",
    policy,
    source_policy_snapshot_id: derived.source_policy_snapshot_id,
    rulebook: derived.rulebook,
    canonical_rulebook_json_sha256: derived.rulebook_root,
    rulebook_root: derived.rulebook_root,
    local_demo_policy: true,
    production_eligible: false,
    mainnet_eligible: false,
    token_depot_cn_policy_mutated: false,
    token_depot_registry_mutated: false,
    token_01_mutated: false,
    ...extra
  };
}

function omaKcc20RegulatedDemoPolicyRequestContent(body: any): OmaKcc20RegulatedDemoPolicyContentV1 {
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    throw new Error("kcc20_regulated_demo_policy_update_body_object_required");
  }
  if (Object.prototype.hasOwnProperty.call(body, "policy_epoch")) {
    throw new Error("kcc20_regulated_demo_policy_caller_epoch_not_allowed");
  }
  if (!body.policy || typeof body.policy !== "object" || Array.isArray(body.policy)) {
    throw new Error("kcc20_regulated_demo_policy_update_policy_object_required");
  }
  if (Object.prototype.hasOwnProperty.call(body.policy, "policy_epoch")) {
    throw new Error("kcc20_regulated_demo_policy_caller_epoch_not_allowed");
  }
  return omaKcc20RegulatedDemoPolicyNormalizeContent(body.policy);
}

function omaKcc20RegulatedDemoPolicyClientError(reason: string): boolean {
  return reason.startsWith("kcc20_regulated_demo_policy_")
    && !reason.includes("template_")
    && !reason.includes("store_");
}

function omaVerifyKcc20RegulatedDemoPolicyRulebook(
  repoRootPath: string,
  userId: string
): OmaKcc20RegulatedAuthoritativeRulebookVerificationResult {
  try {
    const policy = omaKcc20RegulatedDemoPolicyRead(repoRootPath, userId);
    if (!policy) {
      return {
        status: 409,
        body: {
          ok: false,
          reason: "kcc20_regulated_demo_policy_not_initialized",
          policy_source_mode: "Testnet-10 Local Demo Policy",
          local_demo_policy: true,
          registry_deployment_enabled: false,
          signing_enabled: false,
          broadcasting_enabled: false
        }
      };
    }

    const derived = omaKcc20RegulatedDemoPolicyDerive(policy);
    return {
      status: 200,
      body: {
        ok: true,
        proof_kind: "kcc20_regulated_demo_policy_registry_source_v1",
        policy_source_mode: "Testnet-10 Local Demo Policy",
        local_demo_policy: true,
        production_eligible: false,
        network: "testnet-10",
        policy_epoch: policy.policy_epoch,
        source_policy_snapshot_id: derived.source_policy_snapshot_id,
        rulebook_root: derived.rulebook_root,
        canonical_rulebook_json_sha256: derived.rulebook_root,
        registry_deployment_enabled: true,
        signing_enabled: false,
        broadcasting_enabled: false
      },
      verified: {
        rulebook: derived.rulebook as unknown as Record<string, unknown>,
        canonical_rulebook_json: derived.canonical_rulebook_json,
        rulebook_root: derived.rulebook_root,
        policy_epoch: policy.policy_epoch,
        source_policy_snapshot_id: derived.source_policy_snapshot_id,
        network: "testnet-10"
      }
    };
  } catch (err) {
    const reason = err instanceof Error ? err.message : String(err);
    return {
      status: omaKcc20RegulatedDemoPolicyClientError(reason) ? 400 : 500,
      body: {
        ok: false,
        reason,
        policy_source_mode: "Testnet-10 Local Demo Policy",
        local_demo_policy: true,
        registry_deployment_enabled: false,
        signing_enabled: false,
        broadcasting_enabled: false
      }
    };
  }
}

