app.post("/api/covenants/issuer-token/kcc20-regulated/demo-policy/create", (req, res) => {
  const context = omaKcc20RegulatedDemoPolicyRequireTn10Context(res);
  if (!context.ok) return res.status(context.status).json(context.body);
  let auditMutationCompleted = false;
  omaInstallKcc20RegulatedAuditRejectedResponseHook(res, {
    repoRootPath: repoRoot,
    userId: context.userId,
    actionKind: () => "policy_create",
    actor: () => omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
    policy: () => omaKcc20RegulatedAuditCurrentPolicySnapshot(repoRoot, context.userId),
    sourceReferences: () => [{
      source_kind: "demo_policy",
      relative_path: omaKcc20RegulatedAuditRelativePath(
        repoRoot,
        omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
      )
    }],
    shouldCapture: () => !auditMutationCompleted
  });
  try {
    if (omaKcc20RegulatedDemoPolicyRead(repoRoot, context.userId)) {
      return res.status(409).json({
        ok: false,
        reason: "kcc20_regulated_demo_policy_already_initialized"
      });
    }
    const body = (req.body || {}) as any;
    const includeActiveWallet = body.include_active_wallet_in_allowlist === true;
    const content = omaKcc20RegulatedDemoPolicyReadTemplate(repoRoot);
    if (includeActiveWallet) {
      content.recipient_allowlist = omaKcc20RegulatedDemoPolicyNormalizeStringList(
        [...content.recipient_allowlist, context.active.address0],
        "kcc20_regulated_demo_policy_recipient_allowlist",
        omaKcc20RegulatedDemoPolicyNormalizeTn10Address
      );
    }
    const now = new Date().toISOString();
    const policy: Kcc20RegulatedDemoPolicyV1 = {
      schema_kind: OMA_KCC20_REGULATED_DEMO_POLICY_SCHEMA_KIND,
      schema_version: 1,
      network: "testnet-10",
      policy_epoch: 1,
      ...content,
      created_at: now,
      updated_at: now
    };
    const auditDerived = omaKcc20RegulatedDemoPolicyDerive(policy);
    const auditCorrelationId = `policy:${policy.policy_epoch}:${auditDerived.rulebook_root}`;
    const auditPolicy = {
      ...omaKcc20RegulatedAuditPolicySnapshot(policy),
      previous_policy_epoch: null,
      previous_rulebook_root: null,
      diff: omaKcc20RegulatedAuditPolicyDiff(null, policy),
      registry_publication_required: true
    };
    appendOmaKcc20RegulatedAuditEvent(repoRoot, context.userId, {
      actionKind: "policy_create",
      stage: "planned",
      outcome: "informational",
      occurredAt: policy.updated_at,
      dedupeKey: `policy_create:planned:${policy.policy_epoch}:${auditDerived.rulebook_root}`,
      correlationId: auditCorrelationId,
      actor: omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
      policy: auditPolicy,
      sourceReferences: [{
        source_kind: "demo_policy",
        relative_path: omaKcc20RegulatedAuditRelativePath(
          repoRoot,
          omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
        )
      }]
    });
    omaKcc20RegulatedDemoPolicyWrite(repoRoot, context.userId, policy);
    auditMutationCompleted = true;
    appendOmaKcc20RegulatedAuditEvent(repoRoot, context.userId, {
      actionKind: "policy_create",
      stage: "tracking_updated",
      outcome: "success",
      occurredAt: policy.updated_at,
      dedupeKey: `policy_create:tracking_updated:${policy.policy_epoch}:${auditDerived.rulebook_root}`,
      correlationId: auditCorrelationId,
      actor: omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
      policy: auditPolicy,
      decision: { policy_saved: true, policy_epoch_incremented: false },
      sourceReferences: [{
        source_kind: "demo_policy",
        relative_path: omaKcc20RegulatedAuditRelativePath(
          repoRoot,
          omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
        )
      }]
    });
    return res.status(201).json(omaKcc20RegulatedDemoPolicyPublic(policy, {
      operation: "create",
      writes_to_disk: true,
      active_wallet_seeded_into_allowlist: includeActiveWallet,
      registry_publication_required: true
    }));
  } catch (err) {
    const reason = String(err instanceof Error ? err.message : err);
    return res.status(omaKcc20RegulatedDemoPolicyClientError(reason) ? 400 : 500).json({
      ok: false,
      reason: omaKcc20RegulatedDemoPolicyClientError(reason)
        ? reason
        : "kcc20_regulated_demo_policy_create_failed",
      ...(omaKcc20RegulatedDemoPolicyClientError(reason) ? {} : { error: reason })
    });
  }
});

app.post("/api/covenants/issuer-token/kcc20-regulated/demo-policy/update", (req, res) => {
  const context = omaKcc20RegulatedDemoPolicyRequireTn10Context(res);
  if (!context.ok) return res.status(context.status).json(context.body);
  let auditMutationCompleted = false;
  omaInstallKcc20RegulatedAuditRejectedResponseHook(res, {
    repoRootPath: repoRoot,
    userId: context.userId,
    actionKind: () => "policy_update",
    actor: () => omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
    policy: () => omaKcc20RegulatedAuditCurrentPolicySnapshot(repoRoot, context.userId),
    sourceReferences: () => [{
      source_kind: "demo_policy",
      relative_path: omaKcc20RegulatedAuditRelativePath(
        repoRoot,
        omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
      )
    }],
    shouldCapture: () => !auditMutationCompleted
  });
  try {
    const current = omaKcc20RegulatedDemoPolicyRead(repoRoot, context.userId);
    if (!current) {
      return res.status(404).json({
        ok: false,
        reason: "kcc20_regulated_demo_policy_not_initialized",
        initialization_required: true
      });
    }
    const nextContent = omaKcc20RegulatedDemoPolicyRequestContent(req.body || {});
    const currentContent: OmaKcc20RegulatedDemoPolicyContentV1 = {
      regulated_asset_covenant_ids: current.regulated_asset_covenant_ids,
      recipient_allowlist: current.recipient_allowlist,
      recipient_blacklist: current.recipient_blacklist,
      frozen_holders: current.frozen_holders,
      frozen_outpoints: current.frozen_outpoints,
      lawful_order_actions: current.lawful_order_actions
    };
    if (omaStableJson(currentContent) === omaStableJson(nextContent)) {
      return res.json(omaKcc20RegulatedDemoPolicyPublic(current, {
        operation: "update",
        writes_to_disk: false,
        no_op: true,
        policy_epoch_incremented: false,
        registry_publication_required: false
      }));
    }
    if (current.policy_epoch >= OMA_KCC20_REGULATED_DEMO_POLICY_MAX_EPOCH) {
      return res.status(409).json({
        ok: false,
        reason: "kcc20_regulated_demo_policy_epoch_overflow"
      });
    }
    const nextPolicy: Kcc20RegulatedDemoPolicyV1 = {
      ...current,
      ...nextContent,
      policy_epoch: current.policy_epoch + 1,
      updated_at: new Date().toISOString()
    };
    const previousDerived = omaKcc20RegulatedDemoPolicyDerive(current);
    const nextDerived = omaKcc20RegulatedDemoPolicyDerive(nextPolicy);
    const auditCorrelationId = `policy:${nextPolicy.policy_epoch}:${nextDerived.rulebook_root}`;
    const auditPolicy = {
      ...omaKcc20RegulatedAuditPolicySnapshot(nextPolicy),
      previous_policy_epoch: current.policy_epoch,
      previous_rulebook_root: previousDerived.rulebook_root,
      diff: omaKcc20RegulatedAuditPolicyDiff(current, nextPolicy),
      registry_publication_required: true
    };
    appendOmaKcc20RegulatedAuditEvent(repoRoot, context.userId, {
      actionKind: "policy_update",
      stage: "planned",
      outcome: "informational",
      occurredAt: nextPolicy.updated_at,
      dedupeKey: `policy_update:planned:${nextPolicy.policy_epoch}:${nextDerived.rulebook_root}`,
      correlationId: auditCorrelationId,
      actor: omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
      policy: auditPolicy,
      sourceReferences: [{
        source_kind: "demo_policy",
        relative_path: omaKcc20RegulatedAuditRelativePath(
          repoRoot,
          omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
        )
      }]
    });
    omaKcc20RegulatedDemoPolicyWrite(repoRoot, context.userId, nextPolicy);
    auditMutationCompleted = true;
    appendOmaKcc20RegulatedAuditEvent(repoRoot, context.userId, {
      actionKind: "policy_update",
      stage: "tracking_updated",
      outcome: "success",
      occurredAt: nextPolicy.updated_at,
      dedupeKey: `policy_update:tracking_updated:${nextPolicy.policy_epoch}:${nextDerived.rulebook_root}`,
      correlationId: auditCorrelationId,
      actor: omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
      policy: auditPolicy,
      decision: { policy_saved: true, policy_epoch_incremented: true },
      sourceReferences: [{
        source_kind: "demo_policy",
        relative_path: omaKcc20RegulatedAuditRelativePath(
          repoRoot,
          omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
        )
      }]
    });
    omaAppendKcc20RegulatedAuditPolicyControlEvents({
      repoRootPath: repoRoot,
      userId: context.userId,
      previousPolicy: current,
      nextPolicy,
      actor: omaKcc20RegulatedAuditActorFromWallet(context.active, context.userId, "demo_policy_owner"),
      sourceReferences: [{
        source_kind: "demo_policy",
        relative_path: omaKcc20RegulatedAuditRelativePath(
          repoRoot,
          omaKcc20RegulatedDemoPolicyPath(repoRoot, context.userId)
        )
      }]
    });
    return res.json(omaKcc20RegulatedDemoPolicyPublic(nextPolicy, {
      operation: "update",
      writes_to_disk: true,
      no_op: false,
      previous_policy_epoch: current.policy_epoch,
      policy_epoch_incremented: true,
      registry_publication_required: true
    }));
  } catch (err) {
    const reason = String(err instanceof Error ? err.message : err);
    return res.status(omaKcc20RegulatedDemoPolicyClientError(reason) ? 400 : 500).json({
      ok: false,
      reason: omaKcc20RegulatedDemoPolicyClientError(reason)
        ? reason
        : "kcc20_regulated_demo_policy_update_failed",
      ...(omaKcc20RegulatedDemoPolicyClientError(reason) ? {} : { error: reason })
    });
  }
});

