type OmaKcc20PolicyRegistryFundingCandidate = {
  reference: any;
  row: CovenantControlsBuildSourceRow;
  outpoint: string;
  amount_sompi: bigint;
  previous_outpoint: any;
};

function omaKcc20NativeFundingCandidateSets(
  entries: any[],
  targetSompi: bigint,
  maxInputs = 8
): OmaKcc20PolicyRegistryFundingCandidate[][] {
  const rows: OmaKcc20PolicyRegistryFundingCandidate[] = (Array.isArray(entries) ? entries : [])
    .map((reference, index) => {
      const row = covenantBuildSourceRow(reference, index);
      const outpoint = String(covenantInputOutpointKey(row) || "");
      const amountSompi = row.amount_sompi && /^\d+$/.test(row.amount_sompi) ? BigInt(row.amount_sompi) : 0n;
      const previousOutpoint = reference?.outpoint && typeof reference.outpoint.toJSON === "function"
        ? reference.outpoint.toJSON()
        : reference?.outpoint;
      return { reference, row, outpoint, amount_sompi: amountSompi, previous_outpoint: previousOutpoint };
    })
    .filter((candidate) => (
      !candidate.row.covenant_present
      && !candidate.row.is_coinbase
      && candidate.amount_sompi > 0n
      && !!candidate.outpoint
      && !!candidate.previous_outpoint
    ))
    .sort((a, b) => {
      if (a.amount_sompi !== b.amount_sompi) return a.amount_sompi < b.amount_sompi ? -1 : 1;
      return a.outpoint < b.outpoint ? -1 : a.outpoint > b.outpoint ? 1 : 0;
    });

  if (!rows.length || targetSompi <= 0n) return [];

  const candidateSets: OmaKcc20PolicyRegistryFundingCandidate[][] = [];
  const seen = new Set<string>();
  const pushCandidate = (items: OmaKcc20PolicyRegistryFundingCandidate[]) => {
    if (!items.length || items.length > maxInputs) return;
    const normalized = items.slice().sort((a, b) => a.outpoint < b.outpoint ? -1 : a.outpoint > b.outpoint ? 1 : 0);
    const totalSompi = normalized.reduce((sum, item) => sum + item.amount_sompi, 0n);
    if (totalSompi < targetSompi) return;
    const key = normalized.map((item) => item.outpoint).join("|");
    if (!key || seen.has(key)) return;
    seen.add(key);
    candidateSets.push(normalized);
  };

  for (const row of rows) {
    if (row.amount_sompi >= targetSompi) pushCandidate([row]);
  }

  const belowTarget = rows.filter((row) => row.amount_sompi < targetSompi);
  const descendingAccum: OmaKcc20PolicyRegistryFundingCandidate[] = [];
  let descendingTotal = 0n;
  for (const row of belowTarget.slice().reverse()) {
    if (descendingAccum.length >= maxInputs) break;
    descendingAccum.push(row);
    descendingTotal += row.amount_sompi;
    if (descendingTotal >= targetSompi) pushCandidate(descendingAccum);
  }

  const ascendingAccum: OmaKcc20PolicyRegistryFundingCandidate[] = [];
  let ascendingTotal = 0n;
  for (const row of belowTarget) {
    if (ascendingAccum.length >= maxInputs) break;
    ascendingAccum.push(row);
    ascendingTotal += row.amount_sompi;
    if (ascendingTotal >= targetSompi) pushCandidate(ascendingAccum);
  }

  const boostedAccum: OmaKcc20PolicyRegistryFundingCandidate[] = [];
  let boostedTotal = 0n;
  for (const row of rows) {
    if (boostedAccum.length >= maxInputs) break;
    boostedAccum.push(row);
    boostedTotal += row.amount_sompi;
    if (boostedTotal >= targetSompi) pushCandidate(boostedAccum);
  }

  const comboWindow = rows.slice(0, Math.min(rows.length, 24));
  for (let firstIndex = 0; firstIndex < comboWindow.length; firstIndex += 1) {
    for (let secondIndex = firstIndex + 1; secondIndex < comboWindow.length; secondIndex += 1) {
      pushCandidate([comboWindow[firstIndex], comboWindow[secondIndex]]);
    }
  }

  if (!candidateSets.length) pushCandidate(rows.slice(0, maxInputs));

  return candidateSets.sort((a, b) => {
    const aTotal = a.reduce((sum, item) => sum + item.amount_sompi, 0n);
    const bTotal = b.reduce((sum, item) => sum + item.amount_sompi, 0n);
    if (a.length !== b.length) return a.length - b.length;
    if (aTotal !== bTotal) return aTotal < bTotal ? -1 : 1;
    const aKey = a.map((item) => item.outpoint).join("|");
    const bKey = b.map((item) => item.outpoint).join("|");
    return aKey < bKey ? -1 : aKey > bKey ? 1 : 0;
  });
}

const omaKcc20PolicyRegistryDeployCache = new Map<string, OmaKcc20PolicyRegistryDeployCacheEntry>();

function omaKcc20PolicyRegistryStorePath(repoRootPath: string, userId: string): string {
  return path.join(repoRootPath, "data", "users", userId, OMA_KCC20_POLICY_REGISTRY_STORE_FILE);
}

function readOmaKcc20PolicyRegistryStore(repoRootPath: string, userId: string): OmaKcc20PolicyRegistryStoreV1 {
  const filePath = omaKcc20PolicyRegistryStorePath(repoRootPath, userId);
  if (!fs.existsSync(filePath)) {
    return { schema_kind: "oma_l1_policy_registry_store_v1", schema_version: 1, records: [] };
  }
  const parsed = JSON.parse(fs.readFileSync(filePath, "utf8"));
  if (
    !parsed || parsed.schema_kind !== "oma_l1_policy_registry_store_v1"
    || Number(parsed.schema_version) !== 1 || !Array.isArray(parsed.records)
  ) throw new Error("oma_l1_policy_registry_store_invalid");
  return parsed as OmaKcc20PolicyRegistryStoreV1;
}

function writeOmaKcc20PolicyRegistryStore(repoRootPath: string, userId: string, store: OmaKcc20PolicyRegistryStoreV1): void {
  const filePath = omaKcc20PolicyRegistryStorePath(repoRootPath, userId);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const tempPath = `${filePath}.tmp-${process.pid}-${Date.now()}`;
  fs.writeFileSync(tempPath, JSON.stringify(store, null, 2) + "\n", { mode: 0o600 });
  fs.renameSync(tempPath, filePath);
}

function upsertOmaKcc20PolicyRegistryRecord(repoRootPath: string, userId: string, record: OmaKcc20PolicyRegistryRecordV1): void {
  const store = readOmaKcc20PolicyRegistryStore(repoRootPath, userId);
  const id = String(record.registry_covenant_id || "").trim().toLowerCase();
  const records = store.records.filter((row) => String(row?.registry_covenant_id || "").trim().toLowerCase() !== id);
  records.push(record);
  records.sort((a, b) => a.registry_covenant_id.localeCompare(b.registry_covenant_id));
  writeOmaKcc20PolicyRegistryStore(repoRootPath, userId, { ...store, records });
}

function omaKcc20PolicyRegistryRecord(
  repoRootPath: string,
  userId: string,
  registryCovenantId: string
): OmaKcc20PolicyRegistryRecordV1 | null {
  const id = String(registryCovenantId || "").trim().toLowerCase();
  return readOmaKcc20PolicyRegistryStore(repoRootPath, userId).records.find(
    (row) => String(row?.registry_covenant_id || "").trim().toLowerCase() === id
  ) || null;
}


