function omaKcc20RegulatedAuditIso(value: unknown, fieldName: string): string {
  const text = String(value ?? "").trim();
  if (!text || Number.isNaN(Date.parse(text))) throw new Error(`${fieldName}_iso_timestamp_required`);
  return new Date(text).toISOString();
}

function omaKcc20RegulatedAuditOptionalHex64(value: unknown, fieldName: string): string | null {
  const text = String(value ?? "").trim().toLowerCase();
  if (!text) return null;
  if (!/^[0-9a-f]{64}$/.test(text)) throw new Error(`${fieldName}_64_hex_required`);
  return text;
}

function omaKcc20RegulatedAuditAssertNoForbiddenKeys(value: unknown, pathParts: string[] = []): void {
  if (Array.isArray(value)) {
    value.forEach((item, index) => omaKcc20RegulatedAuditAssertNoForbiddenKeys(item, [...pathParts, String(index)]));
    return;
  }
  if (!value || typeof value !== "object") return;
  for (const [key, nested] of Object.entries(value as Record<string, unknown>)) {
    const normalizedKey = key.trim().toLowerCase();
    if (OMA_KCC20_REGULATED_AUDIT_FORBIDDEN_EXACT_KEYS.has(normalizedKey)) {
      throw new Error(`kcc20_regulated_audit_forbidden_field:${[...pathParts, key].join(".")}`);
    }
    omaKcc20RegulatedAuditAssertNoForbiddenKeys(nested, [...pathParts, key]);
  }
}

function omaKcc20RegulatedAuditEventHash(event: OmaKcc20RegulatedAuditEventV1): string {
  const { event_hash: _eventHash, ...hashable } = event;
  return omaSha256Text(omaStableJson(hashable));
}

function readOmaKcc20RegulatedAuditStore(repoRootPath: string, userId: string): {
  present: boolean;
  chain_verified: boolean | null;
  head_event_hash: string | null;
  store: OmaKcc20RegulatedAuditStoreV1;
} {
  const filePath = omaKcc20RegulatedAuditPath(repoRootPath, userId);
  if (!fs.existsSync(filePath)) {
    return {
      present: false,
      chain_verified: null,
      head_event_hash: null,
      store: {
        schema_kind: OMA_KCC20_REGULATED_AUDIT_STORE_SCHEMA_KIND,
        schema_version: 1,
        records: []
      }
    };
  }

  const parsed = JSON.parse(fs.readFileSync(filePath, "utf8"));
  omaKcc20RegulatedDemoPolicyAssertExactKeys(
    parsed,
    ["schema_kind", "schema_version", "records"],
    "kcc20_regulated_audit_store"
  );
  if (
    parsed.schema_kind !== OMA_KCC20_REGULATED_AUDIT_STORE_SCHEMA_KIND
    || Number(parsed.schema_version) !== 1
    || !Array.isArray(parsed.records)
  ) {
    throw new Error("kcc20_regulated_audit_store_invalid");
  }

  let previousHash: string | null = null;
  const records = parsed.records.map((raw: any, index: number): OmaKcc20RegulatedAuditEventV1 => {
    omaKcc20RegulatedDemoPolicyAssertExactKeys(raw, [
      "schema_kind",
      "schema_version",
      "sequence",
      "event_id",
      "dedupe_key",
      "previous_event_hash",
      "event_hash",
      "occurred_at",
      "recorded_at",
      "networkId",
      "origin",
      "historical_coverage",
      "action_kind",
      "stage",
      "outcome",
      "correlation_id",
      "actor",
      "asset",
      "policy",
      "transaction",
      "decision",
      "amounts",
      "control",
      "supply",
      "source_references",
      "safety"
    ], "kcc20_regulated_audit_event");

    if (
      raw.schema_kind !== OMA_KCC20_REGULATED_AUDIT_EVENT_SCHEMA_KIND
      || Number(raw.schema_version) !== 1
      || Number(raw.sequence) !== index + 1
      || raw.origin !== "audit_journal"
      || raw.historical_coverage !== "complete_for_instrumented_routes"
      || raw.networkId !== "testnet-10"
      || !OMA_KCC20_REGULATED_AUDIT_ACTION_KINDS.has(raw.action_kind)
      || !OMA_KCC20_REGULATED_AUDIT_STAGES.has(raw.stage)
      || !OMA_KCC20_REGULATED_AUDIT_OUTCOMES.has(raw.outcome)
      || !Array.isArray(raw.source_references)
      || !raw.safety
      || typeof raw.safety !== "object"
    ) {
      throw new Error(`kcc20_regulated_audit_event_invalid:${index}`);
    }

    const event = raw as OmaKcc20RegulatedAuditEventV1;
    const eventId = String(event.event_id || "").trim();
    const dedupeKey = String(event.dedupe_key || "").trim();
    const correlationId = String(event.correlation_id || "").trim();
    if (!eventId || eventId.length > 160 || !dedupeKey || dedupeKey.length > 320 || !correlationId || correlationId.length > 160) {
      throw new Error(`kcc20_regulated_audit_event_identifier_invalid:${index}`);
    }

    event.occurred_at = omaKcc20RegulatedAuditIso(event.occurred_at, "kcc20_regulated_audit_occurred_at");
    event.recorded_at = omaKcc20RegulatedAuditIso(event.recorded_at, "kcc20_regulated_audit_recorded_at");
    const suppliedPrevious = omaKcc20RegulatedAuditOptionalHex64(event.previous_event_hash, "kcc20_regulated_audit_previous_event_hash");
    const suppliedHash = omaKcc20RegulatedAuditOptionalHex64(event.event_hash, "kcc20_regulated_audit_event_hash");
    if (!suppliedHash) throw new Error(`kcc20_regulated_audit_event_hash_required:${index}`);
    if (suppliedPrevious !== previousHash) throw new Error(`kcc20_regulated_audit_previous_hash_mismatch:${index}`);
    if (omaKcc20RegulatedAuditEventHash(event) !== suppliedHash) {
      throw new Error(`kcc20_regulated_audit_event_hash_mismatch:${index}`);
    }
    omaKcc20RegulatedAuditAssertNoForbiddenKeys(event);
    previousHash = suppliedHash;
    return event;
  });

  return {
    present: true,
    chain_verified: true,
    head_event_hash: previousHash,
    store: {
      schema_kind: OMA_KCC20_REGULATED_AUDIT_STORE_SCHEMA_KIND,
      schema_version: 1,
      records
    }
  };
}

type OmaKcc20RegulatedAuditAppendParams = {
  actionKind: OmaKcc20RegulatedAuditActionKind;
  stage: OmaKcc20RegulatedAuditStage;
  outcome: OmaKcc20RegulatedAuditOutcome;
  occurredAt: string;
  dedupeKey: string;
  correlationId: string;
  actor?: Record<string, unknown> | null;
  asset?: Record<string, unknown> | null;
  policy?: Record<string, unknown> | null;
  transaction?: Record<string, unknown> | null;
  decision?: Record<string, unknown> | null;
  amounts?: Record<string, unknown> | null;
  control?: Record<string, unknown> | null;
  supply?: Record<string, unknown> | null;
  sourceReferences?: Array<Record<string, unknown>>;
  safety?: Record<string, unknown>;
};

type OmaKcc20RegulatedAuditAppendResult = {
  appended: boolean;
  event: OmaKcc20RegulatedAuditEventV1;
};

function omaKcc20RegulatedAuditComparableEvent(event: OmaKcc20RegulatedAuditEventV1): Record<string, unknown> {
  return {
    networkId: event.networkId,
    action_kind: event.action_kind,
    stage: event.stage,
    outcome: event.outcome,
    correlation_id: event.correlation_id,
    actor: event.actor,
    asset: event.asset,
    policy: event.policy,
    transaction: event.transaction,
    decision: event.decision,
    amounts: event.amounts,
    control: event.control,
    supply: event.supply,
    source_references: event.source_references,
    safety: event.safety
  };
}

function appendOmaKcc20RegulatedAuditEvent(
  repoRootPath: string,
  userId: string,
  params: OmaKcc20RegulatedAuditAppendParams
): OmaKcc20RegulatedAuditAppendResult {
  const journal = readOmaKcc20RegulatedAuditStore(repoRootPath, userId);
  const dedupeKey = String(params.dedupeKey || "").trim();
  const correlationId = String(params.correlationId || "").trim();
  if (!dedupeKey || dedupeKey.length > 320) throw new Error("kcc20_regulated_audit_append_dedupe_key_invalid");
  if (!correlationId || correlationId.length > 160) throw new Error("kcc20_regulated_audit_append_correlation_id_invalid");
  if (!OMA_KCC20_REGULATED_AUDIT_ACTION_KINDS.has(params.actionKind)) throw new Error("kcc20_regulated_audit_append_action_invalid");
  if (!OMA_KCC20_REGULATED_AUDIT_STAGES.has(params.stage)) throw new Error("kcc20_regulated_audit_append_stage_invalid");
  if (!OMA_KCC20_REGULATED_AUDIT_OUTCOMES.has(params.outcome)) throw new Error("kcc20_regulated_audit_append_outcome_invalid");
  if (params.sourceReferences !== undefined && !Array.isArray(params.sourceReferences)) {
    throw new Error("kcc20_regulated_audit_append_source_references_invalid");
  }

  const occurredAt = omaKcc20RegulatedAuditIso(params.occurredAt, "kcc20_regulated_audit_append_occurred_at");
  const recordedAt = new Date().toISOString();
  const safety = {
    demo_only: true,
    production_eligible: false,
    legal_validity_claimed: false,
    signed_transaction_json_included: false,
    signature_script_included: false,
    redeem_script_included: false,
    submit_token_included: false,
    private_key_included: false,
    signer_material_included: false,
    custody_material_included: false,
    ...(params.safety || {})
  };
  const comparable = {
    networkId: "testnet-10",
    action_kind: params.actionKind,
    stage: params.stage,
    outcome: params.outcome,
    correlation_id: correlationId,
    actor: params.actor ?? null,
    asset: params.asset ?? null,
    policy: params.policy ?? null,
    transaction: params.transaction ?? null,
    decision: params.decision ?? null,
    amounts: params.amounts ?? null,
    control: params.control ?? null,
    supply: params.supply ?? null,
    source_references: params.sourceReferences || [],
    safety
  };
  omaKcc20RegulatedAuditAssertNoForbiddenKeys(comparable);

  const existing = journal.store.records.find((event) => event.dedupe_key === dedupeKey) || null;
  if (existing) {
    if (omaStableJson(omaKcc20RegulatedAuditComparableEvent(existing)) !== omaStableJson(comparable)) {
      throw new Error("kcc20_regulated_audit_append_dedupe_conflict");
    }
    return { appended: false, event: existing };
  }

  const sequence = journal.store.records.length + 1;
  const eventId = `audit:${sequence}:${omaSha256Text(`${dedupeKey}:${correlationId}:${occurredAt}`).slice(0, 48)}`;
  const event: OmaKcc20RegulatedAuditEventV1 = {
    schema_kind: OMA_KCC20_REGULATED_AUDIT_EVENT_SCHEMA_KIND,
    schema_version: 1,
    sequence,
    event_id: eventId,
    dedupe_key: dedupeKey,
    previous_event_hash: journal.head_event_hash,
    event_hash: null,
    occurred_at: occurredAt,
    recorded_at: recordedAt,
    networkId: "testnet-10",
    origin: "audit_journal",
    historical_coverage: "complete_for_instrumented_routes",
    action_kind: params.actionKind,
    stage: params.stage,
    outcome: params.outcome,
    correlation_id: correlationId,
    actor: params.actor ?? null,
    asset: params.asset ?? null,
    policy: params.policy ?? null,
    transaction: params.transaction ?? null,
    decision: params.decision ?? null,
    amounts: params.amounts ?? null,
    control: params.control ?? null,
    supply: params.supply ?? null,
    source_references: params.sourceReferences || [],
    safety
  };
  event.event_hash = omaKcc20RegulatedAuditEventHash(event);
  omaKcc20RegulatedAuditAssertNoForbiddenKeys(event);

  const nextStore: OmaKcc20RegulatedAuditStoreV1 = {
    schema_kind: OMA_KCC20_REGULATED_AUDIT_STORE_SCHEMA_KIND,
    schema_version: 1,
    records: [...journal.store.records, event]
  };
  const filePath = omaKcc20RegulatedAuditPath(repoRootPath, userId);
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const tempPath = `${filePath}.tmp.${process.pid}.${randomUUID()}`;
  fs.writeFileSync(tempPath, JSON.stringify(nextStore, null, 2) + "\n", { mode: 0o600 });
  fs.renameSync(tempPath, filePath);
  return { appended: true, event };
}

function omaKcc20RegulatedAuditPolicyDiff(
  previousPolicy: Kcc20RegulatedDemoPolicyV1 | null,
  nextPolicy: Kcc20RegulatedDemoPolicyV1
): Record<string, unknown> {
  const fields: Array<keyof OmaKcc20RegulatedDemoPolicyContentV1> = [
    "regulated_asset_covenant_ids",
    "recipient_allowlist",
    "recipient_blacklist",
    "frozen_holders",
    "frozen_outpoints",
    "lawful_order_actions"
  ];
  const result: Record<string, unknown> = {};
  const changedFields: string[] = [];
  for (const field of fields) {
    const before = Array.isArray(previousPolicy?.[field]) ? [...(previousPolicy?.[field] as any[])] : [];
    const after = Array.isArray(nextPolicy[field]) ? [...(nextPolicy[field] as any[])] : [];
    const beforeSet = new Set(before.map((value) => omaStableJson(value)));
    const afterSet = new Set(after.map((value) => omaStableJson(value)));
    const added = after.filter((value) => !beforeSet.has(omaStableJson(value)));
    const removed = before.filter((value) => !afterSet.has(omaStableJson(value)));
    if (added.length || removed.length) changedFields.push(String(field));
    result[String(field)] = { added, removed, before_count: before.length, after_count: after.length };
  }
  return { changed_fields: changedFields, fields: result };
}

function omaKcc20RegulatedAuditPolicySnapshot(policy: Kcc20RegulatedDemoPolicyV1): Record<string, unknown> {
  const derived = omaKcc20RegulatedDemoPolicyDerive(policy);
  return {
    policy_epoch: policy.policy_epoch,
    source_policy_snapshot_id: derived.source_policy_snapshot_id,
    rulebook_root: derived.rulebook_root,
    regulated_asset_covenant_ids: policy.regulated_asset_covenant_ids,
    recipient_allowlist: policy.recipient_allowlist,
    recipient_blacklist: policy.recipient_blacklist,
    frozen_holders: policy.frozen_holders,
    frozen_outpoints: policy.frozen_outpoints,
    lawful_order_actions: policy.lawful_order_actions
  };
}

function omaKcc20RegulatedAuditCurrentPolicySnapshot(
  repoRootPath: string,
  userId: string
): Record<string, unknown> | null {
  try {
    const current = omaKcc20RegulatedDemoPolicyRead(repoRootPath, userId);
    return current ? omaKcc20RegulatedAuditPolicySnapshot(current) : null;
  } catch {
    return null;
  }
}

function omaKcc20RegulatedAuditActorFromWallet(
  active: any,
  fallbackUserId: string,
  role: "demo_policy_owner" | "registry_authority"
): Record<string, unknown> {
  return {
    user_id: fallbackUserId,
    wallet_id: String(active?.id || "") || null,
    address: String(active?.address0 || "") || null,
    role
  };
}

function omaKcc20RegulatedAuditRelativePath(repoRootPath: string, filePath: string): string {
  return path.relative(repoRootPath, filePath).replace(/\\/g, "/");
}

function omaInstallKcc20RegulatedAuditRejectedResponseHook(
  res: express.Response,
  params: {
    repoRootPath: string;
    userId: string;
    actionKind: () => OmaKcc20RegulatedAuditActionKind;
    actor: () => Record<string, unknown> | null;
    policy?: () => Record<string, unknown> | null;
    asset?: () => Record<string, unknown> | null;
    sourceReferences: () => Array<Record<string, unknown>>;
    shouldCapture?: () => boolean;
  }
): void {
  const originalJson = res.json.bind(res);
  const rejectionCorrelationId = `rejection:${randomUUID()}`;
  const occurredAt = new Date().toISOString();
  let captured = false;
  (res as any).json = (body: any) => {
    if (
      !captured
      && res.statusCode >= 400
      && body
      && typeof body === "object"
      && body.ok === false
      && (!params.shouldCapture || params.shouldCapture())
    ) {
      captured = true;
      try {
        const reasonCode = String(body.reason || "request_rejected").trim().slice(0, 160) || "request_rejected";
        const actionKind = params.actionKind();
        appendOmaKcc20RegulatedAuditEvent(params.repoRootPath, params.userId, {
          actionKind,
          stage: "rejected",
          outcome: "rejected",
          occurredAt,
          dedupeKey: `${actionKind}:rejected:${rejectionCorrelationId}`,
          correlationId: rejectionCorrelationId,
          actor: params.actor(),
          asset: params.asset ? params.asset() : null,
          policy: params.policy ? params.policy() : null,
          decision: {
            allowed: false,
            reason_code: reasonCode,
            http_status: res.statusCode
          },
          sourceReferences: params.sourceReferences()
        });
      } catch {
        console.error("kcc20_regulated_audit_rejection_append_failed");
      }
    }
    return originalJson(body);
  };
}

type OmaKcc20RegulatedAuditLifecyclePhase = "build" | "submit";

type OmaKcc20RegulatedAuditLifecycleHookParams = {
  repoRootPath: string;
  userId: string;
  actionKind: Extract<OmaKcc20RegulatedAuditActionKind,
    "regulated_deploy" | "regulated_issue" | "holder_transfer" | "holder_burn" | "change_owner">;
  phase: OmaKcc20RegulatedAuditLifecyclePhase;
  actor: Record<string, unknown>;
  requestBody: Record<string, unknown>;
  assetCovenantId?: string | null;
  tokenSymbol?: string | null;
  regulatedProfile: OmaL1TokenRegulatedCompactState;
  correlationHint?: string | null;
  sourceReferences?: Array<Record<string, unknown>>;
};

function omaKcc20RegulatedAuditReadPath(value: unknown, pathText: string): unknown {
  let cursor: any = value;
  for (const part of pathText.split(".")) {
    if (!cursor || typeof cursor !== "object" || !(part in cursor)) return undefined;
    cursor = cursor[part];
  }
  return cursor;
}

function omaKcc20RegulatedAuditFirstText(value: unknown, paths: string[], maxLength = 256): string | null {
  for (const pathText of paths) {
    const candidate = omaKcc20RegulatedAuditReadPath(value, pathText);
    if (candidate === null || candidate === undefined) continue;
    const text = String(candidate).trim();
    if (text) return text.slice(0, maxLength);
  }
  return null;
}

function omaKcc20RegulatedAuditFirstBoolean(value: unknown, paths: string[]): boolean | null {
  for (const pathText of paths) {
    const candidate = omaKcc20RegulatedAuditReadPath(value, pathText);
    if (candidate === true || candidate === false) return candidate;
  }
  return null;
}

function omaKcc20RegulatedAuditSafeStringArray(value: unknown, maxItems = 64): string[] {
  if (!Array.isArray(value)) return [];
  return value
    .map((item) => String(item ?? "").trim())
    .filter(Boolean)
    .slice(0, maxItems)
    .map((item) => item.slice(0, 320));
}

function omaKcc20RegulatedAuditLifecycleAmounts(
  requestBody: Record<string, unknown>,
  responseBody: Record<string, unknown>
): Record<string, unknown> | null {
  const definitions: Array<[string, string[]]> = [
    ["max_supply_raw", ["token_definition.max_supply_raw", "max_supply_raw"]],
    ["initial_issue_raw", ["token_definition.initial_issue_raw", "initial_issue_raw"]],
    ["issue_amount_raw", ["issue_plan.issue_amount_raw", "issue_amount_raw", "amount_raw"]],
    ["transfer_amount_raw", ["transfer_plan.transfer_amount_raw", "transfer_amount_raw", "amount_raw"]],
    ["burn_amount_raw", ["burn_plan.burn_amount_raw", "burn_amount_raw", "amount_raw"]],
    ["recipient_amount_raw", ["transfer_plan.recipient_amount_raw", "recipient_amount_raw"]],
    ["sender_change_amount_raw", ["transfer_plan.sender_change_amount_raw", "sender_change_amount_raw"]],
    ["issued_supply_before_raw", ["issue_plan.issued_supply_before_raw", "issued_supply_before_raw"]],
    ["issued_supply_after_raw", ["issue_plan.issued_supply_after_raw", "issued_supply_after_raw"]]
  ];
  const amounts: Record<string, unknown> = {};
  for (const [label, paths] of definitions) {
    const responseValue = omaKcc20RegulatedAuditFirstText(responseBody, paths, 120);
    const requestValue = omaKcc20RegulatedAuditFirstText(requestBody, paths, 120);
    const selected = responseValue || requestValue;
    if (selected !== null) amounts[label] = selected;
  }
  return Object.keys(amounts).length ? amounts : null;
}

function omaKcc20RegulatedAuditLifecycleSourceOutpoints(responseBody: Record<string, unknown>): string[] {
  const direct = omaKcc20RegulatedAuditSafeStringArray(responseBody.source_holder_outpoints);
  const nestedRows = [
    omaKcc20RegulatedAuditReadPath(responseBody, "transfer_plan.source_holders"),
    omaKcc20RegulatedAuditReadPath(responseBody, "burn_plan.source_holders")
  ];
  const nested: string[] = [];
  for (const rows of nestedRows) {
    if (!Array.isArray(rows)) continue;
    for (const row of rows) {
      const outpoint = String((row as any)?.outpoint || "").trim();
      if (outpoint) nested.push(outpoint.slice(0, 320));
    }
  }
  return Array.from(new Set([...direct, ...nested])).slice(0, 64);
}

function omaInstallKcc20RegulatedAuditTokenLifecycleResponseHook(
  res: express.Response,
  params: OmaKcc20RegulatedAuditLifecycleHookParams
): void {
  const originalJson = res.json.bind(res);
  const installedAt = new Date().toISOString();
  let captured = false;

  (res as any).json = (body: any) => {
    if (!captured && body && typeof body === "object" && (body.ok === true || body.ok === false)) {
      captured = true;
      try {
        const responseBody = body as Record<string, unknown>;
        const assetCovenantId = (
          omaKcc20RegulatedAuditFirstText(responseBody, [
            "asset_covenant_id",
            "token_definition.asset_covenant_id",
            "tracked_asset.asset_covenant_id",
            "tracking.asset_covenant_id"
          ], 64)
          || String(params.assetCovenantId || "").trim().toLowerCase()
          || null
        );
        const tokenSymbol = (
          omaKcc20RegulatedAuditFirstText(responseBody, [
            "token_symbol",
            "token_definition.token_symbol",
            "tracked_asset.token_symbol",
            "tracking.token_symbol"
          ], 32)
          || String(params.tokenSymbol || "").trim()
          || null
        );
        const unsignedPlanSha256 = omaKcc20RegulatedAuditFirstText(responseBody, [
          "unsigned_safe_json_sha256",
          "unsigned_plan_sha256"
        ], 64);
        const signedPlanSha256 = omaKcc20RegulatedAuditFirstText(responseBody, [
          "signed_safe_json_sha256",
          "signed_plan_sha256"
        ], 64);
        const submittedTxid = omaKcc20RegulatedAuditFirstText(responseBody, [
          "submitted_txid",
          "transaction_id",
          "tracking.submitted_txid"
        ], 64);
        const signedTxid = omaKcc20RegulatedAuditFirstText(responseBody, ["signed_txid"], 64);
        const previewTxid = omaKcc20RegulatedAuditFirstText(responseBody, ["txid_preview", "finalized_txid"], 64);
        const applicationStatus = omaKcc20RegulatedAuditFirstText(responseBody, ["application_status"], 160);
        const correlationSeed = String(
          params.correlationHint
          || unsignedPlanSha256
          || submittedTxid
          || signedTxid
          || previewTxid
          || assetCovenantId
          || `${params.actionKind}:${installedAt}`
        );
        const correlationId = `${params.actionKind}:${omaSha256Text(correlationSeed).slice(0, 64)}`;
        const sourceOutpoints = omaKcc20RegulatedAuditLifecycleSourceOutpoints(responseBody);
        const responseDecision = omaKcc20RegulatedAuditReadPath(responseBody, "demo_policy_decision") as any;
        const rejectionReasons = omaKcc20RegulatedAuditSafeStringArray(
          responseDecision?.rejection_reasons || responseBody.rejection_reasons
        );
        const policyEpoch = omaKcc20RegulatedAuditFirstText(responseBody, [
          "demo_policy_decision.successor_policy_epoch",
          "demo_policy_decision.policy_epoch",
          "policy_epoch",
          "token_definition.policy_registry_verification.policy_epoch"
        ], 32) || String(params.regulatedProfile.pe);
        const rulebookRoot = omaKcc20RegulatedAuditFirstText(responseBody, [
          "demo_policy_decision.rulebook_root",
          "rulebook_root",
          "token_definition.policy_registry_verification.rulebook_root"
        ], 64);
        const transaction = {
          transaction_id: submittedTxid,
          signed_transaction_id: signedTxid,
          preview_transaction_id: previewTxid,
          unsigned_plan_sha256: unsignedPlanSha256,
          signed_plan_sha256: signedPlanSha256,
          submitted_matches_signed: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["submitted_txid_matches_signed"]),
          source_outpoints: sourceOutpoints
        };
        const policy = {
          registry_covenant_id: params.regulatedProfile.pr,
          source_policy_epoch: params.regulatedProfile.pe,
          applied_policy_epoch: policyEpoch,
          rulebook_root: rulebookRoot,
          control_flags: params.regulatedProfile.fc,
          policy_source_mode: omaKcc20RegulatedAuditFirstText(responseBody, [
            "demo_policy_decision.policy_source_mode",
            "policy_source_mode"
          ], 120)
        };
        const asset = {
          asset_covenant_id: assetCovenantId,
          token_symbol: tokenSymbol,
          regulated_profile_version: params.regulatedProfile.rv,
          regulated: params.regulatedProfile.rg === 1
        };
        const decision = {
          allowed: responseDecision?.allowed === true ? true : (responseDecision?.allowed === false ? false : null),
          reason_code: omaKcc20RegulatedAuditFirstText(responseBody, ["reason"], 160),
          rejection_reasons: rejectionReasons,
          http_status: res.statusCode,
          application_status: applicationStatus
        };
        const sourceReferences = [
          ...(params.sourceReferences || []),
          {
            source_kind: "tracked_assets",
            relative_path: `data/users/${params.userId}/${OMA_L1_TRACKED_ASSETS_FILE_NAME}`
          }
        ];

        const appendStage = (
          stage: OmaKcc20RegulatedAuditStage,
          outcome: OmaKcc20RegulatedAuditOutcome,
          suffix: string
        ) => appendOmaKcc20RegulatedAuditEvent(params.repoRootPath, params.userId, {
          actionKind: params.actionKind,
          stage,
          outcome,
          occurredAt: new Date().toISOString(),
          dedupeKey: `${params.actionKind}:${stage}:${correlationId}:${suffix}`,
          correlationId,
          actor: params.actor,
          asset,
          policy,
          transaction,
          decision,
          amounts: omaKcc20RegulatedAuditLifecycleAmounts(params.requestBody, responseBody),
          sourceReferences,
          safety: {
            route_phase: params.phase,
            response_captured_after_route_decision: true
          }
        });

        if (body.ok === false || res.statusCode >= 400) {
          appendStage(
            "rejected",
            "rejected",
            `http_${res.statusCode}:${omaSha256Text(String(decision.reason_code || "request_rejected")).slice(0, 16)}`
          );
        } else if (params.phase === "build") {
          appendStage("built", "success", "build");
        } else {
          appendStage("signed_locally", "success", "validated_signed_submit_payload");
          appendStage("submitted", "success", submittedTxid || signedTxid || "submit");
          const liveVerified = responseBody.live_verified === true
            || String(applicationStatus || "").toLowerCase().includes("live_verified")
            || String(omaKcc20RegulatedAuditReadPath(responseBody, "post_submit_scan.status") || "").toLowerCase().includes("visible")
            || String(omaKcc20RegulatedAuditReadPath(responseBody, "tracked_asset.tracking_status") || "").toLowerCase().includes("live_chain_verification");
          const trackingPresent = !!omaKcc20RegulatedAuditReadPath(responseBody, "tracking")
            || !!omaKcc20RegulatedAuditReadPath(responseBody, "tracked_asset")
            || !!omaKcc20RegulatedAuditReadPath(responseBody, "post_submit_scan");
          if (liveVerified) appendStage("live_verified", "success", submittedTxid || "live");
          else if (trackingPresent) appendStage("tracking_updated", "pending", submittedTxid || "tracking");
          else appendStage("accepted", "success", submittedTxid || "accepted");
        }
      } catch {
        console.error("kcc20_regulated_audit_token_lifecycle_append_failed");
      }
    }
    return originalJson(body);
  };
}


type OmaKcc20RegulatedAuditControlActionKind = Extract<OmaKcc20RegulatedAuditActionKind,
  "seize" | "forced_burn" | "controller_supply_update">;

type OmaKcc20RegulatedAuditControlHookParams = {
  repoRootPath: string;
  userId: string;
  actionKind: OmaKcc20RegulatedAuditControlActionKind;
  phase: OmaKcc20RegulatedAuditLifecyclePhase;
  actor: Record<string, unknown>;
  requestBody: Record<string, unknown>;
  assetCovenantId?: string | null;
  tokenSymbol?: string | null;
  regulatedProfile?: OmaL1TokenRegulatedCompactState | null;
  sourceReferences?: Array<Record<string, unknown>>;
};

function omaKcc20RegulatedAuditProfileForAsset(
  repoRootPath: string,
  userId: string,
  assetCovenantId: string
): OmaL1TokenRegulatedCompactState | null {
  const assetId = String(assetCovenantId || "").trim().toLowerCase();
  if (!/^[0-9a-f]{64}$/.test(assetId)) return null;
  try {
    const records = readOmaL1TrackedAssetStore(repoRootPath, userId).records;
    for (const record of records) {
      if (String(record?.asset_covenant_id || "").trim().toLowerCase() !== assetId) continue;
      const profile = omaReadKcc20StoredRegulatedCompactState(record?.regulated_profile);
      if (profile) return profile;
    }
  } catch {
    return null;
  }
  return null;
}

function omaAppendKcc20RegulatedAuditPolicyControlEvents(params: {
  repoRootPath: string;
  userId: string;
  previousPolicy: Kcc20RegulatedDemoPolicyV1 | null;
  nextPolicy: Kcc20RegulatedDemoPolicyV1;
  actor: Record<string, unknown>;
  sourceReferences: Array<Record<string, unknown>>;
}): void {
  const nextDerived = omaKcc20RegulatedDemoPolicyDerive(params.nextPolicy);
  const previousDerived = params.previousPolicy
    ? omaKcc20RegulatedDemoPolicyDerive(params.previousPolicy)
    : null;
  const policy = {
    ...omaKcc20RegulatedAuditPolicySnapshot(params.nextPolicy),
    previous_policy_epoch: params.previousPolicy?.policy_epoch ?? null,
    previous_rulebook_root: previousDerived?.rulebook_root ?? null,
    registry_publication_required: true
  };
  const definitions: Array<{
    field: "frozen_holders" | "frozen_outpoints";
    targetKind: "holder" | "outpoint";
    freezeAction: Extract<OmaKcc20RegulatedAuditActionKind, "freeze_holder" | "freeze_outpoint">;
    unfreezeAction: Extract<OmaKcc20RegulatedAuditActionKind, "unfreeze_holder" | "unfreeze_outpoint">;
  }> = [
    {
      field: "frozen_holders",
      targetKind: "holder",
      freezeAction: "freeze_holder",
      unfreezeAction: "unfreeze_holder"
    },
    {
      field: "frozen_outpoints",
      targetKind: "outpoint",
      freezeAction: "freeze_outpoint",
      unfreezeAction: "unfreeze_outpoint"
    }
  ];

  for (const definition of definitions) {
    const before = new Set((params.previousPolicy?.[definition.field] || []).map((value) => String(value)));
    const after = new Set((params.nextPolicy[definition.field] || []).map((value) => String(value)));
    const changes: Array<{ actionKind: OmaKcc20RegulatedAuditActionKind; change: "added" | "removed"; target: string }> = [];
    for (const target of after) if (!before.has(target)) changes.push({ actionKind: definition.freezeAction, change: "added", target });
    for (const target of before) if (!after.has(target)) changes.push({ actionKind: definition.unfreezeAction, change: "removed", target });

    for (const change of changes) {
      const targetHash = omaSha256Text(change.target).slice(0, 32);
      const correlationId = `policy_control:${params.nextPolicy.policy_epoch}:${nextDerived.rulebook_root}:${targetHash}`;
      appendOmaKcc20RegulatedAuditEvent(params.repoRootPath, params.userId, {
        actionKind: change.actionKind,
        stage: "planned",
        outcome: "pending",
        occurredAt: params.nextPolicy.updated_at,
        dedupeKey: `${change.actionKind}:planned:${params.nextPolicy.policy_epoch}:${targetHash}`,
        correlationId,
        actor: params.actor,
        policy,
        decision: {
          policy_saved: true,
          registry_publication_required: true,
          control_effective_only_after_matching_registry_publication: true
        },
        control: {
          target_kind: definition.targetKind,
          target: change.target,
          policy_change: change.change,
          policy_epoch: params.nextPolicy.policy_epoch,
          rulebook_root: nextDerived.rulebook_root
        },
        sourceReferences: params.sourceReferences,
        safety: {
          policy_control_transaction_created: false,
          control_effect_pending_registry_publication: true
        }
      });
    }
  }
}

function omaInstallKcc20RegulatedAuditControlLifecycleResponseHook(
  res: express.Response,
  params: OmaKcc20RegulatedAuditControlHookParams
): void {
  const originalJson = res.json.bind(res);
  const installedAt = new Date().toISOString();
  let captured = false;

  (res as any).json = (body: any) => {
    if (!captured && body && typeof body === "object" && (body.ok === true || body.ok === false)) {
      captured = true;
      try {
        const responseBody = body as Record<string, unknown>;
        const assetCovenantId = (
          omaKcc20RegulatedAuditFirstText(responseBody, [
            "asset_covenant_id",
            "token_definition.asset_covenant_id",
            "tracked_asset.asset_covenant_id"
          ], 64)
          || omaKcc20RegulatedAuditFirstText(params.requestBody, ["asset_covenant_id", "assetCovenantId"], 64)
          || String(params.assetCovenantId || "").trim().toLowerCase()
          || null
        );
        const regulatedProfile = params.regulatedProfile
          || (assetCovenantId
            ? omaKcc20RegulatedAuditProfileForAsset(params.repoRootPath, params.userId, assetCovenantId)
            : null);
        if (params.actionKind === "controller_supply_update" && !regulatedProfile) {
          return originalJson(body);
        }

        const tokenSymbol = (
          omaKcc20RegulatedAuditFirstText(responseBody, [
            "token_symbol",
            "token_definition.token_symbol",
            "tracked_asset.token_symbol"
          ], 32)
          || String(params.tokenSymbol || "").trim()
          || null
        );
        const orderReference = omaKcc20RegulatedAuditFirstText(responseBody, ["order_reference"], 96)
          || omaKcc20RegulatedAuditFirstText(params.requestBody, ["order_reference", "orderReference"], 96);
        const receiptTxids = omaKcc20RegulatedAuditSafeStringArray(
          omaKcc20RegulatedAuditReadPath(responseBody, "burn_receipts.submitted_txids")
        );
        const responseReceiptTxid = omaKcc20RegulatedAuditFirstText(responseBody, [
          "burn_receipt.submitted_txid",
          "submitted_txid"
        ], 64);
        const requestedReceiptTxid = omaKcc20RegulatedAuditFirstText(params.requestBody, [
          "burn_receipt_txid",
          "burnReceiptTxid",
          "receipt_submitted_txid",
          "receiptSubmittedTxid"
        ], 64);
        const selectedReceiptTxids = Array.from(new Set([
          ...receiptTxids,
          ...(responseReceiptTxid ? [responseReceiptTxid] : []),
          ...(requestedReceiptTxid ? [requestedReceiptTxid] : [])
        ])).slice(0, 64);
        const unsignedPlanSha256 = omaKcc20RegulatedAuditFirstText(responseBody, [
          "unsigned_safe_json_sha256",
          "unsigned_plan_sha256"
        ], 64);
        const signedPlanSha256 = omaKcc20RegulatedAuditFirstText(responseBody, [
          "signed_safe_json_sha256",
          "signed_plan_sha256"
        ], 64);
        const submittedTxid = omaKcc20RegulatedAuditFirstText(responseBody, [
          "submitted_txid",
          "transaction_id"
        ], 64);
        const signedTxid = omaKcc20RegulatedAuditFirstText(responseBody, ["signed_txid"], 64);
        const previewTxid = omaKcc20RegulatedAuditFirstText(responseBody, ["txid_preview", "finalized_txid"], 64);
        const applicationStatus = omaKcc20RegulatedAuditFirstText(responseBody, ["application_status"], 160);
        const registryCovenantId = omaKcc20RegulatedAuditFirstText(responseBody, ["registry_covenant_id"], 64)
          || regulatedProfile?.pr
          || null;
        const currentPolicy = (() => {
          try { return omaKcc20RegulatedDemoPolicyRead(params.repoRootPath, params.userId); }
          catch { return null; }
        })();
        const currentPolicySnapshot = currentPolicy
          ? omaKcc20RegulatedAuditPolicySnapshot(currentPolicy)
          : null;
        const policyEpoch = omaKcc20RegulatedAuditFirstText(responseBody, ["policy_epoch"], 32)
          || (currentPolicy ? String(currentPolicy.policy_epoch) : null)
          || (regulatedProfile ? String(regulatedProfile.pe) : null);
        const rulebookRoot = omaKcc20RegulatedAuditFirstText(responseBody, ["rulebook_root"], 64)
          || (currentPolicySnapshot ? String((currentPolicySnapshot as any).rulebook_root || "") || null : null);
        const sourceOutpoints = Array.from(new Set([
          ...omaKcc20RegulatedAuditSafeStringArray(responseBody.source_holder_outpoints),
          ...omaKcc20RegulatedAuditSafeStringArray(
            omaKcc20RegulatedAuditReadPath(responseBody, "transaction.source_outpoints")
          )
        ])).slice(0, 64);
        const correlationSeed = String(
          orderReference
          || selectedReceiptTxids[0]
          || unsignedPlanSha256
          || submittedTxid
          || signedTxid
          || previewTxid
          || assetCovenantId
          || `${params.actionKind}:${installedAt}`
        );
        const correlationId = `${params.actionKind}:${omaSha256Text(correlationSeed).slice(0, 64)}`;
        const controllerSupplyStatus = omaKcc20RegulatedAuditFirstText(responseBody, [
          "burn_receipt.controller_supply_update_status",
          "burn_receipts.controller_supply_update_status"
        ], 160);
        const postSubmitStatus = omaKcc20RegulatedAuditFirstText(responseBody, [
          "post_submit_scan.status",
          "post_submit_scan_status"
        ], 160);
        const liveVerified = responseBody.live_verified === true
          || String(applicationStatus || "").toLowerCase().includes("live_verified")
          || String(postSubmitStatus || "").toLowerCase().includes("outputs_visible")
          || String(postSubmitStatus || "").toLowerCase().includes("submitted_and_");
        const supplyPending = params.actionKind === "forced_burn"
          && !!controllerSupplyStatus
          && (controllerSupplyStatus.includes("not_updated") || controllerSupplyStatus.includes("pending"));
        const supplyCompleted = params.actionKind === "controller_supply_update"
          && !!controllerSupplyStatus
          && controllerSupplyStatus.includes("updated_after_controller_supply_submit");
        const transaction = {
          transaction_id: submittedTxid,
          signed_transaction_id: signedTxid,
          preview_transaction_id: previewTxid,
          unsigned_plan_sha256: unsignedPlanSha256,
          signed_plan_sha256: signedPlanSha256,
          submitted_matches_signed: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["submitted_txid_matches_signed"]),
          source_outpoints: sourceOutpoints
        };
        const control = {
          order_reference: orderReference,
          target_holder_address: omaKcc20RegulatedAuditFirstText(responseBody, ["target_holder_address"], 180),
          target_authorization_basis: omaKcc20RegulatedAuditFirstText(responseBody, ["target_authorization_basis"], 80),
          freeze_requirement_waived: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["freeze_requirement_waived"]),
          destination_address: omaKcc20RegulatedAuditFirstText(responseBody, ["destination_address"], 180),
          registry_covenant_id: registryCovenantId,
          registry_covenant_id_continuity: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["registry_covenant_id_continuity"]),
          holder_signature_required: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["holder_signature_required"]),
          registry_authority_signature_required: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["registry_authority_signature_required"]),
          source_holder_outpoints: omaKcc20RegulatedAuditSafeStringArray(responseBody.source_holder_outpoints),
          source_holder_spent: omaKcc20RegulatedAuditFirstBoolean(responseBody, ["source_holder_spent"])
        };
        const amounts = {
          seize_amount_raw: omaKcc20RegulatedAuditFirstText(responseBody, ["seize_amount_raw"], 120)
            || omaKcc20RegulatedAuditFirstText(params.requestBody, ["seize_amount_raw", "seizeAmountRaw"], 120),
          burn_amount_raw: omaKcc20RegulatedAuditFirstText(responseBody, [
            "burned_amount_raw",
            "burn_amount_raw",
            "token_definition.burn_amount_raw",
            "supply_update_result.burn_amount_raw"
          ], 120)
            || omaKcc20RegulatedAuditFirstText(params.requestBody, ["burn_amount_raw", "burnAmountRaw"], 120),
          holder_remainder_amount_raw: omaKcc20RegulatedAuditFirstText(responseBody, ["holder_remainder_amount_raw"], 120),
          issued_supply_before_raw: omaKcc20RegulatedAuditFirstText(responseBody, [
            "token_definition.issued_supply_before_raw",
            "supply_update_result.issued_supply_before_raw"
          ], 120),
          issued_supply_after_raw: omaKcc20RegulatedAuditFirstText(responseBody, [
            "token_definition.issued_supply_after_raw",
            "supply_update_result.issued_supply_after_raw",
            "tracked_asset.issued_supply_after_raw"
          ], 120)
        };
        const cleanAmounts = Object.fromEntries(Object.entries(amounts).filter(([, value]) => value !== null));
        const supply = {
          burn_receipt_submitted_txids: selectedReceiptTxids,
          controller_supply_update_status: controllerSupplyStatus,
          supply_update_pending: supplyPending,
          supply_update_completed: supplyCompleted,
          issued_supply_before_raw: amounts.issued_supply_before_raw,
          issued_supply_after_raw: amounts.issued_supply_after_raw,
          burn_amount_raw: amounts.burn_amount_raw
        };
        const asset = {
          asset_covenant_id: assetCovenantId,
          token_symbol: tokenSymbol,
          regulated: !!regulatedProfile,
          regulated_profile_version: regulatedProfile?.rv ?? null
        };
        const policy = {
          ...(currentPolicySnapshot || {}),
          registry_covenant_id: registryCovenantId,
          applied_policy_epoch: policyEpoch,
          rulebook_root: rulebookRoot,
          control_flags: regulatedProfile?.fc ?? null,
          policy_source_mode: "Testnet-10 Local Demo Policy"
        };
        const decision = {
          allowed: responseBody.ok === true,
          reason_code: omaKcc20RegulatedAuditFirstText(responseBody, ["reason"], 160),
          http_status: res.statusCode,
          application_status: applicationStatus,
          demo_only: true,
          production_eligible: false,
          legal_validity_claimed: false
        };
        const sourceReferences = [
          ...(params.sourceReferences || []),
          { source_kind: "tracked_assets", relative_path: `data/users/${params.userId}/${OMA_L1_TRACKED_ASSETS_FILE_NAME}` },
          { source_kind: "demo_policy", relative_path: `data/users/${params.userId}/${OMA_KCC20_REGULATED_DEMO_POLICY_FILE}` },
          { source_kind: "policy_registry", relative_path: `data/users/${params.userId}/${OMA_KCC20_POLICY_REGISTRY_STORE_FILE}` },
          { source_kind: "burn_receipts", relative_path: `data/users/${params.userId}/${OMA_L1_BURN_RECEIPTS_FILE_NAME}` }
        ];

        const appendStage = (
          stage: OmaKcc20RegulatedAuditStage,
          outcome: OmaKcc20RegulatedAuditOutcome,
          suffix: string,
          stageSupply: Record<string, unknown> | null = supply
        ) => appendOmaKcc20RegulatedAuditEvent(params.repoRootPath, params.userId, {
          actionKind: params.actionKind,
          stage,
          outcome,
          occurredAt: installedAt,
          dedupeKey: `${params.actionKind}:${stage}:${correlationId}:${suffix}`,
          correlationId,
          actor: params.actor,
          asset,
          policy,
          transaction,
          decision,
          amounts: Object.keys(cleanAmounts).length ? cleanAmounts : null,
          control,
          supply: stageSupply,
          sourceReferences,
          safety: {
            route_phase: params.phase,
            response_captured_after_route_decision: true,
            holder_signature_required: control.holder_signature_required,
            registry_authority_signature_required: control.registry_authority_signature_required
          }
        });

        if (responseBody.ok === false || res.statusCode >= 400) {
          appendStage(
            "rejected",
            "rejected",
            `http_${res.statusCode}:${omaSha256Text(String(decision.reason_code || "request_rejected")).slice(0, 16)}`,
            null
          );
        } else if (params.phase === "build") {
          appendStage("built", "success", unsignedPlanSha256 || previewTxid || "build");
        } else {
          appendStage("signed_locally", "success", "validated_signed_submit_payload");
          appendStage("submitted", "success", submittedTxid || signedTxid || "submit");
          appendStage(liveVerified ? "live_verified" : "accepted", liveVerified ? "success" : "pending", submittedTxid || "accepted");
          const trackingPresent = !!omaKcc20RegulatedAuditReadPath(responseBody, "tracked_asset")
            || responseBody.tracked_holder_record_count !== undefined
            || !!omaKcc20RegulatedAuditReadPath(responseBody, "burn_receipt")
            || !!omaKcc20RegulatedAuditReadPath(responseBody, "burn_receipts");
          if (trackingPresent) appendStage("tracking_updated", "success", submittedTxid || "tracking");
          if (supplyPending) appendStage("supply_update_pending", "pending", responseReceiptTxid || submittedTxid || "pending_supply");
        }
      } catch {
        console.error("kcc20_regulated_audit_control_lifecycle_append_failed");
      }
    }
    return originalJson(body);
  };
}

function omaKcc20RegulatedAuditSourceManifestRow(params: {
  repoRootPath: string;
  sourceKind: string;
  filePath: string;
  authoritativeRole: string;
  recordCount: number | null;
}): OmaKcc20RegulatedAuditSourceManifestRow {
  const exists = fs.existsSync(params.filePath);
  const bytes = exists ? fs.readFileSync(params.filePath) : null;
  return {
    source_kind: params.sourceKind,
    relative_path: path.relative(params.repoRootPath, params.filePath).replace(/\\/g, "/"),
    authoritative_role: params.authoritativeRole,
    exists,
    sha256: bytes ? createHash("sha256").update(bytes).digest("hex") : null,
    byte_length: bytes ? bytes.byteLength : 0,
    record_count: params.recordCount
  };
}

function omaKcc20RegulatedAuditProjectionEvent(params: {
  actionKind: OmaKcc20RegulatedAuditActionKind;
  stage: OmaKcc20RegulatedAuditStage;
  outcome: OmaKcc20RegulatedAuditOutcome;
  occurredAt: string;
  dedupeKey: string;
  correlationId: string;
  actor?: Record<string, unknown> | null;
  asset?: Record<string, unknown> | null;
  policy?: Record<string, unknown> | null;
  transaction?: Record<string, unknown> | null;
  decision?: Record<string, unknown> | null;
  amounts?: Record<string, unknown> | null;
  control?: Record<string, unknown> | null;
  supply?: Record<string, unknown> | null;
  sourceReferences: Array<Record<string, unknown>>;
}): OmaKcc20RegulatedAuditEventV1 {
  const occurredAt = omaKcc20RegulatedAuditIso(params.occurredAt, "kcc20_regulated_audit_projection_occurred_at");
  const dedupeKey = String(params.dedupeKey || "").trim();
  const correlationId = String(params.correlationId || "").trim();
  if (!dedupeKey || !correlationId) throw new Error("kcc20_regulated_audit_projection_identity_required");
  const eventId = `projection:${omaSha256Text(omaStableJson({ dedupe_key: dedupeKey, occurred_at: occurredAt }))}`;
  return {
    schema_kind: OMA_KCC20_REGULATED_AUDIT_EVENT_SCHEMA_KIND,
    schema_version: 1,
    sequence: null,
    event_id: eventId,
    dedupe_key: dedupeKey,
    previous_event_hash: null,
    event_hash: null,
    occurred_at: occurredAt,
    recorded_at: occurredAt,
    networkId: "testnet-10",
    origin: "canonical_projection",
    historical_coverage: "partial",
    action_kind: params.actionKind,
    stage: params.stage,
    outcome: params.outcome,
    correlation_id: correlationId,
    actor: params.actor ?? null,
    asset: params.asset ?? null,
    policy: params.policy ?? null,
    transaction: params.transaction ?? null,
    decision: params.decision ?? null,
    amounts: params.amounts ?? null,
    control: params.control ?? null,
    supply: params.supply ?? null,
    source_references: params.sourceReferences,
    safety: {
      signed_transaction_json_included: false,
      signature_script_included: false,
      redeem_script_included: false,
      submit_token_included: false,
      private_key_included: false,
      signer_material_included: false
    }
  };
}

function omaKcc20RegulatedAuditOutpointTxid(value: unknown): string | null {
  const match = /^([0-9a-f]{64}):\d+$/i.exec(String(value ?? "").trim());
  return match ? match[1].toLowerCase() : null;
}

function omaKcc20RegulatedAuditTrackedAction(sourceValue: unknown): OmaKcc20RegulatedAuditActionKind | null {
  const source = String(sourceValue ?? "").trim();
  if (source === "oma_l1_deploy_submit_auto_track_v1") return "regulated_deploy";
  if (source === "oma_l1_issue_holder_submit_verified_preserve_existing_holders_v1") return "regulated_issue";
  if (source === "oma_l1_holder_transfer_submit_auto_track_v1") return "holder_transfer";
  if (source === "oma_l1_change_ownership_submit_controller_update_v1" || source === "oma_l1_change_ownership_submit_owner_recognition_anchor_v1") return "change_owner";
  if (source === "kcc20_regulated_seize_submit_auto_track_v1") return "seize";
  return null;
}

function omaKcc20RegulatedAuditReadFilters(req: express.Request): OmaKcc20RegulatedAuditFilters {
  const q = req.query as Record<string, unknown>;
  const actionText = String(q.action_kind ?? q.action ?? "").trim();
  const stageText = String(q.stage ?? "").trim();
  const outcomeText = String(q.outcome ?? "").trim();
  const asset = String(q.asset ?? "").trim().toLowerCase() || null;
  const search = String(q.search ?? "").trim().toLowerCase() || null;
  if (asset && asset.length > 160) throw new Error("kcc20_regulated_audit_filter_asset_too_long");
  if (search && search.length > 240) throw new Error("kcc20_regulated_audit_filter_search_too_long");
  if (actionText && !OMA_KCC20_REGULATED_AUDIT_ACTION_KINDS.has(actionText as OmaKcc20RegulatedAuditActionKind)) {
    throw new Error("kcc20_regulated_audit_filter_action_invalid");
  }
  if (stageText && !OMA_KCC20_REGULATED_AUDIT_STAGES.has(stageText as OmaKcc20RegulatedAuditStage)) {
    throw new Error("kcc20_regulated_audit_filter_stage_invalid");
  }
  if (outcomeText && !OMA_KCC20_REGULATED_AUDIT_OUTCOMES.has(outcomeText as OmaKcc20RegulatedAuditOutcome)) {
    throw new Error("kcc20_regulated_audit_filter_outcome_invalid");
  }

  const parseDate = (value: unknown, fieldName: string): string | null => {
    const text = String(value ?? "").trim();
    if (!text) return null;
    if (Number.isNaN(Date.parse(text))) throw new Error(`${fieldName}_invalid`);
    return new Date(text).toISOString();
  };
  const limitText = String(q.limit ?? "500").trim();
  const limit = Number(limitText);
  if (!/^\d+$/.test(limitText) || !Number.isInteger(limit) || limit < 1 || limit > OMA_KCC20_REGULATED_AUDIT_MAX_EVENTS) {
    throw new Error("kcc20_regulated_audit_filter_limit_invalid");
  }

  return {
    asset,
    action_kind: actionText ? actionText as OmaKcc20RegulatedAuditActionKind : null,
    stage: stageText ? stageText as OmaKcc20RegulatedAuditStage : null,
    outcome: outcomeText ? outcomeText as OmaKcc20RegulatedAuditOutcome : null,
    date_from: parseDate(q.date_from ?? q.dateFrom, "kcc20_regulated_audit_filter_date_from"),
    date_to: parseDate(q.date_to ?? q.dateTo, "kcc20_regulated_audit_filter_date_to"),
    search,
    limit
  };
}

function omaKcc20RegulatedAuditApplyFilters(
  events: OmaKcc20RegulatedAuditEventV1[],
  filters: OmaKcc20RegulatedAuditFilters
): OmaKcc20RegulatedAuditEventV1[] {
  const fromMs = filters.date_from ? Date.parse(filters.date_from) : null;
  const toMs = filters.date_to ? Date.parse(filters.date_to) : null;
  return events.filter((event) => {
    if (filters.action_kind && event.action_kind !== filters.action_kind) return false;
    if (filters.stage && event.stage !== filters.stage) return false;
    if (filters.outcome && event.outcome !== filters.outcome) return false;
    const occurredMs = Date.parse(event.occurred_at);
    if (fromMs !== null && occurredMs < fromMs) return false;
    if (toMs !== null && occurredMs > toMs) return false;
    if (filters.asset) {
      const assetText = omaStableJson(event.asset || {}).toLowerCase();
      if (!assetText.includes(filters.asset)) return false;
    }
    if (filters.search && !omaStableJson(event).toLowerCase().includes(filters.search)) return false;
    return true;
  }).slice(0, filters.limit);
}

function omaBuildKcc20RegulatedAuditProjection(params: {
  repoRootPath: string;
  userId: string;
  activeWallet: any;
}): OmaKcc20RegulatedAuditProjection {
  const policy = omaKcc20RegulatedDemoPolicyRead(params.repoRootPath, params.userId);
  const derivedPolicy = policy ? omaKcc20RegulatedDemoPolicyDerive(policy) : null;
  const registryStore = readOmaKcc20PolicyRegistryStore(params.repoRootPath, params.userId);
  const trackedStore = readOmaL1TrackedAssetStore(params.repoRootPath, params.userId);
  const authorizationStore = readOmaL1IssuanceAuthorizationStore(params.repoRootPath, params.userId);
  const burnStore = readOmaL1BurnReceiptStore(params.repoRootPath, params.userId);
  const journal = readOmaKcc20RegulatedAuditStore(params.repoRootPath, params.userId);

  const sourceManifest = [
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "audit_journal",
      filePath: omaKcc20RegulatedAuditPath(params.repoRootPath, params.userId),
      authoritativeRole: "append_only_audit_evidence_after_instrumentation",
      recordCount: journal.store.records.length
    }),
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "demo_policy",
      filePath: omaKcc20RegulatedDemoPolicyPath(params.repoRootPath, params.userId),
      authoritativeRole: "current_user_scoped_policy_state",
      recordCount: policy ? 1 : 0
    }),
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "policy_registries",
      filePath: omaKcc20PolicyRegistryStorePath(params.repoRootPath, params.userId),
      authoritativeRole: "current_registry_state_by_covenant_id",
      recordCount: registryStore.records.length
    }),
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "tracked_assets",
      filePath: omaL1TrackedAssetsPath(params.repoRootPath, params.userId),
      authoritativeRole: "current_and_candidate_asset_state",
      recordCount: trackedStore.records.length
    }),
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "issuance_authorizations",
      filePath: omaL1IssuanceAuthorizationsPath(params.repoRootPath, params.userId),
      authoritativeRole: "append_only_issuance_authorization_consumption",
      recordCount: authorizationStore.records.length
    }),
    omaKcc20RegulatedAuditSourceManifestRow({
      repoRootPath: params.repoRootPath,
      sourceKind: "burn_receipts",
      filePath: omaL1BurnReceiptsPath(params.repoRootPath, params.userId),
      authoritativeRole: "accepted_burn_and_controller_supply_accounting",
      recordCount: burnStore.records.length
    })
  ];

  const byDedupeKey = new Map<string, { event: OmaKcc20RegulatedAuditEventV1; priority: number }>();
  const upsert = (event: OmaKcc20RegulatedAuditEventV1, priority: number) => {
    const existing = byDedupeKey.get(event.dedupe_key);
    if (!existing || priority >= existing.priority) {
      const mergedReferences = existing
        ? [...existing.event.source_references, ...event.source_references]
          .filter((value, index, all) => all.findIndex((candidate) => omaStableJson(candidate) === omaStableJson(value)) === index)
        : event.source_references;
      byDedupeKey.set(event.dedupe_key, { event: { ...event, source_references: mergedReferences }, priority });
    }
  };

  if (policy && derivedPolicy) {
    upsert(omaKcc20RegulatedAuditProjectionEvent({
      actionKind: policy.policy_epoch === 1 ? "policy_create" : "policy_update",
      stage: "tracking_updated",
      outcome: "success",
      occurredAt: policy.updated_at,
      dedupeKey: `policy:${policy.policy_epoch}:${derivedPolicy.rulebook_root}`,
      correlationId: `policy-epoch:${policy.policy_epoch}`,
      actor: { user_id: params.userId, role: "demo_policy_owner" },
      policy: {
        policy_epoch: policy.policy_epoch,
        source_policy_snapshot_id: derivedPolicy.source_policy_snapshot_id,
        rulebook_root: derivedPolicy.rulebook_root,
        regulated_asset_covenant_ids: policy.regulated_asset_covenant_ids,
        recipient_allowlist: policy.recipient_allowlist,
        recipient_blacklist: policy.recipient_blacklist,
        frozen_holders: policy.frozen_holders,
        frozen_outpoints: policy.frozen_outpoints,
        lawful_order_actions: policy.lawful_order_actions,
        historical_diff_available: false
      },
      sourceReferences: [{ source_kind: "demo_policy", relative_path: path.relative(params.repoRootPath, omaKcc20RegulatedDemoPolicyPath(params.repoRootPath, params.userId)).replace(/\\/g, "/") }]
    }), 20);
  }

  for (const record of registryStore.records) {
    const previousRoot = String(record.state?.p || "").trim().toLowerCase();
    const actionKind: OmaKcc20RegulatedAuditActionKind = previousRoot === OMA_KCC20_POLICY_REGISTRY_ZERO_ROOT ? "registry_deploy" : "registry_update";
    const stage: OmaKcc20RegulatedAuditStage = record.record_status === "live_verified" ? "live_verified" : "submitted";
    const outcome: OmaKcc20RegulatedAuditOutcome = record.record_status === "live_verified" ? "success" : "pending";
    upsert(omaKcc20RegulatedAuditProjectionEvent({
      actionKind,
      stage,
      outcome,
      occurredAt: record.updated_at || record.created_at,
      dedupeKey: `${actionKind}:${record.submitted_txid}:${record.registry_covenant_id}`,
      correlationId: record.submitted_txid || record.registry_covenant_id,
      actor: { wallet_id: record.wallet_id, address: record.authority_address, role: "registry_authority" },
      policy: {
        registry_covenant_id: record.registry_covenant_id,
        policy_epoch: record.state.e,
        rulebook_root: record.state.r,
        previous_rulebook_root: record.state.p,
        program_hash: record.state.ph
      },
      transaction: {
        transaction_id: record.submitted_txid,
        registry_outpoint: record.source_outpoint,
        registry_address: record.registry_address,
        post_submit_scan_status: record.post_submit_scan_status
      },
      sourceReferences: [{ source_kind: "policy_registries", registry_covenant_id: record.registry_covenant_id }]
    }), 30);
  }

  const regulatedAssetIds = new Set<string>();
  for (const record of trackedStore.records) {
    let regulatedProfile: OmaL1TokenRegulatedCompactState | null = null;
    try {
      regulatedProfile = omaReadKcc20StoredRegulatedCompactState(record.regulated_profile);
    } catch (err) {
      throw new Error(`kcc20_regulated_audit_tracked_profile_invalid:${String(err instanceof Error ? err.message : err)}`);
    }
    if (!regulatedProfile) continue;
    const actionKind = omaKcc20RegulatedAuditTrackedAction(record.source);
    if (!actionKind) continue;
    const assetId = String(record.asset_covenant_id || "").trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(assetId)) throw new Error("kcc20_regulated_audit_tracked_asset_covenant_id_invalid");
    regulatedAssetIds.add(assetId);
    const selectedOutpoint = actionKind === "regulated_deploy" || actionKind === "change_owner"
      ? String(record.controller?.outpoint || "")
      : String(record.holder?.outpoint || record.controller?.outpoint || "");
    const txid = omaKcc20RegulatedAuditOutpointTxid(selectedOutpoint);
    const trackedRecordStatus = String(record.record_status || "").trim();
    const trackedRecordLiveVerified = trackedRecordStatus === "live_verified";
    const trackedRecordRequiresLiveReverification = trackedRecordStatus === "candidate_requires_live_reverification";
    const stage: OmaKcc20RegulatedAuditStage = trackedRecordLiveVerified ? "live_verified" : "tracking_updated";
    const outcome: OmaKcc20RegulatedAuditOutcome = trackedRecordLiveVerified
      ? "success"
      : trackedRecordRequiresLiveReverification
        ? "informational"
        : "pending";
    const trackedRecordPendingAction = !trackedRecordLiveVerified && !trackedRecordRequiresLiveReverification;
    const dedupeSuffix = selectedOutpoint || `${record.source}:${record.updated_at}`;
    upsert(omaKcc20RegulatedAuditProjectionEvent({
      actionKind,
      stage,
      outcome,
      occurredAt: record.updated_at || record.created_at,
      dedupeKey: `${actionKind}:${assetId}:${dedupeSuffix}`,
      correlationId: txid || omaSha256Text(`${record.source}:${assetId}:${dedupeSuffix}`),
      actor: { wallet_id: record.wallet_id, address: record.owner_identifier, role: actionKind === "change_owner" ? "controller_owner" : "token_holder_or_issuer" },
      asset: {
        asset_covenant_id: assetId,
        token_name: record.token_name,
        token_symbol: record.token_symbol,
        decimals: record.decimals,
        holder_script_profile: record.holder_script_profile || null,
        regulated_profile: regulatedProfile
      },
      transaction: {
        transaction_id: txid,
        controller_outpoint: record.controller?.outpoint || null,
        holder_outpoint: record.holder?.outpoint || null,
        tracking_record_status: trackedRecordStatus,
        tracking_source: record.source
      },
      decision: {
        pending_action: trackedRecordPendingAction,
        live_verification_required: trackedRecordRequiresLiveReverification
      },
      amounts: {
        issued_supply_raw: record.issued_supply_raw,
        holder_amount_raw: record.holder_amount_raw,
        max_supply_raw: record.max_supply_raw
      },
      policy: {
        registry_covenant_id: regulatedProfile.pr,
        policy_epoch: regulatedProfile.pe,
        control_flags: regulatedProfile.fc
      },
      sourceReferences: [{ source_kind: "tracked_assets", source: record.source, outpoint: selectedOutpoint || null }]
    }), 10);
  }

  for (const record of authorizationStore.records) {
    const assetId = String(record.target_asset_covenant_id || "").trim().toLowerCase();
    if (/^[0-9a-f]{64}$/.test(assetId)) regulatedAssetIds.add(assetId);
    upsert(omaKcc20RegulatedAuditProjectionEvent({
      actionKind: "regulated_issue",
      stage: "tracking_updated",
      outcome: "success",
      occurredAt: record.updated_at || record.submitted_at,
      dedupeKey: `regulated_issue:${record.submitted_txid}:${assetId}`,
      correlationId: record.submitted_txid,
      actor: { wallet_id: record.wallet_id, address: record.owner_identifier, role: "issuer_controller" },
      asset: { asset_covenant_id: assetId, token_standard: record.token_standard },
      policy: {
        registry_covenant_id: record.policy_registry_covenant_id || null,
        policy_epoch: record.policy_epoch || null,
        source_policy_snapshot_id: record.source_policy_snapshot_id || null,
        rulebook_root: record.rulebook_root || null,
        policy_bypass_reasons: record.policy_bypass_reasons || []
      },
      transaction: { transaction_id: record.submitted_txid, tracking_status: record.tracking_status },
      decision: {
        authorization_id: record.authorization_id,
        provider_id: record.provider_id,
        source_type: record.source_type,
        consumed: true,
        production_eligible: record.production_eligible === true
      },
      amounts: { amount_raw: record.amount_raw, recipient_address: record.recipient_address },
      sourceReferences: [{ source_kind: "issuance_authorizations", event_identity: record.event_identity }]
    }), 40);
  }

  let pendingSupplyActionCount = 0;
  for (const record of burnStore.records) {
    const assetId = String(record.asset_covenant_id || "").trim().toLowerCase();
    const forced = record.burn_authorization_kind === "kcc20_regulated_forced_burn_v1";
    const actionKind: OmaKcc20RegulatedAuditActionKind = forced ? "forced_burn" : "holder_burn";
    if (forced && /^[0-9a-f]{64}$/.test(assetId)) regulatedAssetIds.add(assetId);
    upsert(omaKcc20RegulatedAuditProjectionEvent({
      actionKind,
      stage: "live_verified",
      outcome: "success",
      occurredAt: record.submitted_at,
      dedupeKey: `${actionKind}:${record.submitted_txid}:${assetId}`,
      correlationId: record.submitted_txid,
      actor: { wallet_id: record.wallet_id, address: record.owner_identifier, role: forced ? "registry_authority" : "token_holder" },
      asset: { asset_covenant_id: assetId, token_name: record.token_name, token_symbol: record.token_symbol, decimals: record.decimals },
      policy: forced ? {
        registry_covenant_id: record.registry_covenant_id || null,
        policy_epoch: record.policy_epoch || null,
        source_policy_snapshot_id: record.source_policy_snapshot_id || null,
        rulebook_root: record.rulebook_root || null
      } : null,
      transaction: {
        transaction_id: record.submitted_txid,
        source_holder_outpoints: record.source_holder_outpoints,
        sender_change_holder_outpoint: record.sender_change_holder_outpoint,
        native_refund_outpoint: record.native_refund_outpoint,
        registry_successor_outpoint: record.registry_successor_outpoint || null
      },
      amounts: { burn_amount_raw: record.burn_amount_raw, burn_amount_human: record.burn_amount_human },
      control: forced ? {
        order_reference: record.order_reference || null,
        target_holder_address: record.target_holder_address || null,
        holder_signature_required: record.holder_signature_required === true,
        registry_authority_signature_required: record.registry_authority_signature_required === true
      } : null,
      supply: { controller_supply_update_status: record.controller_supply_update_status },
      sourceReferences: [{ source_kind: "burn_receipts", submitted_txid: record.submitted_txid }]
    }), 50);

    const supplyUpdated = String(record.controller_supply_update_status || "").startsWith("updated_after_controller_supply_submit");
    if (supplyUpdated) {
      const updateTxid = String((record as any).controller_supply_update_txid || "").trim();
      const appliedAt = String((record as any).controller_supply_update_applied_at || record.updated_at || record.submitted_at);
      upsert(omaKcc20RegulatedAuditProjectionEvent({
        actionKind: "controller_supply_update",
        stage: "tracking_updated",
        outcome: "success",
        occurredAt: appliedAt,
        dedupeKey: `controller_supply_update:${updateTxid || record.submitted_txid}:${assetId}`,
        correlationId: record.submitted_txid,
        actor: { wallet_id: record.wallet_id, address: record.owner_identifier, role: "controller_owner" },
        asset: { asset_covenant_id: assetId, token_name: record.token_name, token_symbol: record.token_symbol, decimals: record.decimals },
        transaction: {
          transaction_id: updateTxid || null,
          burn_receipt_transaction_id: record.submitted_txid,
          next_controller_outpoint: (record as any).controller_supply_update_controller_outpoint || null
        },
        supply: {
          controller_supply_update_status: record.controller_supply_update_status,
          issued_supply_after_raw: (record as any).controller_supply_update_issued_supply_after_raw || null
        },
        sourceReferences: [{ source_kind: "burn_receipts", submitted_txid: record.submitted_txid }]
      }), 50);
    } else {
      pendingSupplyActionCount += 1;
      upsert(omaKcc20RegulatedAuditProjectionEvent({
        actionKind: "controller_supply_update",
        stage: "supply_update_pending",
        outcome: "pending",
        occurredAt: record.updated_at || record.submitted_at,
        dedupeKey: `controller_supply_update_pending:${record.submitted_txid}:${assetId}`,
        correlationId: record.submitted_txid,
        actor: { wallet_id: record.wallet_id, address: record.owner_identifier, role: "controller_owner" },
        asset: { asset_covenant_id: assetId, token_name: record.token_name, token_symbol: record.token_symbol, decimals: record.decimals },
        transaction: { burn_receipt_transaction_id: record.submitted_txid },
        decision: { do_not_repeat_holder_burn: true },
        supply: { controller_supply_update_status: record.controller_supply_update_status, burn_amount_raw: record.burn_amount_raw },
        sourceReferences: [{ source_kind: "burn_receipts", submitted_txid: record.submitted_txid }]
      }), 50);
    }
  }

  for (const event of journal.store.records) upsert(event, 100);

  const rawEvents = [...byDedupeKey.values()].map((entry) => entry.event).sort((a, b) => {
    const timeDiff = Date.parse(b.occurred_at) - Date.parse(a.occurred_at);
    return timeDiff || a.event_id.localeCompare(b.event_id);
  });
  const terminalSuccessStages = new Set<OmaKcc20RegulatedAuditStage>(["live_verified", "tracking_updated"]);
  const terminalSuccessEvents = rawEvents.filter((event) => (
    event.outcome === "success" && terminalSuccessStages.has(event.stage)
  ));
  const successfulRegistryPublications = terminalSuccessEvents.filter((event) => event.action_kind === "registry_update");
  const successfulForcedBurns = terminalSuccessEvents.filter((event) => event.action_kind === "forced_burn");
  const successfulControllerSupplyUpdates = terminalSuccessEvents.filter((event) => event.action_kind === "controller_supply_update");

  const burnReceiptTxidForEvent = (event: OmaKcc20RegulatedAuditEventV1): string => {
    const receiptTxids = Array.isArray((event.supply as any)?.burn_receipt_submitted_txids)
      ? (event.supply as any).burn_receipt_submitted_txids.map((value: unknown) => String(value || "").trim().toLowerCase())
      : [];
    return String(
      (event.transaction as any)?.burn_receipt_transaction_id
      || (event.transaction as any)?.transaction_id
      || receiptTxids[0]
      || event.correlation_id
      || ""
    ).trim().toLowerCase();
  };

  const controllerSupplyUpdateForBurnReceipt = (burnReceiptTxid: string): OmaKcc20RegulatedAuditEventV1 | null => {
    if (!burnReceiptTxid) return null;
    return successfulControllerSupplyUpdates.find((candidate) => {
      const completedReceiptTxids = Array.isArray((candidate.supply as any)?.burn_receipt_submitted_txids)
        ? (candidate.supply as any).burn_receipt_submitted_txids.map((value: unknown) => String(value || "").trim().toLowerCase())
        : [];
      return String((candidate.transaction as any)?.burn_receipt_transaction_id || "").trim().toLowerCase() === burnReceiptTxid
        || completedReceiptTxids.includes(burnReceiptTxid)
        || candidate.correlation_id.trim().toLowerCase() === burnReceiptTxid;
    }) || null;
  };

  type OmaKcc20RegulatedAuditLifecycleResolution = {
    terminal: OmaKcc20RegulatedAuditEventV1;
    supporting: OmaKcc20RegulatedAuditEventV1[];
  };

  const lifecycleResolution = (event: OmaKcc20RegulatedAuditEventV1): OmaKcc20RegulatedAuditLifecycleResolution | null => {
    if (event.origin !== "audit_journal" || event.outcome !== "pending") return null;

    if (event.action_kind === "registry_update" && event.stage === "submitted") {
      const terminal = successfulRegistryPublications.find((candidate) => candidate.correlation_id === event.correlation_id) || null;
      return terminal ? { terminal, supporting: [] } : null;
    }

    if (
      event.stage === "planned"
      && ["freeze_holder", "unfreeze_holder", "freeze_outpoint", "unfreeze_outpoint"].includes(event.action_kind)
    ) {
      const policyEpoch = String((event.policy as any)?.policy_epoch ?? "").trim();
      const rulebookRoot = String((event.policy as any)?.rulebook_root || "").trim().toLowerCase();
      if (!policyEpoch || !rulebookRoot) return null;
      const terminal = successfulRegistryPublications.find((candidate) => (
        String((candidate.policy as any)?.policy_epoch ?? "").trim() === policyEpoch
        && String((candidate.policy as any)?.rulebook_root || "").trim().toLowerCase() === rulebookRoot
      )) || null;
      return terminal ? { terminal, supporting: [] } : null;
    }

    if (event.action_kind === "forced_burn" && event.stage === "accepted") {
      const burnReceiptTxid = burnReceiptTxidForEvent(event);
      if (!burnReceiptTxid) return null;
      const forcedBurnTerminal = successfulForcedBurns.find((candidate) => (
        String((candidate.transaction as any)?.transaction_id || "").trim().toLowerCase() === burnReceiptTxid
        || candidate.correlation_id.trim().toLowerCase() === burnReceiptTxid
      )) || null;
      const controllerSupplyTerminal = controllerSupplyUpdateForBurnReceipt(burnReceiptTxid);
      return forcedBurnTerminal && controllerSupplyTerminal
        ? { terminal: controllerSupplyTerminal, supporting: [forcedBurnTerminal] }
        : null;
    }

    if (event.action_kind === "forced_burn" && event.stage === "supply_update_pending") {
      const burnReceiptTxid = burnReceiptTxidForEvent(event);
      const terminal = controllerSupplyUpdateForBurnReceipt(burnReceiptTxid);
      return terminal ? { terminal, supporting: [] } : null;
    }

    return null;
  };

  const events = rawEvents.map((event) => {
    const resolution = lifecycleResolution(event);
    if (!resolution) return event;
    return {
      ...event,
      outcome: "informational" as OmaKcc20RegulatedAuditOutcome,
      decision: {
        ...(event.decision || {}),
        pending_action: false,
        lifecycle_resolution: "superseded_by_success",
        resolved_by_event_id: resolution.terminal.event_id,
        resolved_by_stage: resolution.terminal.stage,
        ...(resolution.supporting.length > 0 ? {
          resolved_by_supporting_event_ids: resolution.supporting.map((candidate) => candidate.event_id),
          resolved_by_supporting_stages: resolution.supporting.map((candidate) => candidate.stage)
        } : {})
      }
    };
  });

  const countBy = (selector: (event: OmaKcc20RegulatedAuditEventV1) => string): Record<string, number> => {
    const counts = new Map<string, number>();
    for (const event of events) counts.set(selector(event), (counts.get(selector(event)) || 0) + 1);
    return Object.fromEntries([...counts.entries()].sort((a, b) => a[0].localeCompare(b[0])));
  };

  const activeRegistryIds = registryStore.records.map((record) => record.registry_covenant_id).sort();
  const currentPolicyContext = policy && derivedPolicy ? {
    policy_epoch: policy.policy_epoch,
    source_policy_snapshot_id: derivedPolicy.source_policy_snapshot_id,
    rulebook_root: derivedPolicy.rulebook_root,
    updated_at: policy.updated_at,
    regulated_asset_count: policy.regulated_asset_covenant_ids.length,
    allowlist_count: policy.recipient_allowlist.length,
    blacklist_count: policy.recipient_blacklist.length,
    frozen_holder_count: policy.frozen_holders.length,
    frozen_outpoint_count: policy.frozen_outpoints.length
  } : null;

  return {
    coverage: {
      status: "partial",
      historical_projection_available: true,
      historical_projection_limitations: [
        "earlier_policy_epochs_and_diffs_may_have_been_overwritten",
        "earlier_registry_states_may_have_been_replaced_by_current_registry_records",
        "earlier_consumed_holder_records_may_have_been_removed",
        "pre_audit_build_rejections_and_submit_rejections_were_not_persisted"
      ],
      audit_journal_present: journal.present,
      instrumented_route_coverage: journal.present ? "policy_and_registry_hooks_installed" : "not_initialized"
    },
    integrity: {
      ok: true,
      audit_journal_status: journal.present ? "present_and_chain_verified" : "not_initialized",
      audit_journal_chain_verified: journal.chain_verified,
      audit_journal_event_count: journal.store.records.length,
      audit_journal_head_event_hash: journal.head_event_hash,
      source_manifest_complete: sourceManifest.every((row) => row.source_kind === "audit_journal" || row.exists)
    },
    current_context: {
      policy_source_mode: "Testnet-10 Local Demo Policy",
      demo_only: true,
      production_eligible: false,
      legal_validity_claimed: false,
      user_id: params.userId,
      active_wallet: {
        wallet_id: String(params.activeWallet?.id || ""),
        address: String(params.activeWallet?.address0 || ""),
        network: String(params.activeWallet?.network || "")
      },
      current_policy: currentPolicyContext,
      registry_covenant_ids: activeRegistryIds,
      pending_controller_supply_action_count: pendingSupplyActionCount
    },
    summary: {
      total_events: events.length,
      live_verified: events.filter((event) => event.stage === "live_verified").length,
      rejected: events.filter((event) => event.outcome === "rejected").length,
      pending: events.filter((event) => event.outcome === "pending").length,
      pending_supply_actions: pendingSupplyActionCount,
      regulated_assets: regulatedAssetIds.size,
      current_policy_epoch: policy?.policy_epoch || null,
      by_action_kind: countBy((event) => event.action_kind),
      by_stage: countBy((event) => event.stage),
      by_outcome: countBy((event) => event.outcome),
      by_origin: countBy((event) => event.origin)
    },
    events,
    available_filters: {
      action_kinds: [...new Set(events.map((event) => event.action_kind))].sort(),
      stages: [...new Set(events.map((event) => event.stage))].sort(),
      outcomes: [...new Set(events.map((event) => event.outcome))].sort(),
      assets: [...regulatedAssetIds].sort(),
      maximum_events_per_response: OMA_KCC20_REGULATED_AUDIT_MAX_EVENTS
    },
    source_manifest: sourceManifest
  };
}

