    if (!omaL1EnvelopeRedeemScriptPushable(expected.controller)) return res.status(409).json({ ...omaL1EnvelopeOversizeProof("oma_l1_change_ownership_source_controller_redeem_script_exceeds_p2sh_push_limit", { source_controller_state_envelope: expected.controller }), change_owner_build_kind: "oma_l1_change_ownership_build_v1", source_controller_outpoint: String(verified.record.controller?.outpoint || "") || null, asset_covenant_id: assetCovenantId });

