    const standardNextControllerFields = omaBuildL1TokenControllerEnvelopeFields({ role: "controller", tokenName, tokenSymbol, decimals, maxSupplyRaw, issuedSupplyRaw, holderAmountRaw: 0n, ownerIdentifier: newOwnerAddress, issuerIdentifier: newOwnerAddress, transferRule, policyHash }, OMA_L1_TOKEN_CONTROLLER_COMPACT_STATE_SCHEMA);
    const standardOwnerRecognitionHolderFields = omaBuildL1TokenEnvelopeFields({ role: "holder", tokenName, tokenSymbol, decimals, maxSupplyRaw, issuedSupplyRaw, holderAmountRaw: 0n, ownerIdentifier: newOwnerAddress, issuerIdentifier: newOwnerAddress, transferRule, policyHash });
    let nextControllerFields = standardNextControllerFields;
    let ownerRecognitionHolderFields = standardOwnerRecognitionHolderFields;
