    const ownerRecognitionHolderEnvelope = omaBuildStateEnvelopeScriptPublicKey({ role: "holder", ownerXOnlyPublicKey: newOwnerPublicKeyHex, fields: ownerRecognitionHolderFields });
    if (!nextControllerEnvelope.decode_round_trip_ok || !nextControllerEnvelope.script_contains_state_envelope || !ownerRecognitionHolderEnvelope.decode_round_trip_ok || !ownerRecognitionHolderEnvelope.script_contains_state_envelope) return res.status(409).json({ ok: false, reason: "oma_l1_change_ownership_state_envelope_not_buildable", next_controller_state_envelope: omaL1EnvelopeProofPublic(nextControllerEnvelope), owner_recognition_holder_state_envelope: omaL1EnvelopeProofPublic(ownerRecognitionHolderEnvelope), signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    if (!omaL1EnvelopeRedeemScriptPushable(nextControllerEnvelope) || !omaL1EnvelopeRedeemScriptPushable(ownerRecognitionHolderEnvelope)) return res.status(409).json({ ...omaL1EnvelopeOversizeProof("oma_l1_change_ownership_state_envelope_exceeds_p2sh_push_limit", { next_controller_state_envelope: nextControllerEnvelope, owner_recognition_holder_state_envelope: ownerRecognitionHolderEnvelope }), change_owner_build_kind: "oma_l1_change_ownership_build_v1" });

    rpc = createCovenantControlsBuildRpcClient(networkId);
