    if (serverInfo.networkId !== networkId || serverInfo.hasUtxoIndex !== true || serverInfo.isSynced !== true || syncStatus.isSynced !== true) return res.status(409).json({ ok: false, reason: "oma_l1_change_ownership_node_not_ready", networkId, serverInfo, syncStatus, signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });

