    const tx = resolvedSupplyBuild.tx;
    const nativeFundingInputs = resolvedSupplyBuild.nativeFundingInputs as OmaL1BurnControllerSupplyFundingInputCacheEntry[];
    const nativeFundingAmountSompi = resolvedSupplyBuild.nativeFundingAmountSompi as bigint;
    const nativeRefundSompi = resolvedSupplyBuild.nativeRefundSompi as bigint;
    const massBeforeUpdate = resolvedSupplyBuild.massBeforeUpdate;
