    const candidateRecords = assetRecords.filter((record: any) => String(record?.owner_identifier || "").trim().toLowerCase() === targetHolderAddress);
    if (candidateRecords.length === 0) return res.status(404).json({ ok: false, reason: "kcc20_regulated_forced_burn_target_holder_records_not_found", signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });

