      if (!recordHolderOutpoint || seenHolderOutpoints.has(recordHolderOutpoint)) continue;
      seenHolderOutpoints.add(recordHolderOutpoint);
      const verification = await verifyOmaL1TrackedAssetRecordLive({ rpc: verifyRpc, record, activeWallet: { address0: targetHolderAddress }, networkId, siblingRecords: assetRecords });
