      if (String(verification.record.issuer_identifier || "").trim() !== active.address0) {
        rejectedCandidates.push({ holder_outpoint: verification.record.holder?.outpoint || null, reason: "kcc20_regulated_forced_burn_token_controller_wallet_required" });
        continue;
      }
      const amountRaw = omaReadNonnegativeRawInteger(verification.record.holder_amount_raw, "holder_amount_raw");
      if (amountRaw <= 0n) continue;
      verifiedCandidates.push({
        verification,
        regulatedProfile,
        amount_raw: amountRaw,
        holder_outpoint: String(verification.record.holder?.outpoint || "").trim(),
        holder_address: String(verification.record.holder?.address || "").trim(),
        owner_identifier: targetHolderAddress
      });
