    if (verifiedCandidates.some((candidate) => candidate.regulatedProfile.rg !== baseProfile.rg || candidate.regulatedProfile.rv !== baseProfile.rv || candidate.regulatedProfile.pr !== baseProfile.pr || candidate.regulatedProfile.fc !== baseProfile.fc)) {
      throw new Error("kcc20_regulated_forced_burn_holder_profile_mismatch");
    }
    const registryRecord = omaKcc20PolicyRegistryRecord(repoRoot, userId, baseProfile.pr);
