    if (registryRecord.authority_address !== active.address0 || registryRecord.wallet_id !== active.id) throw new Error("kcc20_policy_registry_authority_wallet_required");

    const sortedCandidatesAscending = [...verifiedCandidates].sort((a, b) => a.amount_raw < b.amount_raw ? -1 : a.amount_raw > b.amount_raw ? 1 : a.holder_outpoint.localeCompare(b.holder_outpoint));
    const covering = sortedCandidatesAscending.find((candidate) => candidate.amount_raw >= burnAmountRaw) || null;
    const selected: any[] = [];
    if (covering) selected.push(covering);
    else {
      let running = 0n;
      const aggregationCandidates = [...verifiedCandidates].sort((a, b) => a.amount_raw > b.amount_raw ? -1 : a.amount_raw < b.amount_raw ? 1 : a.holder_outpoint.localeCompare(b.holder_outpoint));
      for (const candidate of aggregationCandidates) {
        selected.push(candidate);
        running += candidate.amount_raw;
        if (running >= burnAmountRaw) break;
      }
    }
    const selectedAmountRaw = selected.reduce((total, candidate) => total + candidate.amount_raw, 0n);
    if (selectedAmountRaw < burnAmountRaw) throw new Error("kcc20_regulated_forced_burn_amount_exceeds_target_holdings");
    if (selected.some((candidate) => candidate.owner_identifier !== targetHolderAddress)) throw new Error("kcc20_regulated_forced_burn_multiple_target_owners_not_supported");
    const targetOwnerPublicKey = String(selected[0].verification.record.owner_public_key || "").trim();
    if (selected.some((candidate) => String(candidate.verification.record.owner_public_key || "").trim() !== targetOwnerPublicKey)) throw new Error("kcc20_regulated_forced_burn_target_owner_public_key_mismatch");
    const targetWallet = store.items.find((wallet: any) => String(wallet?.address0 || "").trim() === targetHolderAddress) || null;
