    const transferRule = omaSafeOptionalText(firstRecord.transfer_rule, 80) || "owner_signature_required";
    const policyHash = omaSafeOptionalText(firstRecord.policy_hash, 128);
    const targetPublicKey = new PublicKey(targetOwnerPublicKey);
    const remainderFields = remainderAmountRaw > 0n ? omaBuildKcc20RegulatedCompactStateFields(omaBuildL1TokenCompactHolderEnvelopeFields({ tokenSymbol, decimals, holderAmountRaw: remainderAmountRaw, ownerIdentifierType: OMA_L1_TOKEN_HOLDER_OWNER_TYPE_ADDRESS, ownerIdentifier: targetHolderAddress }), effectiveProfile) : null;
