    const matureLength = Number((context as any).matureLength || 0);
    const entries: any[] = matureLength > 0 ? (((context as any).getMatureRange(0, matureLength) || []) as any[]) : [];
    const candidates = entries.map((entry: any, index: number) => ({ reference: entry, row: covenantBuildSourceRow(entry, index), public_fields: covenantScriptPublicKeyPublicFields(entry), address: covenantAddressFromReference(entry, networkId) }));
