      source_swap_locked_holder_script_public_key_json_sha256: expectedSwapLockedScriptHash || null,
      source_swap_locked_holder_redeem_script_hex_sha256: swapLockedCompactHolder.redeem_script_hex_sha256,
      asset_covenant_id: assetCovenantId,
