    tx.inputs[0].signatureScript = "";

    if (!updateOk) {
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_immediate_recovery_release_output_amount_too_small_for_standard_mass", release_build_kind: "oma_programmable_kas_p2sh_immediate_recovery_release_build_v1", application_status: "build_blocked", network: active.network, networkId, wallet_id: active.id, wallet_type: active.wallet_type, fromAddress: active.address0, viewer_role: viewerRole, p2sh_immediate_recovery_address: policy.p2sh_immediate_recovery_address, destinationAddress: active.address0, selectedSource: { ...selected.row, outpoint_key: covenantInputOutpointKey(selected.row) }, release_amount_sompi: releaseAmountSompi.toString(), release_amount_kas: sompiTextToKasText(releaseAmountSompi.toString()), fee_reserve_sompi: feeReserveSompi.toString(), mass: { maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()), calculated_mass_before_update: covenantPrintable(massBeforeUpdate), storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null }, signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    }

    if (calculatedFee === undefined) throw new Error("programmable_kas_p2sh_immediate_recovery_release_calculateTransactionFee_returned_undefined");
