    const signedOutput0Address = covenantOutputAddress(signedTx.outputs[0], networkId);
    if (signedOutput0Address !== cached.destinationAddress) return res.status(409).json({ ok: false, reason: "signed_programmable_kas_p2sh_owner_release_delayed_recovery_recovery_release_output_address_mismatch", expected_destination_address: cached.destinationAddress, signed_output0_address: signedOutput0Address, broadcasting_enabled: false, minting_enabled: false });

    const massAfterSign = calculateTransactionMass(networkId, signedTx, 1);
    if (massAfterSign > maximumStandardTransactionMass()) return res.status(409).json({ ok: false, reason: "signed_programmable_kas_p2sh_owner_release_delayed_recovery_recovery_release_mass_exceeds_standard_limit", maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()), mass_after_sign: covenantPrintable(massAfterSign), broadcasting_enabled: false, minting_enabled: false });

