    const submitIntent = String((body as any).submit_intent || (body as any).submitIntent || "").trim();
    const signedSafeJson = String((body as any).signed_safe_json || (body as any).signedSafeJson || "").trim();
    const claimedSignedSafeJsonSha256 = String((body as any).signed_safe_json_sha256 || (body as any).signedSafeJsonSha256 || "").trim();

