    const sourceRows: CovenantControlsBuildSourceRow[] = entries.map((entry: any, index: number) => covenantBuildSourceRow(entry, index));
    const selected = selectCovenantControlsReleaseSource(entries, sourceOutpointKey, expectedCovenantId);

