app.post("/api/covenants/programmable-kas/p2sh-owner-release/submit", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet", broadcasting_enabled: false, minting_enabled: false });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const submitIntent = String((body as any).submit_intent || (body as any).submitIntent || "").trim();
    if (submitIntent !== "submit_programmable_kas_p2sh_owner_release_v1") {
      return res.status(400).json({
        ok: false,
        reason: "submit_intent_required",
        expected_submit_intent: "submit_programmable_kas_p2sh_owner_release_v1",
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const submitToken = String((body as any).submit_token || (body as any).submitToken || "").trim();
    if (!submitToken) {
      return res.status(400).json({ ok: false, reason: "submit_token_required", broadcasting_enabled: false, minting_enabled: false });
    }

    const nowMs = Date.now();
    pruneExpiredCovenantControlsBuildCache(nowMs);
    const cached = programmableKasP2shOwnerReleaseBuildCache.get(submitToken) || null;
    if (!cached) {
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_build_snapshot_missing_or_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    if (cached.expires_at_ms <= nowMs) {
      programmableKasP2shOwnerReleaseBuildCache.delete(submitToken);
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_build_snapshot_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    if (cached.networkId !== networkId || cached.network !== active.network) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_submit_network_changed",
        cached_network: cached.network,
        cached_networkId: cached.networkId,
        active_network: active.network,
        active_networkId: networkId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (cached.wallet_id !== active.id || cached.fromAddress !== active.address0) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_submit_active_wallet_changed",
        cached_wallet_id: cached.wallet_id,
        active_wallet_id: active.id,
        cached_fromAddress: cached.fromAddress,
        active_fromAddress: active.address0,
        cached_owner_address: cached.owner_address,
        owner_may_differ_from_sender_for_delegated_holder: true,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_submit_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    let signedSafeJson: string;
    try {
      signedSafeJson = readSignedCovenantSafeJsonFromBody(body);
    } catch (err) {
      return res.status(400).json({ ok: false, reason: "signed_tx_safe_json_required", error: String(err), broadcasting_enabled: false, minting_enabled: false });
    }

    const signedSafeJsonSha256 = covenantSha256Text(signedSafeJson);
    const suppliedSignedHash = String((body as any).signed_safe_json_sha256 || (body as any).signedTxSafeJsonSha256 || "").trim().toLowerCase();
    if (suppliedSignedHash && suppliedSignedHash !== signedSafeJsonSha256) {
      return res.status(400).json({
        ok: false,
        reason: "signed_tx_safe_json_sha256_mismatch",
        supplied_signed_safe_json_sha256: suppliedSignedHash,
        calculated_signed_safe_json_sha256: signedSafeJsonSha256,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTx: any = Transaction.deserializeFromSafeJSON(signedSafeJson);
    const unsignedTx: any = Transaction.deserializeFromSafeJSON(cached.txToSignSafeJson);

    const cachedFundingInputs = Array.isArray((cached as any).native_kas_funding_inputs) ? ((cached as any).native_kas_funding_inputs as CovenantControlsNativeFundingInputCacheEntry[]) : [];
    if (!cachedFundingInputs.length) {
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_cached_native_funding_inputs_missing", broadcasting_enabled: false, minting_enabled: false });
    }
    const fundingInputValidation = covenantControlsValidateNativeFundingSignedInputs({
      signedTx,
      unsignedTx: unsignedTx,
      cachedFundingInputs,
      reasonPrefix: "signed_programmable_kas_p2sh_owner_release"
    });
    if (!fundingInputValidation.ok) return res.status(fundingInputValidation.status).json(fundingInputValidation.body);

    const signedOutput0CovenantId = covenantOutputCovenantId(signedTx.outputs[0]);
    const signedOutput1CovenantId = covenantOutputCovenantId(signedTx.outputs[1]);
    if (signedOutput0CovenantId !== cached.covenant_id || signedOutput1CovenantId) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_output_covenant_mismatch",
        expected_covenant_id: cached.covenant_id,
        signed_output0_covenant_id: signedOutput0CovenantId,
        signed_output1_covenant_id: signedOutput1CovenantId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0Value = covenantOutputValueSompi(signedTx.outputs[0]);
    const signedOutput1Value = covenantOutputValueSompi(signedTx.outputs[1]);
    if (signedOutput0Value !== cached.amount_sompi || signedOutput1Value !== cached.change_sompi) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_output_amount_mismatch",
        expected_output0_sompi: cached.amount_sompi,
        signed_output0_sompi: signedOutput0Value,
        expected_output1_sompi: cached.change_sompi,
        signed_output1_sompi: signedOutput1Value,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0Address = covenantOutputAddress(signedTx.outputs[0], networkId);
    const signedOutput1Address = covenantOutputAddress(signedTx.outputs[1], networkId);
    if (signedOutput0Address !== cached.p2sh_owner_release_address || signedOutput1Address !== cached.changeAddress) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_output_address_mismatch",
        expected_p2sh_owner_release_address: cached.p2sh_owner_release_address,
        expected_change_address: cached.changeAddress,
        signed_output0_address: signedOutput0Address,
        signed_output1_address: signedOutput1Address,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0ScriptHash = covenantOutputScriptPublicKeyJsonSha256(signedTx.outputs[0]);
    if (signedOutput0ScriptHash !== cached.p2sh_owner_release_script_public_key_json_sha256) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_script_public_key_mismatch",
        expected_script_public_key_json_sha256: cached.p2sh_owner_release_script_public_key_json_sha256,
        signed_script_public_key_json_sha256: signedOutput0ScriptHash,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const massAfterSign = calculateTransactionMass(networkId, signedTx, 1);
    if (massAfterSign > maximumStandardTransactionMass()) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_tx_mass_exceeds_max",
        mass: covenantPrintable(massAfterSign),
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTxid = signedTx.finalize().toString();
    const txJsonId = (signedTx.toJSON() as any)?.id ?? null;

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_submit_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const preSubmitResponse = await rpc.getUtxosByAddresses({ addresses: [active.address0] });
    const preSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(preSubmitResponse), networkId);
    const fundingUnspentValidation = covenantControlsValidateCachedNativeFundingUnspent({
      preSubmitRows,
      cachedFundingInputs,
      reasonPrefix: "programmable_kas_p2sh_owner_release_submit"
    });
    if (!fundingUnspentValidation.ok) return res.status(fundingUnspentValidation.status).json(fundingUnspentValidation.body);
    const selectedSourceStillUnspent = fundingUnspentValidation.rows[0] || null;

    const submitResult = await rpc.submitTransaction({ transaction: signedTx, allowOrphan: false } as any);
    const submittedTxid = submitResult && typeof (submitResult as any).transactionId === "string"
      ? String((submitResult as any).transactionId)
      : signedTxid;

    programmableKasP2shOwnerReleaseBuildCache.delete(submitToken);

    let postSubmitRows: CovenantControlsBuildSourceRow[] = [];
    let protectedOutputRow: CovenantControlsBuildSourceRow | null = null;
    let changeOutputRow: CovenantControlsBuildSourceRow | null = null;
    const postSubmitScanAddresses = Array.from(new Set([cached.p2sh_owner_release_address, cached.changeAddress, active.address0].map((address) => String(address || "").trim()).filter(Boolean)));

    for (let attempt = 1; attempt <= COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS; attempt++) {
      if (attempt > 1) await sleepMs(COVENANT_CONTROLS_POST_SUBMIT_SCAN_DELAY_MS);
      const response = await rpc.getUtxosByAddresses({ addresses: postSubmitScanAddresses });
      postSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(response), networkId);
      protectedOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:0`) || null;
      changeOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:1`) || null;
      if (protectedOutputRow && protectedOutputRow.covenant_id === cached.covenant_id && changeOutputRow && !changeOutputRow.covenant_present) break;
    }

    const postSubmitScanStatus = protectedOutputRow && protectedOutputRow.covenant_id === cached.covenant_id && changeOutputRow && !changeOutputRow.covenant_present
      ? "submitted_and_programmable_kas_p2sh_owner_release_outputs_visible"
      : "submitted_not_yet_visible";

    return res.json({
      ok: true,
      submit_kind: "oma_programmable_kas_p2sh_owner_release_submit_v1",
      application_status: "submitted_programmable_kas_p2sh_owner_release_v1",
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      owner_address: cached.owner_address,
      owner_address_source: cached.owner_address_source,
      delegated_holder_enabled: cached.owner_address_source === "provided_destination_address",
      p2sh_owner_release_delegated_holder_v1: cached.owner_address_source === "provided_destination_address",
      owner_public_key_sha256: cached.owner_public_key_sha256,
      p2sh_owner_release_address: cached.p2sh_owner_release_address,
      p2sh_owner_release_redeem_script_sha256: cached.p2sh_owner_release_redeem_script_sha256,
      p2sh_owner_release_script_public_key_json_sha256: cached.p2sh_owner_release_script_public_key_json_sha256,
      protected_output_script_form: "p2sh_owner_release_commitment",
      amount_sompi: cached.amount_sompi,
      amount_kas: sompiTextToKasText(cached.amount_sompi),
      fee_reserve_sompi: cached.fee_reserve_sompi,
      calculated_fee_sompi: cached.calculated_fee_sompi,
      change_sompi: cached.change_sompi,
      change_kas: sompiTextToKasText(cached.change_sompi),
      changeAddress: cached.changeAddress,
      selected_outpoint_key: cached.selected_outpoint_key,
      covenant_id: cached.covenant_id,
      unsigned_safe_json_sha256: cached.unsigned_safe_json_sha256,
      signed_safe_json_sha256: signedSafeJsonSha256,
      signed_txid: signedTxid,
      tx_json_id: txJsonId,
      submitted_txid: submittedTxid,
      submitted_txid_matches_signed: submittedTxid === signedTxid,
      signInputIndexes: cached.signInputIndexes,
      inputs: signedTx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)).map((input: any) => ({
        ...input,
        signatureScript_present: true,
        signatureScript_length: input.signatureScript_length
      })),
      outputs: signedTx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        mass_after_sign: covenantPrintable(massAfterSign),
        storage_mass: signedTx.storageMass !== undefined ? covenantPrintable(signedTx.storageMass) : null
      },
      pre_submit_source: {
        selected_source_still_unspent: true,
        selected_source_covenant_present: selectedSourceStillUnspent.covenant_present,
        selected_source_amount_sompi: selectedSourceStillUnspent.amount_sompi
      },
      post_submit_scan: {
        status: postSubmitScanStatus,
        attempts: COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS,
        scanned_addresses: postSubmitScanAddresses,
        protected_output: protectedOutputRow,
        change_output: changeOutputRow,
        normal_send_exclusion_expected: true
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signed_transaction_json_echoed: false,
        signature_script_echoed: false,
        submit_token_echoed: false,
        server_saved_signed_transaction: false,
        minting: "none",
        wallet_mutation: "none"
      },
      broadcasting_enabled: true,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "programmable_kas_p2sh_owner_release_submit_failed",
      error: String(err),
      signed_transaction_json_echoed: false,
      signature_script_echoed: false,
      submit_token_echoed: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // programmable KAS P2SH owner-release submit route cleanup only
    }
  }
});



app.post("/api/covenants/programmable-kas/p2sh-owner-release/release/build", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;
  let processor: InstanceType<typeof UtxoProcessor> | null = null;
  let context: InstanceType<typeof UtxoContext> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet", signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const sourceOutpointKey = String(
      (body as any).source_outpoint ||
      (body as any).sourceOutpoint ||
      (body as any).covenant_outpoint ||
      (body as any).outpoint ||
      ""
    ).trim();
    const expectedCovenantId = String((body as any).expected_covenant_id || (body as any).covenant_id || "").trim().toLowerCase();

    if (!sourceOutpointKey) {
      return res.status(400).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_source_outpoint_required", signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    }
    if (!/^[0-9a-f]{64}$/i.test(expectedCovenantId)) {
      return res.status(400).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_expected_covenant_id_required", signing_enabled: false, broadcasting_enabled: false, minting_enabled: false });
    }

    let feeReserveSompi = COVENANT_CONTROLS_P2SH_OWNER_RELEASE_DEFAULT_FEE_RESERVE_SOMPI;
    if ((body as any).fee_reserve_sompi !== undefined && (body as any).fee_reserve_sompi !== null && String((body as any).fee_reserve_sompi).trim() !== "") {
      try {
        feeReserveSompi = requirePositiveSompiInput((body as any).fee_reserve_sompi, "fee_reserve_sompi");
      } catch (err) {
        return res.status(400).json({
          ok: false,
          reason: "invalid_programmable_kas_p2sh_owner_release_release_fee_reserve",
          error: String(err),
          signing_enabled: false,
          broadcasting_enabled: false,
          minting_enabled: false
        });
      }
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    const requestedNetworkId = String((body as any).networkId || (body as any).network_id || "").trim();
    if (requestedNetworkId && requestedNetworkId !== networkId) {
      return res.status(400).json({
        ok: false,
        reason: "network_id_mismatch",
        active_wallet_network_id: networkId,
        requested_network_id: requestedNetworkId,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const ownerInspection = programmableKasP2shOwnerReleaseInspectionAddressForActiveWallet(active.address0, networkId);
    if (!ownerInspection) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_owner_public_key_not_derivable",
        active_wallet_address: active.address0,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (ownerInspection.p2sh_owner_release_redeem_script_byte_len > COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_redeem_script_exceeds_p2sh_push_limit",
        p2sh_owner_release_redeem_script_byte_len: ownerInspection.p2sh_owner_release_redeem_script_byte_len,
        p2sh_owner_release_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    processor = new UtxoProcessor({ rpc, networkId });
    await processor.start();

    const contextLabel = `oma-cc-programmable-kas-owner-release-release-${active.id}-${Date.now().toString(36)}`;
    const contextId = covenantControlsUtxoContextId(contextLabel);
    context = new UtxoContext({ processor, id: contextId });
    context.trackAddresses([ownerInspection.address]);
    await sleepMs(COVENANT_CONTROLS_UTXO_CONTEXT_SETTLE_MS);

    const matureLength = Number((context as any).matureLength || 0);
    const entries: any[] = matureLength > 0
      ? (((context as any).getMatureRange(0, matureLength) || []) as any[])
      : [];
    const sourceRows: CovenantControlsBuildSourceRow[] = entries.map((entry: any, index: number) => covenantBuildSourceRow(entry, index));
    const selected = selectCovenantControlsReleaseSource(entries, sourceOutpointKey, expectedCovenantId);

    if (!selected) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_not_found_or_not_matching",
        release_build_kind: "oma_programmable_kas_p2sh_owner_release_release_build_v1",
        application_status: "unsigned_release_build_only",
        networkId,
        p2sh_owner_release_address: ownerInspection.address,
        source_outpoint_key: sourceOutpointKey,
        expected_covenant_id: expectedCovenantId,
        utxo_source: "utxo_context_mature_references",
        utxo_context_id: contextId,
        mature_length: matureLength,
        source_rows: sourceRows,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!selected.row.amount_sompi || !/^[0-9]+$/.test(selected.row.amount_sompi)) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_amount_unreadable",
        selectedSource: selected.row,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const selectedAddress = covenantAddressFromReference(selected.reference, networkId);
    if (selectedAddress !== ownerInspection.address) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_address_mismatch",
        expected_p2sh_owner_release_address: ownerInspection.address,
        selected_source_address: selectedAddress,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const selectedPublicFields = covenantScriptPublicKeyPublicFields(selected.reference);
    if (selectedPublicFields.script_public_key_json_sha256 !== ownerInspection.p2sh_owner_release_script_public_key_json_sha256) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_script_hash_mismatch",
        expected_script_public_key_json_sha256: ownerInspection.p2sh_owner_release_script_public_key_json_sha256,
        selected_script_public_key_json_sha256: selectedPublicFields.script_public_key_json_sha256,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const selectedAmountSompi = BigInt(selected.row.amount_sompi);
    const releaseAmountSompi = selectedAmountSompi - feeReserveSompi;
    if (releaseAmountSompi <= 0n) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_amount_not_positive_after_fee_reserve",
        selected_source_amount_sompi: selected.row.amount_sompi,
        fee_reserve_sompi: feeReserveSompi.toString(),
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const destinationAddress = new Address(active.address0);
    const destinationScript = payToAddressScript(destinationAddress as any);
    const releaseOutput = new TransactionOutput(releaseAmountSompi, destinationScript as any);
    const previousOutpoint = selected.reference?.outpoint && typeof selected.reference.outpoint.toJSON === "function"
      ? selected.reference.outpoint.toJSON()
      : selected.reference?.outpoint;

    if (!previousOutpoint) {
      throw new Error("programmable_kas_p2sh_owner_release_release_source_previous_outpoint_missing");
    }

    const tx: any = new Transaction({
      version: 1,
      inputs: [
        {
          previousOutpoint,
          signatureScript: "",
          sequence: 0n,
          sigOpCount: 0,
          computeBudget: COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET,
          utxo: selected.reference
        }
      ],
      outputs: [releaseOutput],
      lockTime: 0n,
      subnetworkId: COVENANT_CONTROLS_DEFAULT_SUBNETWORK_ID,
      gas: 0n,
      payload: ""
    } as any);

    if (tx.outputs[0]?.covenant) {
      throw new Error("programmable_kas_p2sh_owner_release_release_output_unexpectedly_has_covenant");
    }

    const ownerReleaseFeeDummySignature = new Uint8Array(65);
    const ownerReleaseScript = ScriptBuilder.fromScript(ownerInspection.p2sh_owner_release_redeem_script_hex);
    const ownerReleaseDummySignatureScript = ownerReleaseScript.encodePayToScriptHashSignatureScript(ownerReleaseFeeDummySignature);
    tx.inputs[0].signatureScript = ownerReleaseDummySignatureScript;

    const massBeforeUpdate = calculateTransactionMass(networkId, tx, 1);
    const updateOk = updateTransactionMass(networkId, tx, 1);
    const calculatedFee = updateOk ? calculateTransactionFee(networkId, tx, 1) : undefined;
    tx.inputs[0].signatureScript = "";

    if (!updateOk) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_output_amount_too_small_for_standard_mass",
        release_build_kind: "oma_programmable_kas_p2sh_owner_release_release_build_v1",
        application_status: "build_blocked",
        network: active.network,
        networkId,
        wallet_id: active.id,
        wallet_type: active.wallet_type,
        fromAddress: active.address0,
        p2sh_owner_release_address: ownerInspection.address,
        destinationAddress: active.address0,
        selectedSource: {
          ...selected.row,
          outpoint_key: covenantInputOutpointKey(selected.row)
        },
        release_amount_sompi: releaseAmountSompi.toString(),
        release_amount_kas: sompiTextToKasText(releaseAmountSompi.toString()),
        fee_reserve_sompi: feeReserveSompi.toString(),
        mass: {
          maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
          calculated_mass_before_update: covenantPrintable(massBeforeUpdate),
          storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null
        },
        safety: {
          private_key_read: false,
          signing: "none",
          broadcasting: "none",
          minting: "none",
          wallet_mutation: "none"
        },
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (calculatedFee === undefined) {
      throw new Error("programmable_kas_p2sh_owner_release_release_calculateTransactionFee_returned_undefined");
    }
    const calculatedFeeSompi = BigInt(covenantPrintable(calculatedFee) || "0");
    if (calculatedFeeSompi > feeReserveSompi) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_fee_reserve_under_calculated_fee",
        networkId,
        fromAddress: active.address0,
        fee_reserve_sompi: feeReserveSompi.toString(),
        calculated_fee_sompi: calculatedFeeSompi.toString(),
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const finalizedId = tx.finalize().toString();
    const txJson = tx.toJSON();
    const txToSignSafeJson = requireTransactionSafeJson(tx);
    const unsignedSafeJsonSha256 = covenantSha256Text(txToSignSafeJson);
    const output0CovenantId = covenantOutputCovenantId(tx.outputs[0]);
    const output0Address = covenantOutputAddress(tx.outputs[0], networkId);

    if (output0CovenantId) {
      throw new Error("programmable_kas_p2sh_owner_release_release_output0_still_has_covenant");
    }
    if (output0Address !== active.address0) {
      throw new Error("programmable_kas_p2sh_owner_release_release_output0_address_mismatch");
    }

    const submitToken = covenantControlsSubmitToken();
    const submitCreatedAtMs = Date.now();
    const submitExpiresAtMs = submitCreatedAtMs + COVENANT_CONTROLS_LOWLEVEL_GENESIS_SUBMIT_TTL_MS;

    pruneExpiredCovenantControlsBuildCache(submitCreatedAtMs);
    programmableKasP2shOwnerReleaseReleaseBuildCache.set(submitToken, {
      submit_token: submitToken,
      created_at_ms: submitCreatedAtMs,
      expires_at_ms: submitExpiresAtMs,
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type || null,
      fromAddress: active.address0,
      owner_address: ownerInspection.owner_address,
      owner_public_key_sha256: ownerInspection.owner_public_key_sha256,
      p2sh_owner_release_address: ownerInspection.address,
      p2sh_owner_release_redeem_script_sha256: ownerInspection.p2sh_owner_release_redeem_script_sha256,
      p2sh_owner_release_script_public_key_json_sha256: ownerInspection.p2sh_owner_release_script_public_key_json_sha256,
      source_outpoint_key: sourceOutpointKey,
      source_covenant_id: expectedCovenantId,
      source_amount_sompi: selected.row.amount_sompi,
      source_script_public_key_json_sha256: selectedPublicFields.script_public_key_json_sha256,
      release_amount_sompi: releaseAmountSompi.toString(),
      fee_reserve_sompi: feeReserveSompi.toString(),
      calculated_fee_sompi: calculatedFeeSompi.toString(),
      destinationAddress: active.address0,
      finalized_txid: finalizedId,
      txToSignSafeJson,
      unsigned_safe_json_sha256: unsignedSafeJsonSha256,
      signInputIndexes: [0]
    });

    return res.json({
      ok: true,
      release_build_kind: "oma_programmable_kas_p2sh_owner_release_release_build_v1",
      application_status: "unsigned_release_build_only",
      proof_stage: "cc_programmable_kas_1f_release_build_only_no_submit_v1",
      release_path_status: "p2sh_owner_release_build_only_not_submitted",
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      owner_address: ownerInspection.owner_address,
      owner_public_key_sha256: ownerInspection.owner_public_key_sha256,
      p2sh_owner_release_address: ownerInspection.address,
      p2sh_owner_release_redeem_script_hex: ownerInspection.p2sh_owner_release_redeem_script_hex,
      p2sh_owner_release_redeem_script_sha256: ownerInspection.p2sh_owner_release_redeem_script_sha256,
      p2sh_owner_release_redeem_script_byte_len: ownerInspection.p2sh_owner_release_redeem_script_byte_len,
      p2sh_owner_release_redeem_script_push_limit_bytes: COVENANT_CONTROLS_P2SH_OWNER_RELEASE_REDEEM_SCRIPT_PUSH_LIMIT_BYTES,
      p2sh_owner_release_redeem_script_pushable: true,
      p2sh_owner_release_script_public_key_json_sha256: ownerInspection.p2sh_owner_release_script_public_key_json_sha256,
      destinationAddress: active.address0,
      source_outpoint_key: sourceOutpointKey,
      expected_covenant_id: expectedCovenantId,
      release_amount_sompi: releaseAmountSompi.toString(),
      release_amount_kas: sompiTextToKasText(releaseAmountSompi.toString()),
      fee_reserve_sompi: feeReserveSompi.toString(),
      calculated_fee_sompi: calculatedFeeSompi.toString(),
      utxo_source: "utxo_context_mature_references",
      utxo_context_id: contextId,
      mature_length: matureLength,
      selectedSource: {
        ...selected.row,
        outpoint_key: covenantInputOutpointKey(selected.row),
        source_address: selectedAddress,
        script_public_key_json_sha256: selectedPublicFields.script_public_key_json_sha256
      },
      release_invariant: {
        input_covenant_present: selected.row.covenant_present,
        input_covenant_id: selected.row.covenant_id,
        input_address_matches_p2sh_owner_release: selectedAddress === ownerInspection.address,
        input_script_matches_p2sh_owner_release: selectedPublicFields.script_public_key_json_sha256 === ownerInspection.p2sh_owner_release_script_public_key_json_sha256,
        output0_covenant_present: false,
        output0_covenant_id: output0CovenantId,
        output0_normal_send_expected: true,
        output0_address: output0Address
      },
      finalized_txid: finalizedId,
      tx_json_id: txJson?.id ?? null,
      txToSignSafeJson,
      unsigned_safe_json_sha256: unsignedSafeJsonSha256,
      submit_route_enabled: true,
      submit_token: submitToken,
      submit_expires_at: new Date(submitExpiresAtMs).toISOString(),
      submit_route: "/api/covenants/programmable-kas/p2sh-owner-release/release/submit",
      submit_intent_required: "submit_programmable_kas_p2sh_owner_release_release_v1",
      signInputIndexes: [0],
      release_signing_model: {
        input0: "p2sh_owner_release_input",
        rule: "owner_signature_required",
        signer: "active_wallet_private_key",
        signature_script_shape: "pay_to_script_hash_signature_script",
        redeem_script_supplied_for_browser_signing: true
      },
      inputs: tx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)),
      outputs: tx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        calculated_mass_signed_shape: covenantPrintable(massBeforeUpdate),
        storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signing: "none",
        submit_route_enabled: true,
        broadcasting: "none",
        minting: "none",
        wallet_mutation: "none",
        signed_transaction_json_echoed: false,
        signature_script_echoed: false,
        submit_token_echoed: false
      },
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "programmable_kas_p2sh_owner_release_release_build_failed",
      error: String(err),
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (context) context.clear();
    } catch {
      // programmable KAS owner-release release build route UtxoContext cleanup only
    }
    try {
      if (processor) await processor.stop();
    } catch {
      // programmable KAS owner-release release build route UtxoProcessor cleanup only
    }
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // programmable KAS owner-release release build route cleanup only
    }
  }
});


app.post("/api/covenants/programmable-kas/p2sh-owner-release/release/submit", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet", broadcasting_enabled: false, minting_enabled: false });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const submitIntent = String((body as any).submit_intent || (body as any).submitIntent || "").trim();
    if (submitIntent !== "submit_programmable_kas_p2sh_owner_release_release_v1") {
      return res.status(400).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_intent_required",
        expected_submit_intent: "submit_programmable_kas_p2sh_owner_release_release_v1",
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const submitToken = String((body as any).submit_token || (body as any).submitToken || "").trim();
    if (!submitToken) {
      return res.status(400).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_release_submit_token_required", broadcasting_enabled: false, minting_enabled: false });
    }

    const nowMs = Date.now();
    pruneExpiredCovenantControlsBuildCache(nowMs);
    const cached = programmableKasP2shOwnerReleaseReleaseBuildCache.get(submitToken) || null;
    if (!cached) {
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_release_build_snapshot_missing_or_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    if (cached.expires_at_ms <= nowMs) {
      programmableKasP2shOwnerReleaseReleaseBuildCache.delete(submitToken);
      return res.status(409).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_release_build_snapshot_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    if (cached.networkId !== networkId || cached.network !== active.network) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_network_changed",
        cached_network: cached.network,
        cached_networkId: cached.networkId,
        active_network: active.network,
        active_networkId: networkId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (cached.wallet_id !== active.id || cached.fromAddress !== active.address0 || cached.owner_address !== active.address0 || cached.destinationAddress !== active.address0) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_active_wallet_changed",
        cached_wallet_id: cached.wallet_id,
        active_wallet_id: active.id,
        cached_fromAddress: cached.fromAddress,
        active_fromAddress: active.address0,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const ownerInspection = programmableKasP2shOwnerReleaseInspectionAddressForActiveWallet(active.address0, networkId);
    if (!ownerInspection || ownerInspection.address !== cached.p2sh_owner_release_address) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_owner_address_mismatch",
        cached_p2sh_owner_release_address: cached.p2sh_owner_release_address,
        active_p2sh_owner_release_address: ownerInspection?.address ?? null,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (ownerInspection.p2sh_owner_release_redeem_script_sha256 !== cached.p2sh_owner_release_redeem_script_sha256 ||
        ownerInspection.p2sh_owner_release_script_public_key_json_sha256 !== cached.p2sh_owner_release_script_public_key_json_sha256) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_recomputed_policy_mismatch",
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    let signedSafeJson: string;
    try {
      signedSafeJson = readSignedCovenantSafeJsonFromBody(body);
    } catch (err) {
      return res.status(400).json({ ok: false, reason: "programmable_kas_p2sh_owner_release_release_signed_tx_safe_json_required", error: String(err), broadcasting_enabled: false, minting_enabled: false });
    }

    const signedSafeJsonSha256 = covenantSha256Text(signedSafeJson);
    const suppliedSignedHash = String((body as any).signed_safe_json_sha256 || (body as any).signedTxSafeJsonSha256 || "").trim().toLowerCase();
    if (suppliedSignedHash && suppliedSignedHash !== signedSafeJsonSha256) {
      return res.status(400).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_signed_safe_json_sha256_mismatch",
        supplied_signed_safe_json_sha256: suppliedSignedHash,
        calculated_signed_safe_json_sha256: signedSafeJsonSha256,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTx: any = Transaction.deserializeFromSafeJSON(signedSafeJson);
    const unsignedTx: any = Transaction.deserializeFromSafeJSON(cached.txToSignSafeJson);

    if (!Array.isArray(signedTx.inputs) || signedTx.inputs.length !== 1 || !Array.isArray(signedTx.outputs) || signedTx.outputs.length !== 1) {
      return res.status(400).json({ ok: false, reason: "signed_programmable_kas_p2sh_owner_release_release_tx_shape_invalid", broadcasting_enabled: false, minting_enabled: false });
    }
    if (!Array.isArray(unsignedTx.inputs) || unsignedTx.inputs.length !== 1 || !Array.isArray(unsignedTx.outputs) || unsignedTx.outputs.length !== 1) {
      return res.status(500).json({ ok: false, reason: "cached_unsigned_programmable_kas_p2sh_owner_release_release_tx_shape_invalid", broadcasting_enabled: false, minting_enabled: false });
    }

    const signedInput0 = signedTx.inputs[0];
    const unsignedInput0 = unsignedTx.inputs[0];
    const signedInputOutpointKey = covenantTxInputOutpointKey(signedInput0);
    const unsignedInputOutpointKey = covenantTxInputOutpointKey(unsignedInput0);
    if (!signedInputOutpointKey || signedInputOutpointKey !== cached.source_outpoint_key || unsignedInputOutpointKey !== cached.source_outpoint_key) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_input_outpoint_mismatch",
        cached_source_outpoint_key: cached.source_outpoint_key,
        signed_input_outpoint_key: signedInputOutpointKey,
        unsigned_input_outpoint_key: unsignedInputOutpointKey,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!covenantSignatureScriptIsPresentHex(signedInput0)) {
      return res.status(400).json({ ok: false, reason: "signed_programmable_kas_p2sh_owner_release_release_input_signature_script_missing_or_invalid", broadcasting_enabled: false, minting_enabled: false });
    }

    const signedComputeBudget = Number(signedInput0.computeBudget ?? 0);
    const signedSigOpCount = Number(signedInput0.sigOpCount ?? 0);
    if (signedComputeBudget !== COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET || signedSigOpCount !== 0) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_release_input_budget_mismatch",
        expected_computeBudget: COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET,
        signed_computeBudget: signedComputeBudget,
        expected_sigOpCount: 0,
        signed_sigOpCount: signedSigOpCount,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0CovenantId = covenantOutputCovenantId(signedTx.outputs[0]);
    if (signedOutput0CovenantId) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_release_output_still_has_covenant",
        signed_output0_covenant_id: signedOutput0CovenantId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0Value = covenantOutputValueSompi(signedTx.outputs[0]);
    const signedOutput0Address = covenantOutputAddress(signedTx.outputs[0], networkId);
    if (signedOutput0Value !== cached.release_amount_sompi || signedOutput0Address !== cached.destinationAddress) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_release_output_mismatch",
        expected_output0_sompi: cached.release_amount_sompi,
        signed_output0_sompi: signedOutput0Value,
        expected_output0_address: cached.destinationAddress,
        signed_output0_address: signedOutput0Address,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const massAfterSign = calculateTransactionMass(networkId, signedTx, 1);
    if (massAfterSign > maximumStandardTransactionMass()) {
      return res.status(409).json({
        ok: false,
        reason: "signed_programmable_kas_p2sh_owner_release_release_tx_mass_exceeds_max",
        mass: covenantPrintable(massAfterSign),
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTxid = signedTx.finalize().toString();
    const txJsonId = (signedTx.toJSON() as any)?.id ?? null;

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_submit_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const preSubmitResponse = await rpc.getUtxosByAddresses({ addresses: [cached.p2sh_owner_release_address] });
    const preSubmitEntries = covenantEntriesFromResponse(preSubmitResponse);
    const preSubmitRows = preSubmitEntries.map((entry: any, index: number) => covenantBuildSourceRow(entry, index));
    const sourceIndex = preSubmitRows.findIndex((row) => covenantInputOutpointKey(row) === cached.source_outpoint_key);
    const sourceBeforeRelease = sourceIndex >= 0 ? preSubmitRows[sourceIndex] : null;
    const sourceBeforeReference = sourceIndex >= 0 ? preSubmitEntries[sourceIndex] : null;

    if (!sourceBeforeRelease || !sourceBeforeReference) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_not_unspent",
        source_outpoint_key: cached.source_outpoint_key,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const sourceBeforeFields = covenantScriptPublicKeyPublicFields(sourceBeforeReference);
    const sourceCovenantId = String(sourceBeforeRelease.covenant_id || "").trim().toLowerCase();
    if (sourceBeforeRelease.covenant_present !== true ||
        sourceCovenantId !== cached.source_covenant_id ||
        sourceBeforeRelease.amount_sompi !== cached.source_amount_sompi ||
        sourceBeforeRelease.is_coinbase ||
        sourceBeforeFields.script_public_key_json_sha256 !== cached.source_script_public_key_json_sha256) {
      return res.status(409).json({
        ok: false,
        reason: "programmable_kas_p2sh_owner_release_release_source_state_mismatch",
        source_outpoint_key: cached.source_outpoint_key,
        expected_covenant_id: cached.source_covenant_id,
        source_before_release: sourceBeforeRelease,
        expected_script_public_key_json_sha256: cached.source_script_public_key_json_sha256,
        source_script_public_key_json_sha256: sourceBeforeFields.script_public_key_json_sha256,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const submitResult = await rpc.submitTransaction({ transaction: signedTx, allowOrphan: false } as any);
    const submittedTxid = submitResult && typeof (submitResult as any).transactionId === "string"
      ? String((submitResult as any).transactionId)
      : signedTxid;

    programmableKasP2shOwnerReleaseReleaseBuildCache.delete(submitToken);

    let sourceAfterRelease: CovenantControlsBuildSourceRow | null = null;
    let releaseOutputRow: CovenantControlsBuildSourceRow | null = null;
    let postSubmitRows: CovenantControlsBuildSourceRow[] = [];
    const postSubmitScanAddresses = Array.from(new Set([cached.p2sh_owner_release_address, cached.destinationAddress, active.address0].map((address) => String(address || "").trim()).filter(Boolean)));

    for (let attempt = 1; attempt <= COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS; attempt++) {
      if (attempt > 1) await sleepMs(COVENANT_CONTROLS_POST_SUBMIT_SCAN_DELAY_MS);
      const response = await rpc.getUtxosByAddresses({ addresses: postSubmitScanAddresses });
      postSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(response), networkId);
      sourceAfterRelease = postSubmitRows.find((row) => covenantInputOutpointKey(row) === cached.source_outpoint_key) || null;
      releaseOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:0`) || null;
      if (!sourceAfterRelease && releaseOutputRow && releaseOutputRow.covenant_present === false && releaseOutputRow.amount_sompi === cached.release_amount_sompi) break;
    }

    const releasedNativeVisible = !sourceAfterRelease && !!releaseOutputRow && releaseOutputRow.covenant_present === false && releaseOutputRow.amount_sompi === cached.release_amount_sompi;
    const postSubmitScanStatus = releasedNativeVisible
      ? "submitted_and_programmable_kas_p2sh_owner_release_released_to_normal_kas"
      : "submitted_programmable_kas_p2sh_owner_release_release_not_yet_visible";

    return res.json({
      ok: true,
      submit_kind: "oma_programmable_kas_p2sh_owner_release_release_submit_v1",
      application_status: "submitted_programmable_kas_p2sh_owner_release_release_v1",
      release_path_status: postSubmitScanStatus,
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      destinationAddress: cached.destinationAddress,
      owner_address: cached.owner_address,
      owner_public_key_sha256: cached.owner_public_key_sha256,
      p2sh_owner_release_address: cached.p2sh_owner_release_address,
      p2sh_owner_release_redeem_script_sha256: cached.p2sh_owner_release_redeem_script_sha256,
      p2sh_owner_release_script_public_key_json_sha256: cached.p2sh_owner_release_script_public_key_json_sha256,
      source_outpoint_key: cached.source_outpoint_key,
      expected_covenant_id: cached.source_covenant_id,
      source_amount_sompi: cached.source_amount_sompi,
      source_amount_kas: sompiTextToKasText(cached.source_amount_sompi),
      release_amount_sompi: cached.release_amount_sompi,
      release_amount_kas: sompiTextToKasText(cached.release_amount_sompi),
      fee_reserve_sompi: cached.fee_reserve_sompi,
      calculated_fee_sompi: cached.calculated_fee_sompi,
      unsigned_safe_json_sha256: cached.unsigned_safe_json_sha256,
      signed_safe_json_sha256: signedSafeJsonSha256,
      signed_txid: signedTxid,
      tx_json_id: txJsonId,
      submitted_txid: submittedTxid,
      submitted_txid_matches_signed: submittedTxid === signedTxid,
      signInputIndexes: cached.signInputIndexes,
      inputs: signedTx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)).map((input: any) => ({
        ...input,
        signatureScript_present: true,
        signatureScript_length: input.signatureScript_length
      })),
      outputs: signedTx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        mass_after_sign: covenantPrintable(massAfterSign),
        storage_mass: signedTx.storageMass !== undefined ? covenantPrintable(signedTx.storageMass) : null
      },
      pre_submit_source: {
        source_was_unspent: true,
        source_covenant_present: sourceBeforeRelease.covenant_present,
        source_covenant_id: sourceBeforeRelease.covenant_id,
        source_amount_sompi: sourceBeforeRelease.amount_sompi,
        source_script_public_key_json_sha256: sourceBeforeFields.script_public_key_json_sha256,
        normal_send_eligible_before_release: false
      },
      post_submit_scan: {
        status: postSubmitScanStatus,
        attempts: COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS,
        scanned_addresses: postSubmitScanAddresses,
        old_p2sh_owner_release_source: sourceAfterRelease,
        old_p2sh_owner_release_source_spent: !sourceAfterRelease,
        release_output: releaseOutputRow,
        release_output_native_kas: !!releaseOutputRow && releaseOutputRow.covenant_present === false,
        release_output_normal_send_expected: releasedNativeVisible,
        post_submit_rows: postSubmitRows
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signed_transaction_json_echoed: false,
        signature_script_echoed: false,
        submit_token_echoed: false,
        server_saved_signed_transaction: false,
        minting: "none",
        wallet_mutation: "none"
      },
      broadcasting_enabled: true,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "programmable_kas_p2sh_owner_release_release_submit_failed",
      error: String(err),
      signed_transaction_json_echoed: false,
      signature_script_echoed: false,
      submit_token_echoed: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // programmable KAS P2SH owner-release release submit route cleanup only
    }
  }
});


app.post("/api/covenants/lowlevel-genesis/release/build", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;
  let processor: InstanceType<typeof UtxoProcessor> | null = null;
  let context: InstanceType<typeof UtxoContext> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet" });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const sourceOutpointKey = String((body as any).covenant_outpoint || (body as any).source_outpoint || (body as any).outpoint || "").trim();
    const expectedCovenantId = String((body as any).expected_covenant_id || (body as any).covenant_id || "").trim().toLowerCase();

    if (!sourceOutpointKey) {
      return res.status(400).json({
        ok: false,
        reason: "covenant_release_source_outpoint_required",
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!/^[0-9a-f]{64}$/i.test(expectedCovenantId)) {
      return res.status(400).json({
        ok: false,
        reason: "covenant_release_expected_covenant_id_required",
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    let feeReserveSompi = COVENANT_CONTROLS_LOWLEVEL_RELEASE_DEFAULT_FEE_RESERVE_SOMPI;
    if ((body as any).fee_reserve_sompi !== undefined && (body as any).fee_reserve_sompi !== null && String((body as any).fee_reserve_sompi).trim() !== "") {
      try {
        feeReserveSompi = requirePositiveSompiInput((body as any).fee_reserve_sompi, "fee_reserve_sompi");
      } catch (err) {
        return res.status(400).json({
          ok: false,
          reason: "invalid_covenant_release_fee_reserve",
          error: String(err),
          signing_enabled: false,
          broadcasting_enabled: false,
          minting_enabled: false
        });
      }
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    const requestedNetworkId = String((body as any).networkId || (body as any).network_id || "").trim();
    if (requestedNetworkId && requestedNetworkId !== networkId) {
      return res.status(400).json({
        ok: false,
        reason: "network_id_mismatch",
        active_wallet_network_id: networkId,
        requested_network_id: requestedNetworkId,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "covenant_release_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    processor = new UtxoProcessor({ rpc, networkId });
    await processor.start();

    const contextLabel = `oma-cc-lowlevel-release-${active.id}-${Date.now().toString(36)}`;
    const contextId = covenantControlsUtxoContextId(contextLabel);
    context = new UtxoContext({ processor, id: contextId });
    context.trackAddresses([active.address0]);
    await sleepMs(COVENANT_CONTROLS_UTXO_CONTEXT_SETTLE_MS);

    const matureLength = Number((context as any).matureLength || 0);
    const entries: any[] = matureLength > 0
      ? (((context as any).getMatureRange(0, matureLength) || []) as any[])
      : [];
    const sourceRows: CovenantControlsBuildSourceRow[] = entries.map((entry: any, index: number) => covenantBuildSourceRow(entry, index));
    const selected = selectCovenantControlsReleaseSource(entries, sourceOutpointKey, expectedCovenantId);

    if (!selected) {
      const matchingOutpoint = sourceRows.find((row) => covenantInputOutpointKey(row) === sourceOutpointKey) || null;
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_not_found_or_not_matching",
        release_build_kind: "oma_covenant_controls_lowlevel_release_build_v1",
        application_status: "unsigned_release_build_only",
        networkId,
        fromAddress: active.address0,
        requested_source_outpoint_key: sourceOutpointKey,
        expected_covenant_id: expectedCovenantId,
        matching_outpoint: matchingOutpoint,
        total_utxos: sourceRows.length,
        covenant_utxos: sourceRows.filter((row: CovenantControlsBuildSourceRow) => row.covenant_present).length,
        source_rows: sourceRows,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (selected.row.is_coinbase) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_is_coinbase",
        selectedSource: selected.row,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!selected.row.amount_sompi || !/^[0-9]+$/.test(selected.row.amount_sompi)) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_amount_unreadable",
        selectedSource: selected.row,
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const selectedAmountSompi = BigInt(selected.row.amount_sompi);
    const releaseAmountSompi = selectedAmountSompi - feeReserveSompi;
    if (releaseAmountSompi <= 0n) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_amount_not_positive_after_fee_reserve",
        selected_source_amount_sompi: selected.row.amount_sompi,
        fee_reserve_sompi: feeReserveSompi.toString(),
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const destinationAddress = new Address(active.address0);
    const destinationScript = payToAddressScript(destinationAddress as any);
    const releaseOutput = new TransactionOutput(releaseAmountSompi, destinationScript as any);
    const previousOutpoint = selected.reference?.outpoint && typeof selected.reference.outpoint.toJSON === "function"
      ? selected.reference.outpoint.toJSON()
      : selected.reference?.outpoint;

    if (!previousOutpoint) {
      throw new Error("covenant_release_source_previous_outpoint_missing");
    }

    const tx: any = new Transaction({
      version: 1,
      inputs: [
        {
          previousOutpoint,
          signatureScript: "",
          sequence: 0n,
          sigOpCount: 0,
          computeBudget: COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET,
          utxo: selected.reference
        }
      ],
      outputs: [releaseOutput],
      lockTime: 0n,
      subnetworkId: COVENANT_CONTROLS_DEFAULT_SUBNETWORK_ID,
      gas: 0n,
      payload: ""
    } as any);

    if (tx.outputs[0]?.covenant) {
      throw new Error("covenant_release_output_unexpectedly_has_covenant");
    }

    const massBeforeUpdate = calculateTransactionMass(networkId, tx, 1);
    const updateOk = updateTransactionMass(networkId, tx, 1);
    if (!updateOk) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_output_amount_too_small_for_standard_mass",
        release_build_kind: "oma_covenant_controls_lowlevel_release_build_v1",
        application_status: "build_blocked",
        network: active.network,
        networkId,
        wallet_id: active.id,
        wallet_type: active.wallet_type,
        fromAddress: active.address0,
        destinationAddress: active.address0,
        selectedSource: {
          ...selected.row,
          outpoint_key: covenantInputOutpointKey(selected.row)
        },
        release_amount_sompi: releaseAmountSompi.toString(),
        release_amount_kas: sompiTextToKasText(releaseAmountSompi.toString()),
        fee_reserve_sompi: feeReserveSompi.toString(),
        mass: {
          maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
          calculated_mass_before_update: covenantPrintable(massBeforeUpdate),
          storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null
        },
        safety: {
          private_key_read: false,
          signing: "none",
          broadcasting: "none",
          minting: "none",
          wallet_mutation: "none"
        },
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const calculatedFee = calculateTransactionFee(networkId, tx, 1);
    if (calculatedFee === undefined) {
      throw new Error("covenant_release_calculateTransactionFee_returned_undefined");
    }
    const calculatedFeeSompi = BigInt(covenantPrintable(calculatedFee) || "0");
    if (calculatedFeeSompi > feeReserveSompi) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_fee_reserve_under_calculated_fee",
        networkId,
        fromAddress: active.address0,
        fee_reserve_sompi: feeReserveSompi.toString(),
        calculated_fee_sompi: calculatedFeeSompi.toString(),
        signing_enabled: false,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const finalizedId = tx.finalize().toString();
    const txJson = tx.toJSON();
    const txToSignSafeJson = requireTransactionSafeJson(tx);
    const unsignedSafeJsonSha256 = covenantSha256Text(txToSignSafeJson);
    const output0CovenantId = covenantOutputCovenantId(tx.outputs[0]);
    const output0Address = covenantOutputAddress(tx.outputs[0], networkId);

    if (output0CovenantId) {
      throw new Error("covenant_release_output0_still_has_covenant");
    }
    if (output0Address !== active.address0) {
      throw new Error("covenant_release_output0_address_mismatch");
    }

    return res.json({
      ok: true,
      release_build_kind: "oma_covenant_controls_lowlevel_release_build_v1",
      application_status: "unsigned_release_build_only",
      release_path_status: "release_build_only_not_submitted",
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      destinationAddress: active.address0,
      source_outpoint_key: sourceOutpointKey,
      expected_covenant_id: expectedCovenantId,
      release_amount_sompi: releaseAmountSompi.toString(),
      release_amount_kas: sompiTextToKasText(releaseAmountSompi.toString()),
      fee_reserve_sompi: feeReserveSompi.toString(),
      calculated_fee_sompi: calculatedFeeSompi.toString(),
      utxo_source: "utxo_context_mature_references",
      utxo_context_id: contextId,
      mature_length: matureLength,
      selectedSource: {
        ...selected.row,
        outpoint_key: covenantInputOutpointKey(selected.row)
      },
      release_invariant: {
        input_covenant_present: selected.row.covenant_present,
        input_covenant_id: selected.row.covenant_id,
        output0_covenant_present: false,
        output0_covenant_id: output0CovenantId,
        output0_normal_send_expected: true,
        output0_address: output0Address
      },
      finalized_txid: finalizedId,
      tx_json_id: txJson?.id ?? null,
      txToSignSafeJson,
      unsigned_safe_json_sha256: unsignedSafeJsonSha256,
      submit_token: null,
      submit_route: null,
      submit_intent_required: null,
      signInputIndexes: [0],
      inputs: tx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)),
      outputs: tx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        calculated_mass_before_update: covenantPrintable(massBeforeUpdate),
        storage_mass_after_update: tx.storageMass !== undefined ? covenantPrintable(tx.storageMass) : null
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signing: "none",
        broadcasting: "none",
        minting: "none",
        wallet_mutation: "none",
        submit_route_enabled: false
      },
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "covenant_lowlevel_release_build_failed",
      error: String(err),
      signing_enabled: false,
      broadcasting_enabled: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (context) context.clear();
    } catch {
      // release build route UtxoContext cleanup only
    }
    try {
      if (processor) await processor.stop();
    } catch {
      // release build route UtxoProcessor cleanup only
    }
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // release build route cleanup only
    }
  }
});


app.post("/api/covenants/lowlevel-genesis/release/submit", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet" });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const submitIntent = String((body as any).submit_intent || (body as any).submitIntent || "").trim();
    if (submitIntent !== "submit_lowlevel_genesis_release_v1") {
      return res.status(400).json({
        ok: false,
        reason: "covenant_release_submit_intent_required",
        expected_submit_intent: "submit_lowlevel_genesis_release_v1",
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const sourceOutpointKey = String(
      (body as any).covenant_outpoint ||
      (body as any).source_outpoint ||
      (body as any).sourceOutpoint ||
      (body as any).outpoint ||
      ""
    ).trim();
    const expectedCovenantId = String((body as any).expected_covenant_id || (body as any).covenant_id || "").trim().toLowerCase();

    if (!sourceOutpointKey) {
      return res.status(400).json({ ok: false, reason: "covenant_release_source_outpoint_required", broadcasting_enabled: false, minting_enabled: false });
    }
    if (!/^[0-9a-f]{64}$/i.test(expectedCovenantId)) {
      return res.status(400).json({ ok: false, reason: "covenant_release_expected_covenant_id_required", broadcasting_enabled: false, minting_enabled: false });
    }

    let feeReserveSompi = COVENANT_CONTROLS_LOWLEVEL_RELEASE_DEFAULT_FEE_RESERVE_SOMPI;
    if ((body as any).fee_reserve_sompi !== undefined && (body as any).fee_reserve_sompi !== null && String((body as any).fee_reserve_sompi).trim() !== "") {
      try {
        feeReserveSompi = requirePositiveSompiInput((body as any).fee_reserve_sompi, "fee_reserve_sompi");
      } catch (err) {
        return res.status(400).json({
          ok: false,
          reason: "invalid_covenant_release_fee_reserve",
          error: String(err),
          broadcasting_enabled: false,
          minting_enabled: false
        });
      }
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    const requestedNetworkId = String((body as any).networkId || (body as any).network_id || "").trim();
    if (requestedNetworkId && requestedNetworkId !== networkId) {
      return res.status(400).json({
        ok: false,
        reason: "network_id_mismatch",
        active_wallet_network_id: networkId,
        requested_network_id: requestedNetworkId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_submit_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    let signedSafeJson: string;
    try {
      signedSafeJson = readSignedCovenantSafeJsonFromBody(body);
    } catch (err) {
      return res.status(400).json({ ok: false, reason: "signed_tx_safe_json_required", error: String(err), broadcasting_enabled: false, minting_enabled: false });
    }

    const signedSafeJsonSha256 = covenantSha256Text(signedSafeJson);
    const suppliedSignedHash = String((body as any).signed_safe_json_sha256 || (body as any).signedTxSafeJsonSha256 || "").trim().toLowerCase();
    if (suppliedSignedHash && suppliedSignedHash !== signedSafeJsonSha256) {
      return res.status(400).json({
        ok: false,
        reason: "signed_release_safe_json_sha256_mismatch",
        supplied_signed_safe_json_sha256: suppliedSignedHash,
        calculated_signed_safe_json_sha256: signedSafeJsonSha256,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTx: any = Transaction.deserializeFromSafeJSON(signedSafeJson);
    if (!Array.isArray(signedTx.inputs) || signedTx.inputs.length !== 1 || !Array.isArray(signedTx.outputs) || signedTx.outputs.length !== 1) {
      return res.status(400).json({ ok: false, reason: "signed_covenant_release_tx_shape_invalid", broadcasting_enabled: false, minting_enabled: false });
    }

    const signedInput0 = signedTx.inputs[0];
    const signedInputOutpointKey = covenantTxInputOutpointKey(signedInput0);
    if (!signedInputOutpointKey || signedInputOutpointKey !== sourceOutpointKey) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_input_outpoint_mismatch",
        expected_source_outpoint_key: sourceOutpointKey,
        signed_input_outpoint_key: signedInputOutpointKey,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!covenantSignatureScriptIsPresentHex(signedInput0)) {
      return res.status(400).json({ ok: false, reason: "signed_covenant_release_input_signature_script_missing_or_invalid", broadcasting_enabled: false, minting_enabled: false });
    }

    const signedComputeBudget = Number(signedInput0.computeBudget ?? 0);
    const signedSigOpCount = Number(signedInput0.sigOpCount ?? 0);
    if (signedComputeBudget !== COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET || signedSigOpCount !== 0) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_input_budget_mismatch",
        expected_computeBudget: COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET,
        signed_computeBudget: signedComputeBudget,
        expected_sigOpCount: 0,
        signed_sigOpCount: signedSigOpCount,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0CovenantId = covenantOutputCovenantId(signedTx.outputs[0]);
    if (signedOutput0CovenantId) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_output_still_has_covenant",
        signed_output0_covenant_id: signedOutput0CovenantId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0Address = covenantOutputAddress(signedTx.outputs[0], networkId);
    if (signedOutput0Address !== active.address0) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_output_address_mismatch",
        expected_address: active.address0,
        signed_output0_address: signedOutput0Address,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "covenant_release_submit_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const preSubmitResponse = await rpc.getUtxosByAddresses({ addresses: [active.address0] });
    const preSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(preSubmitResponse), networkId);
    const sourceBeforeRelease = preSubmitRows.find((row) => covenantInputOutpointKey(row) === sourceOutpointKey) || null;
    if (!sourceBeforeRelease) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_not_unspent",
        source_outpoint_key: sourceOutpointKey,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const sourceCovenantId = String(sourceBeforeRelease.covenant_id || "").trim().toLowerCase();
    if (sourceBeforeRelease.covenant_present !== true || sourceCovenantId !== expectedCovenantId || sourceBeforeRelease.is_coinbase) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_state_mismatch",
        source_outpoint_key: sourceOutpointKey,
        expected_covenant_id: expectedCovenantId,
        source_before_release: sourceBeforeRelease,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (!sourceBeforeRelease.amount_sompi || !/^[0-9]+$/.test(sourceBeforeRelease.amount_sompi)) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_source_amount_unreadable",
        source_before_release: sourceBeforeRelease,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const expectedReleaseAmountSompi = BigInt(sourceBeforeRelease.amount_sompi) - feeReserveSompi;
    if (expectedReleaseAmountSompi <= 0n) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_release_expected_amount_not_positive_after_fee_reserve",
        source_amount_sompi: sourceBeforeRelease.amount_sompi,
        fee_reserve_sompi: feeReserveSompi.toString(),
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedOutput0Value = covenantOutputValueSompi(signedTx.outputs[0]);
    if (signedOutput0Value !== expectedReleaseAmountSompi.toString()) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_output_amount_mismatch",
        expected_output0_sompi: expectedReleaseAmountSompi.toString(),
        signed_output0_sompi: signedOutput0Value,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const massAfterSign = calculateTransactionMass(networkId, signedTx, 1);
    if (massAfterSign > maximumStandardTransactionMass()) {
      return res.status(409).json({
        ok: false,
        reason: "signed_covenant_release_tx_mass_exceeds_max",
        mass: covenantPrintable(massAfterSign),
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTxid = signedTx.finalize().toString();
    const txJsonId = (signedTx.toJSON() as any)?.id ?? null;
    const submitResult = await rpc.submitTransaction({ transaction: signedTx, allowOrphan: false } as any);
    const submittedTxid = submitResult && typeof (submitResult as any).transactionId === "string"
      ? String((submitResult as any).transactionId)
      : signedTxid;

    let postSubmitRows: CovenantControlsBuildSourceRow[] = [];
    let sourceAfterRelease: CovenantControlsBuildSourceRow | null = null;
    let releaseOutputRow: CovenantControlsBuildSourceRow | null = null;

    for (let attempt = 1; attempt <= COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS; attempt++) {
      if (attempt > 1) await sleepMs(COVENANT_CONTROLS_POST_SUBMIT_SCAN_DELAY_MS);
      const response = await rpc.getUtxosByAddresses({ addresses: [active.address0] });
      postSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(response), networkId);
      sourceAfterRelease = postSubmitRows.find((row) => covenantInputOutpointKey(row) === sourceOutpointKey) || null;
      releaseOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:0`) || null;
      if (!sourceAfterRelease && releaseOutputRow && releaseOutputRow.covenant_present === false && releaseOutputRow.amount_sompi === expectedReleaseAmountSompi.toString()) break;
    }

    const releasedNativeVisible = !sourceAfterRelease && !!releaseOutputRow && releaseOutputRow.covenant_present === false && releaseOutputRow.amount_sompi === expectedReleaseAmountSompi.toString();
    const postSubmitScanStatus = releasedNativeVisible
      ? "submitted_and_native_release_output_visible"
      : "submitted_release_not_yet_visible";

    const updatedProtectKasRecord = markProgrammableKasProtectKasLockRecordReleased(repoRoot, userId, sourceOutpointKey, expectedCovenantId, {
      record_status: releasedNativeVisible ? "released_live_verified" : "release_submitted_pending_visibility",
      release_status: postSubmitScanStatus,
      release_txid: submittedTxid,
      release_amount_sompi: expectedReleaseAmountSompi.toString(),
      release_amount_kas: sompiTextToKasText(expectedReleaseAmountSompi.toString()),
      released_output_outpoint: releaseOutputRow ? `${submittedTxid}:0` : null
    });

    return res.json({
      ok: true,
      submit_kind: "oma_covenant_controls_lowlevel_release_submit_v1",
      application_status: "submitted_release_testnet_or_active_wallet_network_only",
      release_path_status: postSubmitScanStatus,
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      destinationAddress: active.address0,
      source_outpoint_key: sourceOutpointKey,
      expected_covenant_id: expectedCovenantId,
      source_amount_sompi: sourceBeforeRelease.amount_sompi,
      source_amount_kas: sourceBeforeRelease.amount_kas,
      release_amount_sompi: expectedReleaseAmountSompi.toString(),
      release_amount_kas: sompiTextToKasText(expectedReleaseAmountSompi.toString()),
      fee_reserve_sompi: feeReserveSompi.toString(),
      signed_safe_json_sha256: signedSafeJsonSha256,
      signed_txid: signedTxid,
      tx_json_id: txJsonId,
      submitted_txid: submittedTxid,
      submitted_txid_matches_signed: submittedTxid === signedTxid,
      signInputIndexes: [0],
      inputs: signedTx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)).map((input: any) => ({
        ...input,
        signatureScript_present: true,
        signatureScript_length: input.signatureScript_length
      })),
      outputs: signedTx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        mass_after_sign: covenantPrintable(massAfterSign),
        storage_mass: signedTx.storageMass !== undefined ? covenantPrintable(signedTx.storageMass) : null
      },
      pre_submit_source: {
        source_was_unspent: true,
        source_covenant_present: sourceBeforeRelease.covenant_present,
        source_covenant_id: sourceBeforeRelease.covenant_id,
        source_amount_sompi: sourceBeforeRelease.amount_sompi,
        normal_send_eligible_before_release: false
      },
      post_submit_scan: {
        status: postSubmitScanStatus,
        attempts: COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS,
        old_covenant_source: sourceAfterRelease,
        old_covenant_source_spent: !sourceAfterRelease,
        release_output: releaseOutputRow,
        release_output_native_kas: !!releaseOutputRow && releaseOutputRow.covenant_present === false,
        release_output_normal_send_expected: releasedNativeVisible
      },
      tracking: updatedProtectKasRecord ? {
        store_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
        store_file: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_FILE_NAME,
        record_status: updatedProtectKasRecord.record_status,
        release_status: updatedProtectKasRecord.release_status || null,
        release_txid: updatedProtectKasRecord.release_txid || null,
        released_output_outpoint: updatedProtectKasRecord.released_output_outpoint || null
      } : {
        store_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
        store_file: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_FILE_NAME,
        record_status: "not_tracked_pre_metadata_patch",
        source_outpoint_key: sourceOutpointKey,
        covenant_id: expectedCovenantId
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signed_transaction_json_echoed: false,
        signature_script_echoed: false,
        server_saved_signed_transaction: false,
        minting: "none",
        wallet_mutation: updatedProtectKasRecord ? "protect_kas_tracking_record_updated_after_accepted_release" : "none_existing_untracked_protect_kas_source"
      },
      broadcasting_enabled: true,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "covenant_lowlevel_release_submit_failed",
      error: String(err),
      signed_transaction_json_echoed: false,
      signature_script_echoed: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // release submit route cleanup only
    }
  }
});

app.post("/api/covenants/lowlevel-genesis/submit", async (req, res) => {
  let rpc: InstanceType<typeof RpcClient> | null = null;

  try {
    await ensureKaspaReady(repoRoot);
    await ensureKaspaToccataReady(repoRoot);

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet" });
    }

    const body = req.body && typeof req.body === "object" ? req.body : {};
    const submitIntent = String((body as any).submit_intent || (body as any).submitIntent || "").trim();
    if (submitIntent !== "submit_lowlevel_genesis_covenant_v1") {
      return res.status(400).json({
        ok: false,
        reason: "covenant_submit_intent_required",
        expected_submit_intent: "submit_lowlevel_genesis_covenant_v1",
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const submitToken = String((body as any).submit_token || (body as any).submitToken || "").trim();
    if (!submitToken) {
      return res.status(400).json({ ok: false, reason: "submit_token_required", broadcasting_enabled: false, minting_enabled: false });
    }

    const nowMs = Date.now();
    pruneExpiredCovenantControlsBuildCache(nowMs);
    const cached = covenantControlsLowlevelGenesisBuildCache.get(submitToken) || null;
    if (!cached) {
      return res.status(409).json({ ok: false, reason: "covenant_build_snapshot_missing_or_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    if (cached.expires_at_ms <= nowMs) {
      covenantControlsLowlevelGenesisBuildCache.delete(submitToken);
      return res.status(409).json({ ok: false, reason: "covenant_build_snapshot_expired", broadcasting_enabled: false, minting_enabled: false });
    }

    const appNetworkKey = appNetworkKeyFromWalletNetwork(active.network);
    const networkId = rpcNetworkIdFromAppNetworkKey(appNetworkKey);
    if (cached.networkId !== networkId || cached.network !== active.network) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_submit_network_changed",
        cached_network: cached.network,
        cached_networkId: cached.networkId,
        active_network: active.network,
        active_networkId: networkId,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    if (cached.wallet_id !== active.id || cached.fromAddress !== active.address0) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_submit_active_wallet_changed",
        cached_wallet_id: cached.wallet_id,
        active_wallet_id: active.id,
        cached_fromAddress: cached.fromAddress,
        active_fromAddress: active.address0,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const templateRegistry = readCovenantTemplateRegistry();
    const registryNetworkSupport = covenantRegistryNetworkSupport(templateRegistry);
    if (!registryNetworkSupport.includes(networkId)) {
      return res.status(409).json({
        ok: false,
        reason: "covenant_submit_network_not_in_registry",
        network: active.network,
        networkId,
        registry_network_support: registryNetworkSupport,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    let signedSafeJson: string;
    try {
      signedSafeJson = readSignedCovenantSafeJsonFromBody(body);
    } catch (err) {
      return res.status(400).json({ ok: false, reason: "signed_tx_safe_json_required", error: String(err), broadcasting_enabled: false, minting_enabled: false });
    }

    const signedSafeJsonSha256 = covenantSha256Text(signedSafeJson);
    const suppliedSignedHash = String((body as any).signed_safe_json_sha256 || (body as any).signedTxSafeJsonSha256 || "").trim().toLowerCase();
    if (suppliedSignedHash && suppliedSignedHash !== signedSafeJsonSha256) {
      return res.status(400).json({
        ok: false,
        reason: "signed_tx_safe_json_sha256_mismatch",
        supplied_signed_safe_json_sha256: suppliedSignedHash,
        calculated_signed_safe_json_sha256: signedSafeJsonSha256,
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const signedTx: any = Transaction.deserializeFromSafeJSON(signedSafeJson);
    const unsignedTx: any = Transaction.deserializeFromSafeJSON(cached.txToSignSafeJson);

    const cachedFundingInputs = Array.isArray(cached.native_kas_funding_inputs) ? cached.native_kas_funding_inputs : [];
    if (!cachedFundingInputs.length) {
      return res.status(409).json({ ok: false, reason: "cached_covenant_lowlevel_genesis_native_funding_inputs_missing", broadcasting_enabled: false, minting_enabled: false });
    }
    const expectedInputCount = cachedFundingInputs.length;
    const expectedSignInputIndexes = cachedFundingInputs.map((input) => input.input_index);
    if (!Array.isArray(signedTx.inputs) || signedTx.inputs.length !== expectedInputCount || !Array.isArray(signedTx.outputs) || signedTx.outputs.length !== 2) {
      return res.status(400).json({ ok: false, reason: "signed_covenant_tx_shape_invalid", expected_input_count: expectedInputCount, broadcasting_enabled: false, minting_enabled: false });
    }

    if (!Array.isArray(unsignedTx.inputs) || unsignedTx.inputs.length !== expectedInputCount || !Array.isArray(unsignedTx.outputs) || unsignedTx.outputs.length !== 2) {
      return res.status(500).json({ ok: false, reason: "cached_unsigned_covenant_tx_shape_invalid", expected_input_count: expectedInputCount, broadcasting_enabled: false, minting_enabled: false });
    }

    if (JSON.stringify(cached.signInputIndexes || []) !== JSON.stringify(expectedSignInputIndexes)) {
      return res.status(409).json({ ok: false, reason: "cached_covenant_lowlevel_genesis_sign_indexes_mismatch", expected_sign_indexes: expectedSignInputIndexes, cached_sign_indexes: cached.signInputIndexes || [], broadcasting_enabled: false, minting_enabled: false });
    }

    for (let fundingPosition = 0; fundingPosition < cachedFundingInputs.length; fundingPosition += 1) {
      const fundingInput = cachedFundingInputs[fundingPosition];
      const inputIndex = Number(fundingInput.input_index);
      if (!Number.isInteger(inputIndex) || inputIndex < 0 || inputIndex >= expectedInputCount) {
        return res.status(409).json({ ok: false, reason: "cached_covenant_lowlevel_genesis_native_funding_input_index_invalid", native_funding_input: fundingInput, broadcasting_enabled: false, minting_enabled: false });
      }
      if (inputIndex !== fundingPosition) {
        return res.status(409).json({ ok: false, reason: "cached_covenant_lowlevel_genesis_native_funding_input_order_mismatch", native_funding_input: fundingInput, expected_input_index: fundingPosition, broadcasting_enabled: false, minting_enabled: false });
      }
      const signedInput = signedTx.inputs[inputIndex];
      const unsignedInput = unsignedTx.inputs[inputIndex];
      const signedInputOutpointKey = covenantTxInputOutpointKey(signedInput);
      const unsignedInputOutpointKey = covenantTxInputOutpointKey(unsignedInput);
      if (!fundingInput.outpoint || signedInputOutpointKey !== fundingInput.outpoint || unsignedInputOutpointKey !== fundingInput.outpoint) {
        return res.status(409).json({ ok: false, reason: "covenant_submit_input_outpoint_mismatch", native_funding_input_index: inputIndex, cached_selected_outpoint_key: fundingInput.outpoint, signed_input_outpoint_key: signedInputOutpointKey, unsigned_input_outpoint_key: unsignedInputOutpointKey, broadcasting_enabled: false, minting_enabled: false });
      }
      if (!covenantSignatureScriptIsPresentHex(signedInput)) {
        return res.status(400).json({ ok: false, reason: "signed_covenant_input_signature_script_missing_or_invalid", native_funding_input_index: inputIndex, broadcasting_enabled: false, minting_enabled: false });
      }
      const signedComputeBudget = Number(signedInput.computeBudget ?? 0);
      const signedSigOpCount = Number(signedInput.sigOpCount ?? 0);
      if (signedComputeBudget !== COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET || signedSigOpCount !== 0) {
        return res.status(409).json({ ok: false, reason: "signed_covenant_input_budget_mismatch", native_funding_input_index: inputIndex, expected_computeBudget: COVENANT_CONTROLS_LOWLEVEL_GENESIS_COMPUTE_BUDGET, signed_computeBudget: signedComputeBudget, expected_sigOpCount: 0, signed_sigOpCount: signedSigOpCount, broadcasting_enabled: false, minting_enabled: false });
      }
    }

    const signedOutput0CovenantId = covenantOutputCovenantId(signedTx.outputs[0]);
    const signedOutput1CovenantId = covenantOutputCovenantId(signedTx.outputs[1]);
    if (signedOutput0CovenantId !== cached.covenant_id || signedOutput1CovenantId) {
      return res.status(409).json({ ok: false, reason: "signed_covenant_output_shape_mismatch", expected_covenant_id: cached.covenant_id, signed_output0_covenant_id: signedOutput0CovenantId, signed_output1_covenant_id: signedOutput1CovenantId, broadcasting_enabled: false, minting_enabled: false });
    }

    const signedOutput0Value = covenantOutputValueSompi(signedTx.outputs[0]);
    const signedOutput1Value = covenantOutputValueSompi(signedTx.outputs[1]);
    if (signedOutput0Value !== cached.amount_sompi || signedOutput1Value !== cached.change_sompi) {
      return res.status(409).json({ ok: false, reason: "signed_covenant_output_amount_mismatch", expected_output0_sompi: cached.amount_sompi, signed_output0_sompi: signedOutput0Value, expected_output1_sompi: cached.change_sompi, signed_output1_sompi: signedOutput1Value, broadcasting_enabled: false, minting_enabled: false });
    }

    const signedOutput0Address = covenantOutputAddress(signedTx.outputs[0], networkId);
    const signedOutput1Address = covenantOutputAddress(signedTx.outputs[1], networkId);
    if (signedOutput0Address !== cached.destinationAddress || signedOutput1Address !== cached.changeAddress) {
      return res.status(409).json({ ok: false, reason: "signed_covenant_output_address_mismatch", expected_destination_address: cached.destinationAddress, expected_change_address: cached.changeAddress, signed_output0_address: signedOutput0Address, signed_output1_address: signedOutput1Address, broadcasting_enabled: false, minting_enabled: false });
    }

    const massAfterSign = calculateTransactionMass(networkId, signedTx, 1);
    if (massAfterSign > maximumStandardTransactionMass()) {
      return res.status(409).json({ ok: false, reason: "signed_covenant_tx_mass_exceeds_max", mass: covenantPrintable(massAfterSign), maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()), broadcasting_enabled: false, minting_enabled: false });
    }

    const signedTxid = signedTx.finalize().toString();
    const txJsonId = (signedTx.toJSON() as any)?.id ?? null;

    rpc = createCovenantControlsBuildRpcClient(networkId);
    await rpc.connect();

    const [serverInfo, syncStatus] = await Promise.all([rpc.getServerInfo(), rpc.getSyncStatus()]);
    const nodeReady =
      !!serverInfo &&
      serverInfo.networkId === networkId &&
      serverInfo.hasUtxoIndex === true &&
      serverInfo.isSynced === true &&
      !!syncStatus &&
      syncStatus.isSynced === true;

    if (!nodeReady) {
      return res.status(503).json({
        ok: false,
        reason: "covenant_submit_node_not_ready",
        networkId,
        node: {
          serverVersion: serverInfo?.serverVersion ?? null,
          networkId: serverInfo?.networkId ?? null,
          hasUtxoIndex: serverInfo?.hasUtxoIndex ?? null,
          server_is_synced: serverInfo?.isSynced ?? null,
          sync_is_synced: syncStatus?.isSynced ?? null
        },
        broadcasting_enabled: false,
        minting_enabled: false
      });
    }

    const preSubmitResponse = await rpc.getUtxosByAddresses({ addresses: [active.address0] });
    const preSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(preSubmitResponse), networkId);
    for (const fundingInput of cachedFundingInputs) {
      const selectedSourceStillUnspent = preSubmitRows.find((row) => covenantInputOutpointKey(row) === fundingInput.outpoint) || null;
      if (!selectedSourceStillUnspent) {
        return res.status(409).json({ ok: false, reason: "covenant_submit_selected_source_not_unspent", selected_outpoint_key: fundingInput.outpoint, broadcasting_enabled: false, minting_enabled: false });
      }
      if (selectedSourceStillUnspent.covenant_present || selectedSourceStillUnspent.amount_sompi !== fundingInput.amount_sompi) {
        return res.status(409).json({ ok: false, reason: "covenant_submit_selected_source_state_mismatch", selected_outpoint_key: fundingInput.outpoint, selected_source: selectedSourceStillUnspent, expected_amount_sompi: fundingInput.amount_sompi, broadcasting_enabled: false, minting_enabled: false });
      }
    }
    const selectedSourceStillUnspent = preSubmitRows.find((row) => covenantInputOutpointKey(row) === cached.selected_outpoint_key) || null;
    if (!selectedSourceStillUnspent) throw new Error("covenant_lowlevel_genesis_primary_funding_source_missing_after_validated_scan");

    const submitResult = await rpc.submitTransaction({ transaction: signedTx, allowOrphan: false } as any);
    const submittedTxid = submitResult && typeof (submitResult as any).transactionId === "string"
      ? String((submitResult as any).transactionId)
      : signedTxid;

    covenantControlsLowlevelGenesisBuildCache.delete(submitToken);

    let postSubmitRows: CovenantControlsBuildSourceRow[] = [];
    let covenantOutputRow: CovenantControlsBuildSourceRow | null = null;
    let changeOutputRow: CovenantControlsBuildSourceRow | null = null;

    const postSubmitScanAddresses = Array.from(new Set([cached.destinationAddress, cached.changeAddress].map((address) => String(address || "").trim()).filter(Boolean)));

    for (let attempt = 1; attempt <= COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS; attempt++) {
      if (attempt > 1) await sleepMs(COVENANT_CONTROLS_POST_SUBMIT_SCAN_DELAY_MS);
      const response = await rpc.getUtxosByAddresses({ addresses: postSubmitScanAddresses });
      postSubmitRows = summarizeCovenantPostSubmitRows(covenantEntriesFromResponse(response), networkId);
      covenantOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:0`) || null;
      changeOutputRow = postSubmitRows.find((row) => covenantInputOutpointKey(row) === `${submittedTxid}:1`) || null;
      if (covenantOutputRow && covenantOutputRow.covenant_id === cached.covenant_id) break;
    }

    const postSubmitScanStatus = covenantOutputRow && covenantOutputRow.covenant_id === cached.covenant_id
      ? "submitted_and_covenant_output_visible"
      : "submitted_not_yet_visible";

    const protectKasTrackedRecord: ProgrammableKasProtectKasRecord = {
      record_kind: "programmable_kas_protect_kas_record_v1",
      record_status: covenantOutputRow && covenantOutputRow.covenant_id === cached.covenant_id ? "locked_live_verified" : "submit_submitted_pending_visibility",
      tracking_source: "protect_kas_submit_auto_track_v1",
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type || null,
      creator_address: cached.fromAddress,
      from_address: cached.fromAddress,
      destination_address: cached.destinationAddress,
      destination_address_source: cached.destinationAddress === cached.fromAddress ? "active_wallet" : "provided_destination_address",
      destination_address_version: "unknown",
      change_address: cached.changeAddress,
      selected_outpoint_key: cached.selected_outpoint_key,
      selected_source_amount_sompi: cached.selected_source_amount_sompi,
      amount_sompi: cached.amount_sompi,
      amount_kas: sompiTextToKasText(cached.amount_sompi),
      fee_reserve_sompi: cached.fee_reserve_sompi,
      calculated_fee_sompi: cached.calculated_fee_sompi,
      change_sompi: cached.change_sompi,
      covenant_id: cached.covenant_id,
      source_outpoint_key: `${submittedTxid}:0`,
      submitted_txid: submittedTxid,
      post_submit_scan_status: postSubmitScanStatus,
      protected_output_visible: !!covenantOutputRow,
      normal_send_exclusion_expected: true
    };
    upsertProgrammableKasProtectKasLockRecord(repoRoot, userId, protectKasTrackedRecord);

    return res.json({
      ok: true,
      submit_kind: "oma_covenant_controls_lowlevel_genesis_submit_v1",
      application_status: "submitted_throwaway_or_active_wallet_network_only",
      network: active.network,
      networkId,
      wallet_id: active.id,
      wallet_type: active.wallet_type,
      fromAddress: active.address0,
      destinationAddress: cached.destinationAddress,
      changeAddress: cached.changeAddress,
      amount_sompi: cached.amount_sompi,
      amount_kas: sompiTextToKasText(cached.amount_sompi),
      fee_reserve_sompi: cached.fee_reserve_sompi,
      calculated_fee_sompi: cached.calculated_fee_sompi,
      change_sompi: cached.change_sompi,
      selected_outpoint_key: cached.selected_outpoint_key,
      covenant_id: cached.covenant_id,
      unsigned_safe_json_sha256: cached.unsigned_safe_json_sha256,
      signed_safe_json_sha256: signedSafeJsonSha256,
      signed_txid: signedTxid,
      tx_json_id: txJsonId,
      submitted_txid: submittedTxid,
      submitted_txid_matches_signed: submittedTxid === signedTxid,
      signInputIndexes: cached.signInputIndexes,
      inputs: signedTx.inputs.map((input: any, index: number) => covenantControlsSummarizeTxInput(input, index)).map((input: any) => ({
        ...input,
        signatureScript_present: true,
        signatureScript_length: input.signatureScript_length
      })),
      outputs: signedTx.outputs.map((output: any, index: number) => covenantControlsSummarizeTxOutput(output, index)),
      mass: {
        maximum_standard_transaction_mass: covenantPrintable(maximumStandardTransactionMass()),
        mass_after_sign: covenantPrintable(massAfterSign),
        storage_mass: signedTx.storageMass !== undefined ? covenantPrintable(signedTx.storageMass) : null
      },
      pre_submit_source: {
        selected_source_still_unspent: true,
        selected_source_covenant_present: selectedSourceStillUnspent.covenant_present,
        selected_source_amount_sompi: selectedSourceStillUnspent.amount_sompi
      },
      post_submit_scan: {
        status: postSubmitScanStatus,
        attempts: COVENANT_CONTROLS_POST_SUBMIT_SCAN_ATTEMPTS,
        scanned_addresses: postSubmitScanAddresses,
        covenant_output: covenantOutputRow,
        change_output: changeOutputRow,
        normal_send_exclusion_expected: true
      },
      tracking: {
        store_kind: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_SCHEMA_KIND,
        store_file: PROGRAMMABLE_KAS_PROTECT_KAS_LOCKS_FILE_NAME,
        tracking_source: protectKasTrackedRecord.tracking_source,
        record_status: protectKasTrackedRecord.record_status,
        source_outpoint_key: protectKasTrackedRecord.source_outpoint_key,
        covenant_id: protectKasTrackedRecord.covenant_id,
        destination_address: protectKasTrackedRecord.destination_address
      },
      node: {
        serverVersion: serverInfo.serverVersion,
        networkId: serverInfo.networkId,
        hasUtxoIndex: serverInfo.hasUtxoIndex,
        server_is_synced: serverInfo.isSynced,
        sync_is_synced: syncStatus.isSynced
      },
      template_registry: {
        registry_kind: templateRegistry.registry_kind || null,
        registry_version: templateRegistry.registry_version || null,
        registry_hash_sha256: templateRegistry.registry_hash_sha256,
        registry_network_support: registryNetworkSupport
      },
      safety: {
        private_key_read: false,
        signed_transaction_json_echoed: false,
        signature_script_echoed: false,
        server_saved_signed_transaction: false,
        minting: "none",
        wallet_mutation: "protect_kas_tracking_record_written_after_accepted_submit"
      },
      broadcasting_enabled: true,
      minting_enabled: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "covenant_lowlevel_genesis_submit_failed",
      error: String(err),
      signed_transaction_json_echoed: false,
      signature_script_echoed: false,
      minting_enabled: false
    });
  } finally {
    try {
      if (rpc) await rpc.disconnect();
    } catch {
      // submit route cleanup only
    }
  }
});

function isPositiveAmountString(s: string): boolean {
  const v = String(s || "").trim();
  if (!v) return false;
  if (!/^[0-9]+(\.[0-9]+)?$/.test(v)) return false;
  const n = Number(v);
  return Number.isFinite(n) && n > 0;
}

function extractSinglePushPayloadHexOrThrow(scriptHex: string): string {
  const s = scriptHex.trim().toLowerCase();
  const buf = Buffer.from(s, "hex");
  if (buf.length < 2) throw new Error("signature_not_single_push");
  const op = buf[0];

  let len = 0;
  let off = 0;

  if (op >= 0x01 && op <= 0x4b) {
    len = op;
    off = 1;
  } else if (op === 0x4c) {
    if (buf.length < 3) throw new Error("signature_not_single_push");
    len = buf[1];
    off = 2;
  } else if (op === 0x4d) {
    if (buf.length < 4) throw new Error("signature_not_single_push");
    len = buf[1] + (buf[2] << 8);
    off = 3;
  } else {
    throw new Error("signature_not_single_push");
  }

  if (len <= 0) throw new Error("signature_not_single_push");
  if (buf.length < off + len) throw new Error("signature_not_single_push");

  return buf.slice(off, off + len).toString("hex");
}

function normalizeOpCheckSigSignature64(sig: any, ctx: string): Uint8Array {
  const isHexEven = (s: string): boolean => s.length > 0 && s.length % 2 === 0 && /^[0-9a-fA-F]+$/.test(s);

  let bytes: Uint8Array;

  if (typeof sig === "string") {
    if (!isHexEven(sig)) throw new Error(`sig_not_hex:${ctx}`);
    bytes = Buffer.from(sig, "hex");
  } else if (sig instanceof Uint8Array) {
    bytes = sig;
  } else if (Array.isArray(sig)) {
    bytes = Uint8Array.from(sig);
  } else if (sig && typeof sig === "object" && typeof (sig as any).toString === "function") {
    const s = (sig as any).toString();
    if (typeof s !== "string" || !isHexEven(s)) throw new Error(`sig_not_hex_object:${ctx}`);
    bytes = Buffer.from(s, "hex");
  } else {
    throw new Error(`sig_bad_type:${ctx}`);
  }

  // unwrap "OP_DATA_65 + 65-byte payload" form if the SDK gave it to us
  if (bytes.length === 66 && bytes[0] === 0x41) {
    bytes = bytes.slice(1);
  }

  // If the SDK signature includes an appended sighash-type byte (65 total),
  // we must strip it here because OP_CHECKSIG expects a 64-byte Schnorr signature.
  if (bytes.length === 65) {
    bytes = bytes.slice(0, 64);
  }

  if (bytes.length === 64) return bytes;

  throw new Error(`sig_bad_len_${bytes.length}:${ctx}`);
}

function normalizeSignaturePayload65OrThrow(signatureScriptHex: string): string {
  const payload = extractSinglePushPayloadHexOrThrow(signatureScriptHex);
  if (payload.length !== 130) throw new Error("signature_payload_not_65_bytes");
  return payload;
}

function encodePushOnlyP2shSigScript(sig: Uint8Array, sighashType: number, redeemScriptHex: string): string {
  const hexOk = (s: string): boolean => s.length > 0 && s.length % 2 === 0 && /^[0-9a-fA-F]+$/.test(s);
  const rs = redeemScriptHex.trim();
  if (!hexOk(rs)) throw new Error("redeemScript_not_hex");

  const redeem = Buffer.from(rs, "hex");
  const sigBuf = Buffer.from(sig);

  const push = (b: Buffer): Buffer => {
    const n = b.length;
    if (n <= 75) return Buffer.concat([Buffer.from([n]), b]);
    if (n <= 255) return Buffer.concat([Buffer.from([76, n]), b]);
    if (n <= 65535) return Buffer.concat([Buffer.from([77, n & 0xff, (n >> 8) & 0xff]), b]);
    throw new Error("pushdata_too_large");
  };

  // WASM SDK uses an enum 0..5, while consensus SigHashType is a true bit-field byte.
  const htOrdinal = Number(sighashType);
  if (!Number.isInteger(htOrdinal) || htOrdinal < 0 || htOrdinal > 5) throw new Error("sighashType_out_of_range");

  const htByte =
    htOrdinal === 0 ? 0x01 :
    htOrdinal === 1 ? 0x02 :
    htOrdinal === 2 ? 0x04 :
    htOrdinal === 3 ? 0x81 :
    htOrdinal === 4 ? 0x82 :
    0x84;

  const sigWithHashType = Buffer.concat([sigBuf, Buffer.from([htByte])]);

  return Buffer.concat([push(sigWithHashType), push(redeem)]).toString("hex");
}

type PushDisasm = { op: number; len: number; dataHex: string };

function disasmPushOnlyScriptHex(
  scriptHex: string
): { ok: true; pushes: PushDisasm[] } | { ok: false; error: string } {
  return { ok: false, error: "diag_disabled" };
}

function diagPushOnlyScriptHex(tag: string, scriptHex: any): void {}

async function sleepMs(ms: number): Promise<void> {
  await new Promise((r) => setTimeout(r, ms));
}

// KRC-20 transfer = commit + reveal (Kasplex data insertion), using the wallet's priv0
async function krc20CommitRevealTransfer(params: {
  rpc: RpcClient;
  networkId: string;
  feeRate: number;
  fromAddress: string;
  priv0: any;
  payloadJson: string;
}): Promise<{ commitTxids: string[]; revealTxids: string[] }> {
  const { rpc, networkId, feeRate, fromAddress, priv0, payloadJson } = params;

  // Match the working reference scripts: fixed commit output of 0.3 KAS
  const commitAmountSompi = kaspaToSompi("0.3");
  if (commitAmountSompi === undefined || commitAmountSompi <= 0n) {
    throw new Error("invalid_commit_amount");
  }

  const pub = priv0.toPublicKey();
  const script = new ScriptBuilder()
    .addData(pub.toXOnlyPublicKey().toString())
    .addOp(Opcodes.OpCheckSig)
    .addOp(Opcodes.OpFalse)
    .addOp(Opcodes.OpIf)
    .addData(Buffer.from("kasplex"))
    .addI64(0n)
    .addData(Buffer.from(payloadJson))
    .addOp(Opcodes.OpEndIf);

  const p2shAddrObj = addressFromScriptPublicKey(script.createPayToScriptHashScript(), networkId);
  const p2shAddress = p2shAddrObj ? p2shAddrObj.toString() : "";
  if (!p2shAddress) {
    throw new Error("p2sh_address_failed");
  }

  // Commit: fund the P2SH output
  const ownerUtxos = await rpc.getUtxosByAddresses({ addresses: [fromAddress] });
  const ownerEntries = ownerUtxos.entries;
  if (!ownerEntries || ownerEntries.length === 0) {
    throw new Error("no_utxos");
  }

  const commitCreated = await createTransactions({
    outputs: [{ address: p2shAddress, amount: commitAmountSompi }],
    changeAddress: fromAddress,
    feeRate,
    priorityFee: { amount: 0n, source: FeeSource.SenderPays },
    entries: ownerEntries,
    networkId
  });

  const commitTxids: string[] = [];
  for (const tx of commitCreated.transactions) {
    try {
      tx.sign([priv0], true);
    } catch (e: any) {
      throw new Error(`deploy_issue_commit_sign_failed: ${String(e?.message || e)}`);
    }

    let txid: string;
    try {
      txid = await tx.submit(rpc);
    } catch (e: any) {
      throw new Error(`deploy_issue_commit_submit_failed: ${String(e?.message || e)}`);
    }

    commitTxids.push(txid);
  }

  // Reveal: wait for P2SH UTXO, then spend it with the signature script.
  const startMs = Date.now();
  const deadlineMs = startMs + 120000;

  while (Date.now() < deadlineMs) {
    let commitEntry: any = null;
    try {
      const p2sh = await rpc.getUtxosByAddresses({ addresses: [p2shAddress] });
      const list = p2sh && Array.isArray(p2sh.entries) ? p2sh.entries : [];
      if (list.length > 0) {
        const wanted = new Set(commitTxids);
        const match = list.find((e: any) => {
          const tid = e && e.outpoint ? e.outpoint.transactionId : "";
          return tid && wanted.has(tid);
        });
        commitEntry = match || null;
      }
    } catch {
      commitEntry = null;
    }

    if (!commitEntry) {
      await sleepMs(500);
      continue;
    }

    try {
      const buildReveal = async (effectiveFeeRate: number) => {
        // By-the-book: reveal is a compound tx against change (no explicit outputs).
        // IGeneratorSettingsObject docs: do not set priorityFee when outputs are missing.
        const args: any = {
          priorityEntries: [commitEntry],
          entries: [],
          changeAddress: fromAddress,
          outputs: [],
          feeRate: effectiveFeeRate,
          priorityFee: 0n,
          networkId
        };
        const created = await createTransactions(args);
        if (!created.transactions || created.transactions.length !== 1) {
          throw new Error("unexpected_reveal_batch");
        }
        return created.transactions[0];
      };

      const revealTxids: string[] = [];

      const tx0 = await buildReveal(feeRate);

      const wantedTxid = String(commitEntry?.outpoint?.transactionId || "");
      const wantedIdx = Number(commitEntry?.outpoint?.index ?? -1);

      const inputIndex0 = tx0.transaction.inputs.findIndex((input: any) => {
        const op = input && input.previousOutpoint ? input.previousOutpoint : null;
        const tid = op && typeof op.transactionId === "string" ? op.transactionId : "";
        const idx = op && typeof op.index === "number" ? op.index : -1;
        return tid === wantedTxid && idx === wantedIdx;
      });

      if (inputIndex0 === -1) {
        throw new Error("p2sh_input_not_found");
      }
      if (inputIndex0 !== 0) {
        throw new Error("p2sh_input_not_input0");
      }

      const signature0 = await tx0.createInputSignature(0, priv0);
      tx0.fillInput(0, script.encodePayToScriptHashSignatureScript(signature0));

      const requiredFee0 = calculateTransactionFee(networkId, tx0.transaction);
      if (requiredFee0 === undefined) {
        throw new Error("reveal_tx_mass_exceeds_standard");
      }

      if (tx0.feeAmount < requiredFee0) {
        // Rebuild with a higher feeRate so that the pre-sign estimate covers the post-sign mass.
        // Use fixed-point math to avoid float rounding errors.
        // Conservative bump: scale feeRate by the ratio of requiredFee/currentFee.
        // (No mass helper needed; requiredFee already accounts for the final tx size.)
        const currentFee = tx0.feeAmount > 0n ? tx0.feeAmount : 1n;
        const scale = 1000000n;
        const scaled = (requiredFee0 * scale + currentFee - 1n) / currentFee;
        const neededFeeRate = Math.max(1.0, feeRate * (Number(scaled) / 1_000_000));
        const effectiveFeeRate = Math.max(feeRate, neededFeeRate);

        const tx1 = await buildReveal(effectiveFeeRate);

        const inputIndex1 = tx1.transaction.inputs.findIndex((input: any) => {
          const op = input && input.previousOutpoint ? input.previousOutpoint : null;
          const tid = op && typeof op.transactionId === "string" ? op.transactionId : "";
          const idx = op && typeof op.index === "number" ? op.index : -1;
          return tid === wantedTxid && idx === wantedIdx;
        });

        if (inputIndex1 === -1) {
          throw new Error("p2sh_input_not_found");
        }
        if (inputIndex1 !== 0) {
          throw new Error("p2sh_input_not_input0");
        }

        const signature1 = await tx1.createInputSignature(0, priv0);
        tx1.fillInput(0, script.encodePayToScriptHashSignatureScript(signature1));

        const requiredFee1 = calculateTransactionFee(networkId, tx1.transaction);
        if (requiredFee1 === undefined) {
          throw new Error("reveal_tx_mass_exceeds_standard");
        }
        if (tx1.feeAmount < requiredFee1) {
          throw new Error("reveal_fee_under_minimum");
        }

        const txid1 = await tx1.submit(rpc);
        revealTxids.push(txid1);
      } else {
        const txid0 = await tx0.submit(rpc);
        revealTxids.push(txid0);
      }

      return { commitTxids, revealTxids };
    } catch (e: any) {
      throw e;
    }
  }

  throw new Error("reveal_timeout");
}

// Issue-Mode KRC-20 deploy: commit + reveal with configurable reveal priority fee and timeout.
// Standard wallet version (P2PKH key).
async function krc20CommitRevealIssueModeDeploy(params: {
  rpc: RpcClient;
  networkId: string;
  feeRate: number;
  fromAddress: string;
  priv0: any;
  payloadJson: string;
  revealPriorityFeeSompi: bigint;
  timeoutMs: number;
}): Promise<{ commitTxids: string[]; revealTxids: string[] }> {
  const { rpc, networkId, feeRate, fromAddress, priv0, payloadJson, revealPriorityFeeSompi, timeoutMs } = params;

  const commitAmountSompi = kaspaToSompi("0.3");
  if (commitAmountSompi === undefined || commitAmountSompi <= 0n) {
    throw new Error("invalid_commit_amount");
  }

  const pub = priv0.toPublicKey();
  const script = new ScriptBuilder()
    .addData(pub.toXOnlyPublicKey().toString())
    .addOp(Opcodes.OpCheckSig)
    .addOp(Opcodes.OpFalse)
    .addOp(Opcodes.OpIf)
    .addData(Buffer.from("kasplex"))
    .addI64(0n)
    .addData(Buffer.from(payloadJson))
    .addOp(Opcodes.OpEndIf);

  const p2shAddrObj = addressFromScriptPublicKey(script.createPayToScriptHashScript(), networkId);
  const p2shAddress = p2shAddrObj ? p2shAddrObj.toString() : "";
  if (!p2shAddress) {
    throw new Error("p2sh_address_failed");
  }

  const ownerUtxos = await rpc.getUtxosByAddresses({ addresses: [fromAddress] });
  const ownerEntries = ownerUtxos.entries;
  if (!ownerEntries || ownerEntries.length === 0) {
    throw new Error("no_utxos");
  }

  const commitCreated = await createTransactions({
    outputs: [{ address: p2shAddress, amount: commitAmountSompi }],
    changeAddress: fromAddress,
    feeRate,
    priorityFee: { amount: 0n, source: FeeSource.SenderPays },
    entries: ownerEntries,
    networkId
  });

  const commitTxids: string[] = [];
  for (const tx of commitCreated.transactions) {
    tx.sign([priv0], true);
    const txid = await tx.submit(rpc);
    commitTxids.push(txid);
  }

  const startMs = Date.now();
  const deadlineMs = startMs + Math.max(10_000, Math.min(600_000, timeoutMs));

  while (Date.now() < deadlineMs) {
    let commitEntry: any = null;
    try {
      const p2sh = await rpc.getUtxosByAddresses({ addresses: [p2shAddress] });
      const list = p2sh && Array.isArray(p2sh.entries) ? p2sh.entries : [];
      if (list.length > 0) {
        const wanted = new Set(commitTxids);
        const match = list.find((e: any) => {
          const tid = e && e.outpoint ? e.outpoint.transactionId : "";
          return tid && wanted.has(tid);
        });
        commitEntry = match || null;
      }
    } catch {
      commitEntry = null;
    }

    if (!commitEntry) {
      await sleepMs(500);
      continue;
    }

    const wantedTxid = String(commitEntry?.outpoint?.transactionId || "");
    const wantedIdx = Number(commitEntry?.outpoint?.index ?? -1);

    const buildReveal = async (effectiveFeeRate: number) => {
      const ownerUtxos2 = await rpc.getUtxosByAddresses({ addresses: [fromAddress] });
      const ownerEntries2 = ownerUtxos2.entries || [];

      const args: any = {
        priorityEntries: [commitEntry],
        entries: ownerEntries2,
        changeAddress: fromAddress,
        outputs: [],
        feeRate: effectiveFeeRate,
        priorityFee: revealPriorityFeeSompi,
        networkId
      };
      const created = await createTransactions(args);
      if (!created.transactions || created.transactions.length !== 1) {
        throw new Error("unexpected_reveal_batch");
      }
      return created.transactions[0];
    };

    const signReveal = async (ptx: any) => {
      // P2SH input is handled below (placeholder -> signature -> final script).

      const inputIndex0 = ptx.transaction.inputs.findIndex((input: any) => {
        const op = input && input.previousOutpoint ? input.previousOutpoint : null;
        const tid = op && typeof op.transactionId === "string" ? op.transactionId : "";
        const idx = op && typeof op.index === "number" ? op.index : -1;
        return tid === wantedTxid && idx === wantedIdx;
      });

      if (inputIndex0 === -1) {
        throw new Error("p2sh_input_not_found");
      }
      if (inputIndex0 !== 0) {
        throw new Error("p2sh_input_not_input0");
      }

      // Provide redeem script (P2SH) context before creating the signature.
      const dummySig = new Uint8Array(65);
      try {
        ptx.fillInput(0, script.encodePayToScriptHashSignatureScript(dummySig));
      } catch (e: any) {
        throw new Error(`deploy_issue_reveal_fill_p2sh_placeholder_failed: ${String(e?.message || e)}`);
      }

      let signature0: any;
      try {
        signature0 = await ptx.createInputSignature(0, priv0);
      } catch (e: any) {
        throw new Error(`deploy_issue_reveal_create_input_sig_failed: ${String(e?.message || e)}`);
      }

      try {
        ptx.fillInput(0, script.encodePayToScriptHashSignatureScript(signature0));
      } catch (e: any) {
        throw new Error(`deploy_issue_reveal_fill_p2sh_sigscript_failed: ${String(e?.message || e)}`);
      }

      // Sign remaining standard inputs (if any). Skip input 0 (P2SH).
      try {
        for (let i = 1; i < ptx.transaction.inputs.length; i++) {
          ptx.signInput(i, priv0);
        }
      } catch (e: any) {
        throw new Error(`deploy_issue_reveal_sign_rest_failed: ${String(e?.message || e)}`);
      }

      // Sanity: ensure every input has a signatureScript before submit.
      const ins = ptx?.transaction?.inputs || [];
      const empties: number[] = [];
      for (let i = 0; i < ins.length; i++) {
        const input: any = ins[i];
        const ss = input && input.signatureScript ? String(input.signatureScript) : "";
        if (!ss) empties.push(i);
      }
      if (empties.length) {
        throw new Error(`deploy_issue_reveal_missing_sigscript_inputs: ${empties.join(",")}`);
      }
    };

    const revealTxids: string[] = [];

    const tx0 = await buildReveal(feeRate);
    await signReveal(tx0);

    const requiredFee0 = calculateTransactionFee(networkId, tx0.transaction);
    if (requiredFee0 === undefined) {
      throw new Error("reveal_tx_mass_exceeds_standard");
    }

    if (tx0.feeAmount < requiredFee0) {
      const currentFee = tx0.feeAmount > 0n ? tx0.feeAmount : 1n;
      const scale = 1000000n;
      const scaled = (requiredFee0 * scale + currentFee - 1n) / currentFee;
      const neededFeeRate = Math.max(1.0, feeRate * (Number(scaled) / 1_000_000));
      const effectiveFeeRate = Math.max(feeRate, neededFeeRate);

      const tx1 = await buildReveal(effectiveFeeRate);
      await signReveal(tx1);

      const requiredFee1 = calculateTransactionFee(networkId, tx1.transaction);
      if (requiredFee1 === undefined) {
        throw new Error("reveal_tx_mass_exceeds_standard");
      }
      if (tx1.feeAmount < requiredFee1) {
        throw new Error("reveal_fee_under_minimum");
      }

      const txid1 = await tx1.submit(rpc);
      revealTxids.push(txid1);
    } else {
      const txid0 = await tx0.submit(rpc);
      revealTxids.push(txid0);
    }

    return { commitTxids, revealTxids };
  }

  throw new Error("reveal_timeout");
}

