app.get("/api/wallet/max-sendable", async (req, res) => {
  let rpc: RpcClient | null = null;

  try {
    await ensureKaspaReady(repoRoot);

    const tokenRaw = typeof req.query.token === "string" ? req.query.token.trim() : "";
    const tokenId = tokenRaw ? tokenRaw : "KAS";
    const isKas = tokenId.toUpperCase() === "KAS";
    const isCa = /^CA:/i.test(tokenId);
    const caHex = isCa ? tokenId.slice(3).trim().toLowerCase() : "";

    if (isCa) {
      if (!/^[0-9a-f]{64}$/.test(caHex)) {
        return res.json({ ok: false, reason: "invalid_token", error: "Invalid CA (expected 64 hex)" });
      }
    } else if (!isKas) {
      if (!/^[A-Za-z0-9]{1,16}$/.test(tokenId)) {
        return res.json({ ok: false, reason: "invalid_token", error: "Invalid token ticker" });
      }
    }

    const userId = String((res.locals as any).td_user_id || "").trim();
    if (!userId) {
      return res.status(401).json({ ok: false, reason: "auth_required", login: "/login.html" });
    }

    const store = readWalletStore(repoRoot, userId);
    const active = store.active_id
      ? store.items.find((w) => w.id === store.active_id) ?? null
      : null;

    if (!active) {
      return res.status(409).json({ ok: false, reason: "no_active_wallet", error: "No active wallet selected" });
    }

    const networkId = active.network === "mainnet" ? "mainnet" : "testnet-10";
    rpc = await getSharedRpc(networkId);

    if (isKas) {
      const r = await rpc.getBalanceByAddress({ address: active.address0 });
      let maxSompi = r.balance;

      if (active.wallet_type === "compliance") {
        const cfg = getAppConfig(repoRoot);
        const policy = cnFeePolicyForNetwork(cfg, networkId);
        maxSompi = maxSendableSompiForFeePolicy(maxSompi, policy);
      }

      const whole = maxSompi / 100000000n;
      const frac = maxSompi % 100000000n;
      const fracStr = frac.toString().padStart(8, "0").replace(/0+$/, "");
      const kasStr = fracStr ? `${whole.toString()}.${fracStr}` : whole.toString();

      return res.json({
        ok: true,
        token: "KAS",
        amount: kasStr,
        use_receiver_pays: true
      });
    }

    const out = await kasplexGetAddressTokenList(active.network, active.address0);

    if (isCa) {
      const caHex = tokenId.slice(3).trim().toLowerCase();
      const issues = Array.isArray(out.issue) ? out.issue : [];
      const hit = issues.find((it: any) => String(it?.ca || "").toLowerCase() === caHex);
      const amt = hit && typeof hit.amount === "number" ? hit.amount : (Number(hit?.amount) || 0);

      return res.json({
        ok: true,
        token: `CA:${caHex}`,
        amount: String(amt),
        use_receiver_pays: false
      });
    }

    const val = (out.tokens && Object.prototype.hasOwnProperty.call(out.tokens, tokenId)) ? out.tokens[tokenId] : 0;

    return res.json({
      ok: true,
      token: tokenId,
      amount: String((typeof val === "number") ? val : (Number(val) || 0)),
      use_receiver_pays: false
    });
  } catch (err) {
    return res.status(500).json({
      ok: false,
      reason: "max_sendable_failed",
      error: String(err)
    });
  } finally {
    // keep shared RPC connected
  }
});

